function normalizeCollectionPurpose(value) {
  const text = String(value || "").trim();
  if (COLLECTION_PURPOSE_PROFILES[text]) return text;
  if (/basic|master|db|기본/.test(text)) return "basic_db";
  if (/demand|location|cluster|입지|수요/.test(text)) return "demand_location";
  return "revenue_detail";
}

function collectionPurposeProfile(value) {
  const key = normalizeCollectionPurpose(value);
  return {
    ...(COLLECTION_PURPOSE_PROFILES[key] || COLLECTION_PURPOSE_PROFILES.revenue_detail),
    ...(COLLECTION_PURPOSE_EXECUTION_PROFILES[key] || COLLECTION_PURPOSE_EXECUTION_PROFILES.revenue_detail),
    ...(COLLECTION_PURPOSE_UI_COPY[key] || COLLECTION_PURPOSE_UI_COPY.revenue_detail)
  };
}

function collectionPurposeLabel(value) {
  return collectionPurposeProfile(value).label;
}

function collectionPurposeDefaultRange(value) {
  return collectionPurposeProfile(value).defaultRange || "1-10";
}

function normalizedRankRangeText(value = "") {
  return String(value || "")
    .normalize("NFKC")
    .replace(/[~–—]/g, "-")
    .replace(/\s+/g, "");
}

function rankRangeCountFromText(value = "", fallback = "1-10") {
  const text = normalizedRankRangeText(value);
  const source = (!text || /^(none|skip|없음)$/i.test(text)) ? normalizedRankRangeText(fallback) : text;
  if (!source || /^(none|skip|없음)$/i.test(source)) return 0;
  if (/^(all|전체)$/i.test(source)) return 100;
  const ranks = new Set();
  source.split(",").forEach((part) => {
    const match = part.match(/^(\d{1,3})(?:-(\d{1,3}))?$/);
    if (!match) return;
    const left = Math.max(1, Math.min(100, Math.floor(Number(match[1]))));
    const right = Math.max(1, Math.min(100, Math.floor(Number(match[2] || match[1]))));
    for (let rank = Math.min(left, right); rank <= Math.max(left, right); rank += 1) {
      ranks.add(rank);
    }
  });
  if (!ranks.size && source !== normalizedRankRangeText(fallback)) {
    return rankRangeCountFromText(fallback, "");
  }
  return Math.max(0, Math.min(100, ranks.size));
}

function rankRangePlaceLimitFromText(value = "", fallback = "1-10") {
  return Math.max(0, Math.min(20, rankRangeCountFromText(value, fallback)));
}

function crawlSpeedPresetOptions(purposeValue = els.collectionPurposeInput?.value || "revenue_detail") {
  const purpose = normalizeCollectionPurpose(purposeValue);
  if (purpose === "basic_db") {
    return [
      { key: "top10", label: "1-20위", collectionMode: "precision", range: "1-20", note: "작은 지역 기본정보 확인", collectionPurpose: "basic_db" },
      { key: "top20", label: "1-50위", collectionMode: "precision", range: "1-50", note: "기본정보 권장", collectionPurpose: "basic_db" },
      { key: "top50", label: "1-100위", collectionMode: "precision", range: "1-100", note: "넓은 후보 확보", collectionPurpose: "basic_db" },
      { key: "top100", label: "10-100위", collectionMode: "precision", range: "10-100", note: "상위권 제외 보강", collectionPurpose: "basic_db" }
    ];
  }
  if (purpose === "demand_location") {
    return [
      { key: "top10", label: "1-10위", collectionMode: "precision", range: "1-10", note: "핵심 수요 신호", collectionPurpose: "demand_location" },
      { key: "top20", label: "1-20위", collectionMode: "precision", range: "1-20", note: "수요·입지 권장", collectionPurpose: "demand_location" },
      { key: "top50", label: "1-50위", collectionMode: "precision", range: "1-50", note: "클러스터 확장", collectionPurpose: "demand_location" },
      { key: "top100", label: "1-100위", collectionMode: "precision", range: "1-100", note: "넓은 입지 후보", collectionPurpose: "demand_location" }
    ];
  }
  return [
    { key: "top10", label: "1-5위", collectionMode: "precision", range: "1-5", note: "핵심 경쟁사 정밀", collectionPurpose: "revenue_detail" },
    { key: "top20", label: "1-10위", collectionMode: "precision", range: "1-10", note: "상세 매출 권장", collectionPurpose: "revenue_detail" },
    { key: "top50", label: "1-20위", collectionMode: "precision", range: "1-20", note: "확장 매출 비교", collectionPurpose: "revenue_detail" },
    { key: "top100", label: "10-20위", collectionMode: "precision", range: "10-20", note: "중위권 보강", collectionPurpose: "revenue_detail" }
  ];
}

function currentCrawlFormPayload() {
  const keyword = els.keywordInput?.value?.trim() || "";
  const requestedMode = els.searchModeInput?.value || "keyword";
  const resolvedMode = correctedSearchMode(keyword, requestedMode);
  const collectionMode = "precision";
  const collectionPurpose = normalizeCollectionPurpose(els.collectionPurposeInput?.value || "revenue_detail");
  const purpose = collectionPurposeProfile(collectionPurpose);
  const defaultRange = purpose.defaultRange || collectionPurposeDefaultRange(collectionPurpose);
  const rawDetailRankRanges = els.detailRankRangesInput?.value?.trim() || "";
  const detailRankRanges = /^(none|skip|없음)$/i.test(rawDetailRankRanges) ? defaultRange : (rawDetailRankRanges || defaultRange);
  return {
    keyword,
    checkIn: els.checkInInput?.value || "",
    checkOut: els.checkOutInput?.value || "",
    searchMode: resolvedMode,
    requestedMode,
    productMode: els.productModeInput?.value || "all",
    collectionPurpose,
    collectionMode,
    detailRankRanges,
    rankRangeCount: rankRangeCountFromText(detailRankRanges, defaultRange),
    bookingRangePlaceLimit: purpose.collectWeeklyRange ? rankRangePlaceLimitFromText(detailRankRanges, defaultRange) : 0
  };
}

function selectedCrawlSpeedPresetKey(payload = currentCrawlFormPayload()) {
  if (payload.collectionMode === "fast") return "fast";
  const range = normalizedRankRangeText(payload.detailRankRanges || "");
  return crawlSpeedPresetOptions(payload.collectionPurpose).find((preset) => (
    normalizedRankRangeText(preset.range) === range &&
    (!preset.collectionPurpose || preset.collectionPurpose === normalizeCollectionPurpose(payload.collectionPurpose))
  ))?.key || "";
}

function renderCollectionPurposeRoutePreview(payload = currentCrawlFormPayload(), preview = crawlPreviewMeta(payload)) {
  if (!els.crawlPurposeRoutePreview) return;
  const purpose = collectionPurposeProfile(payload.collectionPurpose);
  const detailText = `${payload.detailRankRanges || purpose.defaultRange}위`;
  const rangeCount = rankRangeCountFromText(payload.detailRankRanges || purpose.defaultRange, purpose.defaultRange);
  const weeklyText = purpose.collectWeeklyRange
    ? `기간 매출 반영 · 상세 확인 ${fmtNumber(payload.bookingRangePlaceLimit || 0)}곳`
    : purpose.excludeText || "기간별 매출 누적 제외";
  els.crawlPurposeRoutePreview.innerHTML = `
    <article>
      <span>DB 반영 위치</span>
      <strong>${escapeHtml(purpose.dbTarget || purpose.label)}</strong>
      <small>${escapeHtml(purpose.dbApplyText || purpose.note || "")}</small>
    </article>
    <article>
      <span>검색 범위</span>
      <strong>${escapeHtml(detailText)}</strong>
      <small>${escapeHtml(`${fmtNumber(rangeCount)}개 순위 · ${purpose.rangeHint || "범위 직접 지정 가능"}`)}</small>
    </article>
    <article>
      <span>수집 깊이</span>
      <strong>${escapeHtml(purpose.depthLabel || purpose.shortLabel || purpose.label)}</strong>
      <small>${escapeHtml(weeklyText)}</small>
    </article>
    <article>
      <span>예상 완료</span>
      <strong>${escapeHtml(formatClockTime(preview.estimatedCompleteAt))}</strong>
      <small>${escapeHtml(formatElapsed(preview.estimatedTotalSeconds || 0))}</small>
    </article>
  `;
}

function activeRunDbRoute(data = state.data || {}) {
  const run = data.run || {};
  const companyMaster = data.companyMaster || {};
  const route = run.collectionDbRoute || companyMaster.dbRoute || data.history?.collectionDbRoute || {};
  const purpose = collectionPurposeProfile(run.collectionPurpose || route.key || "revenue_detail");
  return {
    key: route.key || purpose.key,
    label: route.label || purpose.dbTarget || purpose.label,
    note: route.note || purpose.note || "",
    targets: Array.isArray(route.targets) && route.targets.length ? route.targets : [],
    appliesHistory: route.appliesHistory ?? Boolean(purpose.collectWeeklyRange),
    appliesInventory: route.appliesInventory ?? Boolean(purpose.collectBookingStock),
    appliesDemandLocation: route.appliesDemandLocation ?? (purpose.key === "demand_location")
  };
}

function dbRouteTargetLabel(target = "") {
  const key = String(target || "").trim();
  const labels = {
    "company_master.basic": "마스터 기본정보",
    "company_master.inventory": "상품·가격",
    "company_master.demand_signals": "수요·입지 신호",
    "company_master.keyword_exposure": "노출 순위",
    "history.observations": "매출 관측",
    region_operations: "지역 운영",
    demand_structure: "수요 구조"
  };
  if (labels[key]) return labels[key];
  if (key.startsWith("company_master.")) return `마스터 ${key.replace(/^company_master\./, "").replace(/_/g, " ")}`;
  if (key.startsWith("history.")) return `누적 ${key.replace(/^history\./, "").replace(/_/g, " ")}`;
  return key.replace(/_/g, " ") || "DB 반영";
}

function runDbApplySummaryModel(data = state.data || {}) {
  const run = data.run || {};
  const companyMaster = data.companyMaster || {};
  const history = data.history || {};
  const items = data.availability?.items || [];
  const route = activeRunDbRoute(data);
  const purpose = collectionPurposeProfile(run.collectionPurpose || route.key || "revenue_detail");
  const currentRunCompanies = Number(companyMaster.currentRunCompanies ?? items.length ?? 0);
  const inventoryApplied = Number(companyMaster.inventoryAppliedCompanies ?? (route.appliesInventory ? currentRunCompanies : 0));
  const demandSignalCompanies = Number(companyMaster.demandSignalCompanies ?? (route.appliesDemandLocation ? currentRunCompanies : 0));
  const historyEligible = Boolean(companyMaster.historyEligible ?? route.appliesHistory);
  const historyRows = Number(history.currentRunObservationCount || 0);
  const targetText = route.targets?.length
    ? route.targets.map(dbRouteTargetLabel).join(" · ")
    : purpose.dbApplyText || "DB 반영";
  return {
    run,
    route,
    purpose,
    currentRunCompanies,
    inventoryApplied,
    demandSignalCompanies,
    historyEligible,
    historyRows,
    targetText,
    error: companyMaster.error || ""
  };
}

function runDbApplyStatusModel(model = {}) {
  const route = model.route || {};
  const errors = [];
  const warnings = [];
  const actions = [];
  const currentRunCompanies = Number(model.currentRunCompanies || 0);
  const inventoryApplied = Number(model.inventoryApplied || 0);
  const demandSignalCompanies = Number(model.demandSignalCompanies || 0);
  const historyRows = Number(model.historyRows || 0);

  if (model.error) errors.push("업체 기준값 반영 오류");
  if (!currentRunCompanies) errors.push("업체 기준값 반영 없음");
  if (route.appliesInventory && currentRunCompanies && !inventoryApplied) warnings.push("상품·가격 반영 없음");
  else if (route.appliesInventory && inventoryApplied > 0 && inventoryApplied < currentRunCompanies) warnings.push("상품·가격 일부 반영");
  if (model.historyEligible && !historyRows) warnings.push("매출 누적 관측치 없음");
  if (route.appliesDemandLocation && currentRunCompanies && !demandSignalCompanies) warnings.push("수요·입지 반영 없음");

  if (errors.length) {
    actions.push(
      { label: "업체 관리", section: "database", status: "needs_work" },
      { label: "재수집 설정", section: "collect" }
    );
    return {
      key: "failed",
      tone: "bad",
      label: "반영 실패",
      message: errors.join(" · "),
      actions
    };
  }

  if (warnings.length) {
    actions.push(
      { label: "보정 대상 보기", section: "database", status: "needs_work" },
      { label: "추가 수집", section: "collect" }
    );
    return {
      key: "partial",
      tone: "watch",
      label: "부분 반영",
      message: warnings.join(" · "),
      actions
    };
  }

  actions.push(
    { label: "업체 관리", section: "database" },
    { label: "다음 수집 준비", section: "collect" }
  );
  return {
    key: "complete",
    tone: "good",
    label: "정상 반영",
    message: "선택한 수집 목적 기준으로 필요한 DB 반영이 완료되었습니다.",
    actions
  };
}

function runResultChannelLabels(item = {}) {
  const labels = new Set();
  if (item.url || item.naverUrl || item.naverPlaceUrl || item.bookingUrl || item.naverBookingUrl || item.reservationUrl) {
    labels.add("네이버");
  }
  [
    item.companyChannelExposures,
    item.channelExposures,
    item.companyProfile?.channelExposures,
    item.manualMeta?.channelExposures
  ].forEach((source) => {
    Object.entries(source || {}).forEach(([key, value]) => {
      const label = String(value?.label || key || "").trim();
      const status = String(value?.status || value?.result || value || "").toLowerCase();
      if (label && !/not_found|hidden|none|없음|미노출|fail/.test(status)) labels.add(label);
    });
  });
  [
    ...(item.manualMeta?.otaChannels || []),
    ...(item.manualCorrection?.otaChannels || [])
  ].forEach((value) => {
    const label = String(value || "").trim();
    if (label) labels.add(label);
  });
  return [...labels].filter(Boolean);
}

function runPurposeOutcomeCards(model = {}, status = {}) {
  const data = state.data || {};
  const run = model.run || data.run || {};
  const items = data.availability?.items || [];
  const ranking = data.ranking || {};
  const diag = collectionDiagnosticProfile(items);
  const revenue = summarizeRevenue(items);
  const revenueAmount = finiteNumber(revenue.adjustedRevenue) + finiteNumber(revenue.dayAdjustedRevenue)
    || finiteNumber(revenue.revenue) + finiteNumber(revenue.dayRevenue);
  const soldCount = finiteNumber(revenue.pricedSoldOut)
    + finiteNumber(revenue.missingPriceSoldOut)
    + finiteNumber(revenue.dayPricedSoldOut)
    + finiteNumber(revenue.dayMissingPriceSoldOut);
  const channelCompanyCount = items.filter((item) => runResultChannelLabels(item).length).length;
  const rankCandidateCount = finiteNumber(ranking.total, 0) || finiteNumber(ranking.items?.length, 0) || finiteNumber(model.currentRunCompanies, 0) || items.length;
  const detailRange = run.detailRankRanges ? `${run.detailRankRanges}위` : "범위 미확인";
  const checkedText = diag.checked ? `${fmtNumber(diag.succeeded)}/${fmtNumber(diag.checked)}` : (items.length ? fmtNumber(items.length) : "대기");
  const issueCount = finiteNumber(diag.priceMissing) + finiteNumber(diag.quantityUnclear) + finiteNumber(diag.missingDates);
  const regionKeyword = run.keyword || run.label || "검색 지역";
  if (model.purpose?.key === "basic_db") {
    return {
      key: "basic",
      title: "기본정보 확보 결과",
      note: "순위, 상품 및 상품별 금액, 예약채널을 업체 기준값에 반영합니다.",
      cards: [
        { label: "순위 후보", value: fmtNumber(rankCandidateCount), note: `${detailRange} 수집 범위` },
        { label: "상품·금액", value: model.route?.appliesInventory ? fmtNumber(model.inventoryApplied) : "제외", note: diag.succeeded ? `상세 확인 ${checkedText}` : "상품/가격 최신값 반영" },
        { label: "예약채널", value: channelCompanyCount ? `${fmtNumber(channelCompanyCount)}곳` : "확인 대기", note: "네이버·OTA 노출 신호" },
        { label: "기준값 반영", value: fmtNumber(model.currentRunCompanies), note: status.label || "반영 상태", tone: status.tone || "good" }
      ]
    };
  }
  if (model.purpose?.key === "demand_location") {
    return {
      key: "region",
      title: "지역정보 확보 결과",
      note: "수요, 입지, 클러스터 신호를 지역카드와 수요구조에 반영합니다.",
      cards: [
        { label: "수요 신호", value: model.route?.appliesDemandLocation ? fmtNumber(model.demandSignalCompanies) : "제외", note: "검색수요·트렌드" },
        { label: "입지·클러스터", value: model.demandSignalCompanies ? "반영" : "대기", note: `${regionKeyword} 기준` },
        { label: "지역 범위", value: detailRange, note: "지도/클러스터 연결 범위" },
        { label: "기준값 연결", value: fmtNumber(model.currentRunCompanies), note: status.label || "반영 상태", tone: status.tone || "good" }
      ]
    };
  }
  return {
    key: "detail",
    title: "상세정보 확보 결과",
    note: "요일별 매출, 예약율, 수량, 가격, OTA 정보를 누적합니다.",
    cards: [
      { label: "예약율 표본", value: checkedText, note: "네이버 플레이스 기준" },
      { label: "요일별 매출", value: revenueAmount ? fmtWon(revenueAmount) : fmtNumber(model.historyRows), note: revenueAmount ? `${fmtNumber(soldCount)}개/회 판매 반영` : "매출 관측치" },
      { label: "수량·가격 확인", value: issueCount ? `${fmtNumber(issueCount)}건` : "정상", note: `가격 ${fmtNumber(diag.priceMissing)} · 수량 ${fmtNumber(diag.quantityUnclear)}`, tone: issueCount ? "watch" : "good" },
      { label: "OTA 취합", value: channelCompanyCount ? `${fmtNumber(channelCompanyCount)}곳` : "대기", note: "보조 채널 노출 신호" }
    ]
  };
}

function runPurposeOutcomeHtml(outcome = {}) {
  return `
    <div class="run-purpose-result ${escapeHtml(outcome.key || "")}">
      <div class="run-purpose-result-head">
        <span>수집 목적별 결과</span>
        <strong>${escapeHtml(outcome.title || "수집 결과")}</strong>
        <small>${escapeHtml(outcome.note || "")}</small>
      </div>
      <div class="run-purpose-result-grid">
        ${(outcome.cards || []).map((card) => `
          <article class="${escapeHtml(card.tone || "")}">
            <span>${escapeHtml(card.label || "")}</span>
            <strong>${escapeHtml(String(card.value ?? ""))}</strong>
            <small>${escapeHtml(card.note || "")}</small>
          </article>
        `).join("")}
      </div>
    </div>
  `;
}

function collectionRouteRunCount(company = {}, routeKey = "") {
  const stats = Array.isArray(company.collectionRouteStats)
    ? company.collectionRouteStats
    : Object.values(company.collectionRouteStats || {});
  const stat = stats.find((row) => row?.key === routeKey) || {};
  return Number(stat.runCount || stat.observationCount || 0);
}

function runDbApplyCompanyMatchSets(data = state.data || {}) {
  const items = data.availability?.items || [];
  const ids = new Set();
  const names = new Set();
  items.forEach((item) => {
    if (item.companyId) ids.add(String(item.companyId));
    const name = compactSearchText(item.name || item.primaryName || "");
    if (name) names.add(name);
  });
  return { ids, names, runId: data.run?.runId || "" };
}

function rowMatchesRunApply(row = {}, match = {}) {
  const company = row.company || {};
  if (company.companyId && match.ids?.has(String(company.companyId))) return true;
  if (company.latestCollection?.runId && company.latestCollection.runId === match.runId) return true;
  if (company.lastRunId && company.lastRunId === match.runId) return true;
  const names = [company.primaryName, ...(company.aliases || [])]
    .map((value) => compactSearchText(value || ""))
    .filter(Boolean);
  return names.some((name) => match.names?.has(name));
}

function runDbApplyLinkedQueueModel(model = {}, status = {}) {
  const master = companyMasterSource();
  const allRows = adminDbRows(master);
  const match = runDbApplyCompanyMatchSets(state.data || {});
  const runRows = allRows.filter((row) => rowMatchesRunApply(row, match));
  const decisionMap = new Map(companyDecisionQueueEntries(master).map((entry) => [entry.company?.companyId, entry]));
  const queueRows = runRows.map((row) => {
    const company = row.company || {};
    const metrics = row.metrics || {};
    const entry = decisionMap.get(company.companyId);
    const reasons = [];
    const routeCount = collectionRouteRunCount(company, model.route?.key || "");
    const lowConfidence = adminDbConfidenceMatches(row, "low");
    const decisionActive = adminDbStatusMatches(row, "decision_queue");
    const recrawl = adminDbStatusMatches(row, "recrawl");
    const manual = adminDbStatusMatches(row, "manual");
    const confirmNeeded = metrics.collection?.needsConfirm || adminDbSourceMatches(row, "confirm_needed");
    const revenueWeak = Boolean(entry?.revenueEvidence?.weak);
    if (routeCount >= 2 && (lowConfidence || confirmNeeded || decisionActive || revenueWeak)) reasons.push(`${fmtNumber(routeCount)}회 반복 보강`);
    if (lowConfidence) reasons.push(`수량 신뢰도 ${metrics.confidenceGrade || "낮음"}`);
    if (manual) reasons.push("보정 필요");
    if (recrawl) reasons.push("재수집 필요");
    if (decisionActive) reasons.push("확인 대상 진입");
    if (confirmNeeded) reasons.push(metrics.collection?.note || "확인 수집 필요");
    if (revenueWeak) reasons.push(entry.revenueEvidence.reasons?.[0] || "매출 근거 보강");
    return {
      row,
      entry,
      reasons: [...new Set(reasons)].slice(0, 4),
      routeCount,
      priority: Number(entry?.priority?.score || metrics.priority || 0)
    };
  }).filter((item) => item.reasons.length)
    .sort((a, b) =>
      b.priority - a.priority ||
      b.routeCount - a.routeCount ||
      String(a.row.company?.primaryName || "").localeCompare(String(b.row.company?.primaryName || ""), "ko")
    );
  const lowConfidenceCount = queueRows.filter((item) => adminDbConfidenceMatches(item.row, "low")).length;
  const confirmNeededCount = queueRows.filter((item) => item.row.metrics?.collection?.needsConfirm || adminDbSourceMatches(item.row, "confirm_needed")).length;
  const tone = status.key === "failed" ? "bad" : queueRows.length ? "watch" : "good";
  return {
    tone,
    runRows,
    queueRows,
    lowConfidenceCount,
    confirmNeededCount,
    status,
    summary: runRows.length
      ? `이번 수집 ${fmtNumber(runRows.length)}곳 중 ${fmtNumber(queueRows.length)}곳을 보강 큐와 연결했습니다.`
      : "이번 수집 업체가 아직 업체 기준값과 매칭되지 않았습니다."
  };
}

function runDbApplyLinkedQueueHtml(queue = {}) {
  const rows = queue.queueRows || [];
  const visibleRows = rows.slice(0, 4);
  return `
    <div class="run-apply-linked-queue ${escapeHtml(queue.tone || "watch")}">
      <div class="run-apply-linked-head">
        <div>
          <span>보강 큐 연결</span>
          <strong>${rows.length ? `${fmtNumber(rows.length)}곳 확인 필요` : "연결된 보강 대상 없음"}</strong>
          <small>${escapeHtml(queue.summary || "수집 결과 기준으로 보강 대상을 자동 확인합니다.")}</small>
        </div>
        <mark>${escapeHtml(queue.lowConfidenceCount ? `낮은 신뢰도 ${fmtNumber(queue.lowConfidenceCount)}` : queue.confirmNeededCount ? `확인 수집 ${fmtNumber(queue.confirmNeededCount)}` : "정상")}</mark>
      </div>
      ${visibleRows.length ? `
        <div class="run-apply-linked-list">
          ${visibleRows.map(({ row, reasons }) => {
            const company = row.company || {};
            const metrics = row.metrics || {};
            return `
              <article>
                <div>
                  <strong>${escapeHtml(company.primaryName || "업체명 확인")}</strong>
                  <small>${escapeHtml([row.provinceLabel, row.localityLabel, metrics.rank ? `${fmtNumber(metrics.rank)}위` : "", metrics.collection?.label].filter(Boolean).join(" · "))}</small>
                </div>
                <p>${escapeHtml(reasons.join(" · "))}</p>
              </article>
            `;
          }).join("")}
          ${rows.length > visibleRows.length ? `<small class="run-apply-linked-more">외 ${fmtNumber(rows.length - visibleRows.length)}곳은 업체 관리 필터에서 이어서 확인합니다.</small>` : ""}
        </div>
      ` : `
        <p>이번 실행에서 낮은 신뢰도나 보정 필요 신호가 잡힌 업체는 없습니다.</p>
      `}
      <div class="run-apply-linked-actions">
        <button type="button" data-drawer-tab="admin" data-admin-section-link="database" data-admin-db-status-link="needs_work">처리 필요 보기</button>
        <button type="button" data-drawer-tab="admin" data-admin-section-link="database" data-admin-db-status-link="low_confidence" ${queue.lowConfidenceCount ? "" : "disabled"}>낮은 신뢰도</button>
        <button type="button" data-admin-db-source-link="confirm_needed" ${queue.confirmNeededCount ? "" : "disabled"}>확인 수집 필요</button>
      </div>
    </div>
  `;
}

function renderRunResultApplySummary() {
  if (!isAdminRole() || !els.runApplySummary) return;
  if (!state.data?.run) {
    els.runApplySummary.innerHTML = `
      <div class="run-apply-empty">
        <strong>결과를 선택하면 DB 반영 위치를 표시합니다.</strong>
        <small>기본정보, 상세정보, 지역정보 중 어디에 반영됐는지 확인합니다.</small>
      </div>
    `;
    return;
  }
  const model = runDbApplySummaryModel(state.data);
  const run = model.run || {};
  const status = runDbApplyStatusModel(model);
  const linkedQueue = runDbApplyLinkedQueueModel(model, status);
  const outcome = runPurposeOutcomeCards(model, status);
  const detailText = run.detailRankRanges ? `${run.detailRankRanges}위` : "범위 미확인";
  const dateText = dateRangeLabel(run);
  const historyValue = model.historyEligible ? fmtNumber(model.historyRows) : "제외";
  const historyNote = model.historyEligible ? "이번 결과 매출 관측치" : "이 수집 목적은 매출 누적 제외";
  const demandValue = model.route.appliesDemandLocation ? fmtNumber(model.demandSignalCompanies) : "제외";
  const demandNote = model.route.appliesDemandLocation ? "지역정보 신호 반영" : "지역정보 수집 아님";
  els.runApplySummary.innerHTML = `
    <section class="run-apply-panel ${escapeHtml(model.route.key || "unknown")} ${escapeHtml(status.tone)}">
      <div class="run-apply-head">
        <div>
          <span>이번 수집 반영</span>
          <strong>${escapeHtml(model.purpose.label || model.route.label || "수집 결과")}</strong>
          <small>${escapeHtml([run.keyword || run.label || "", detailText, dateText].filter(Boolean).join(" · "))}</small>
        </div>
        <div class="run-apply-badges">
          <mark class="run-apply-status ${escapeHtml(status.tone)}">${escapeHtml(status.label)}</mark>
          <em>${escapeHtml(model.purpose.dbApplyText || model.targetText || "DB 반영")}</em>
        </div>
      </div>
      ${runPurposeOutcomeHtml(outcome)}
      <div class="run-apply-check ${escapeHtml(status.tone)}">
        <strong>${escapeHtml(status.label)}</strong>
        <span>${escapeHtml(status.message)}</span>
      </div>
      <div class="run-apply-grid">
        <article>
          <span>업체 기준값</span>
          <strong>${fmtNumber(model.currentRunCompanies)}</strong>
          <small>이번 결과 업체 반영</small>
        </article>
        <article>
          <span>상품·가격</span>
          <strong>${model.route.appliesInventory ? fmtNumber(model.inventoryApplied) : "제외"}</strong>
          <small>${model.route.appliesInventory ? "상품/가격 최신값 반영" : "노출 기록 중심"}</small>
        </article>
        <article>
          <span>매출 이력</span>
          <strong>${escapeHtml(historyValue)}</strong>
          <small>${escapeHtml(historyNote)}</small>
        </article>
        <article>
          <span>지역정보</span>
          <strong>${escapeHtml(demandValue)}</strong>
          <small>${escapeHtml(demandNote)}</small>
        </article>
      </div>
      <p>${escapeHtml(model.error ? `업체 기준값 반영 오류: ${model.error}` : model.targetText)}</p>
      <div class="run-apply-actions">
        ${status.actions.map((action) => `
          <button type="button" data-drawer-tab="admin" data-admin-section-link="${escapeHtml(action.section)}"${action.status ? ` data-admin-db-status-link="${escapeHtml(action.status)}"` : ""}>${escapeHtml(action.label)}</button>
        `).join("")}
      </div>
      ${runDbApplyLinkedQueueHtml(linkedQueue)}
    </section>
  `;
}

function updateCrawlSpeedPreview() {
  ensureCrawlControls();
  if (!els.crawlForm) return;
  const payload = currentCrawlFormPayload();
  const preview = crawlPreviewMeta(payload);
  const selectedKey = selectedCrawlSpeedPresetKey(payload);
  const presetOptions = crawlSpeedPresetOptions(payload.collectionPurpose);
  if (els.crawlSpeedPresetRow) {
    els.crawlSpeedPresetRow.querySelectorAll("[data-crawl-speed-preset]").forEach((button) => {
      const preset = presetOptions.find((row) => row.key === button.dataset.crawlSpeedPreset);
      if (preset) {
        button.textContent = preset.label;
        button.title = preset.note || preset.label;
      }
      button.classList.toggle("active", button.dataset.crawlSpeedPreset === selectedKey);
    });
  }
  if (els.crawlSpeedPreview) {
    const purpose = collectionPurposeProfile(payload.collectionPurpose);
    const detailText = `${payload.detailRankRanges || collectionPurposeDefaultRange(payload.collectionPurpose)}위`;
    const rangeCount = rankRangeCountFromText(payload.detailRankRanges || purpose.defaultRange, purpose.defaultRange);
    const safetyText = rangeCount > 20 ? " · 상세 확인은 안전 한도 적용" : "";
    els.crawlSpeedPreview.textContent = `${purpose.shortLabel} · ${detailText} · ${purpose.dbApplyText || "DB 반영"} · 예상 ${formatElapsed(preview.estimatedTotalSeconds)} · 완료 ${formatClockTime(preview.estimatedCompleteAt)}${safetyText}`;
  }
  renderCollectionPurposeRoutePreview(payload, preview);
  renderCrawlReadinessPreview(payload, preview);
  scheduleCrawlEstimatePreviewRefresh(payload);
}

function applyCrawlSpeedPreset(key = "") {
  const currentPurpose = normalizeCollectionPurpose(els.collectionPurposeInput?.value || "revenue_detail");
  const preset = crawlSpeedPresetOptions(currentPurpose).find((row) => row.key === key);
  if (!preset) return;
  if (els.collectionPurposeInput && preset.collectionPurpose) els.collectionPurposeInput.value = preset.collectionPurpose;
  if (els.collectionModeInput) els.collectionModeInput.value = preset.collectionMode;
  if (els.detailRankRangesInput) {
    els.detailRankRangesInput.value = preset.range;
    els.detailRankRangesInput.disabled = false;
  }
  syncCollectionModeInputs();
  updateCrawlSpeedPreview();
  if (els.crawlStatus) {
    const payload = currentCrawlFormPayload();
    const purpose = collectionPurposeProfile(payload.collectionPurpose);
    const detailText = `${payload.detailRankRanges || collectionPurposeDefaultRange(payload.collectionPurpose)}위`;
    els.crawlStatus.textContent = `${purpose.label} · ${detailText} 적용 · ${preset.note}. ${purpose.dbApplyText || "DB 반영"} 기준으로 예상시간을 다시 계산했습니다.`;
  }
}

function syncCollectionModeInputs() {
  if (els.collectionPurposeInput) {
    els.collectionPurposeInput.value = normalizeCollectionPurpose(els.collectionPurposeInput.value || "revenue_detail");
  }
  const purpose = collectionPurposeProfile(els.collectionPurposeInput?.value || "revenue_detail");
  if (els.collectionModeInput) els.collectionModeInput.value = "precision";
  if (els.detailRankRangesInput) {
    els.detailRankRangesInput.disabled = false;
    els.detailRankRangesInput.placeholder = "예: 1-10, 1-50, 1-100";
    if (!els.detailRankRangesInput.value.trim()) els.detailRankRangesInput.value = purpose.defaultRange;
  }
  els.crawlForm?.querySelectorAll("[data-collection-purpose]").forEach((button) => {
    const buttonPurpose = collectionPurposeProfile(button.dataset.collectionPurpose);
    button.classList.toggle("active", buttonPurpose.key === purpose.key);
    button.setAttribute("aria-pressed", buttonPurpose.key === purpose.key ? "true" : "false");
    button.title = `${buttonPurpose.depthLabel || buttonPurpose.label} · ${buttonPurpose.depthNote || buttonPurpose.note || ""}`;
    const title = button.querySelector("strong");
    const summary = button.querySelector("span");
    const helper = button.querySelector("em");
    if (title) title.textContent = buttonPurpose.label;
    if (summary) summary.textContent = buttonPurpose.cardSummary || buttonPurpose.note || "";
    if (helper) helper.textContent = `${buttonPurpose.dbApplyText || buttonPurpose.depthNote || ""} · ${buttonPurpose.rangeHint || buttonPurpose.defaultRange}`;
  });
  updateCrawlSpeedPreview();
}

function selectCollectionPurpose(value = "revenue_detail") {
  const purpose = collectionPurposeProfile(value);
  if (els.collectionPurposeInput) els.collectionPurposeInput.value = purpose.key;
  if (els.detailRankRangesInput) {
    els.detailRankRangesInput.value = purpose.defaultRange;
  }
  syncCollectionModeInputs();
  if (els.crawlStatus) {
    els.crawlStatus.textContent = `${purpose.label} 선택 · ${purpose.status} ${purpose.rangeHint || "순위 범위는 직접 조정할 수 있습니다."}`;
  }
}

function focusAdminCrawlProgress() {
  ensureCrawlControls();
  setActiveTab("admin");
  setAdminPanelSection("collect");
  window.requestAnimationFrame(() => {
    (els.crawlProgress || els.crawlForm)?.scrollIntoView({ behavior: "smooth", block: "start" });
  });
}

