function reportPlatformStats(items = []) {
  const platformNames = ["네이버", "야놀자", "여기어때", "떠나요"];
  const stats = Object.fromEntries(platformNames.map((name) => [name, 0]));
  const otaStats = Object.fromEntries(platformNames.map((name) => [name, 0]));
  let otaCheckCount = 0;
  for (const item of items) {
    const names = platformsForItem(item).map((row) => platformShortName(row.platform));
    const audit = inventoryAuditProfile(item);
    platformNames.forEach((name) => {
      if (names.includes(name)) stats[name] += 1;
    });
    if (audit.otaCheckNeeded) {
      otaCheckCount += 1;
      platformNames.forEach((name) => {
        if (names.includes(name)) otaStats[name] += 1;
      });
    }
  }
  return {
    names: platformNames,
    counts: stats,
    otaCheckCount,
    otaCounts: otaStats,
    missingYeogi: Math.max(0, otaCheckCount - otaStats["여기어때"]),
    missingYanolja: Math.max(0, otaCheckCount - otaStats["야놀자"]),
    missingDdnayo: Math.max(0, otaCheckCount - otaStats["떠나요"])
  };
}

function reportMarketScore({
  rate,
  targetCount,
  itemCount,
  platformGapRatio,
  searchVolume,
  highReservationRate = B2B_HIGH_RESERVATION_RATE,
  lowReservationRate = B2B_LOW_RESERVATION_RATE
}) {
  const targetSignal = itemCount ? Math.min(30, (targetCount / itemCount) * 40) : 0;
  const gapSignal = Math.min(22, platformGapRatio * 26);
  const saleSignal = Number.isFinite(rate)
    ? (rate <= lowReservationRate ? 18 : rate < highReservationRate ? 12 : 5)
    : 8;
  const demandSignal = searchVolume >= 30000 ? 16 : searchVolume >= 10000 ? 10 : searchVolume > 0 ? 6 : 4;
  return Math.max(35, Math.min(94, Math.round(30 + targetSignal + gapSignal + saleSignal + demandSignal)));
}

function b2bCompetitionStrengthScore({
  rate,
  strongCount,
  itemCount,
  salesSampleCount,
  averageRevenue,
  revenueSampleCount,
  searchVolume,
  highReservationRate = B2B_HIGH_RESERVATION_RATE
}) {
  const exposureSignal = itemCount ? Math.min(16, itemCount * 0.9) : 0;
  const strongReservationSignal = itemCount ? Math.min(24, (strongCount / itemCount) * 48) : 0;
  const highRate = Math.max(0.1, finiteNumber(highReservationRate, B2B_HIGH_RESERVATION_RATE));
  const reservationCap = Math.max(0.45, highRate * 1.5);
  const reservationSignal = Number.isFinite(rate)
    ? Math.max(0, Math.min(20, (rate / reservationCap) * 20))
    : (salesSampleCount ? 8 : 4);
  const revenueSignal = revenueSampleCount
    ? Math.max(6, Math.min(16, (finiteNumber(averageRevenue, 0) / 1200000) * 10))
    : 4;
  const demandSignal = searchVolume >= 30000 ? 14 : searchVolume >= 10000 ? 10 : searchVolume > 0 ? 6 : 4;
  return Math.max(35, Math.min(94, Math.round(
    24 + exposureSignal + strongReservationSignal + reservationSignal + revenueSignal + demandSignal
  )));
}

function reportDecision(score, rate, targetCount) {
  if (score >= 75 && targetCount >= 5) {
    return {
      label: "집중 공략",
      tone: "strong",
      summary: "노출은 확인되지만 판매 흐름과 상품 구성 개선 여지가 큽니다."
    };
  }
  if (score >= 62) {
    return {
      label: "선별 공략",
      tone: "watch",
      summary: "상위 업체 중 판매 흐름이 비는 곳부터 선별 접촉이 적합합니다."
    };
  }
  if (Number.isFinite(rate) && rate >= 0.6) {
    return {
      label: "수요 강세",
      tone: "hot",
      summary: "판매율이 높아 신규 영업보다 기존 고객 운영 효율과 가격 점검이 우선입니다."
    };
  }
  return {
    label: "관찰",
    tone: "neutral",
    summary: "즉시 공략보다는 추가 수집과 네이버 기준값 검증이 필요합니다."
  };
}

function b2bMarketDecision(score, rate, strongCount, profile = activeLodgingCategoryProfile()) {
  const categoryProfile = lodgingCategoryProfile(profile);
  const highReservationRate = finiteNumber(categoryProfile.highReservationRate, B2B_HIGH_RESERVATION_RATE);
  if (score >= 78 || strongCount >= 3) {
    return {
      label: "경쟁 강함",
      tone: "hot",
      summary: "상위 경쟁업체의 예약율, 매출 표본, 검색수요가 함께 강한 경쟁권입니다."
    };
  }
  if (score >= 64) {
    return {
      label: "경쟁 활발",
      tone: "strong",
      summary: "상위 노출 경쟁업체의 예약율과 매출 표본을 기준으로 시장 위치를 비교합니다."
    };
  }
  if (Number.isFinite(rate) && rate >= highReservationRate) {
    return {
      label: "수요 강세",
      tone: "hot",
      summary: "경쟁업체 예약율이 높아 가격대와 주말 판매 흐름을 우선 비교합니다."
    };
  }
  return {
    label: "경쟁 관찰",
    tone: "neutral",
    summary: "현재 표본만으로 단정하기보다 경쟁업체 표본과 기간별 수요 변화를 함께 보는 것이 적합합니다."
  };
}

function b2bAnalysisDays(run = {}) {
  return Math.max(1, Math.min(31, bookingDays(run) || DEFAULT_BOOKING_DAYS));
}

function b2bReservationBasisText(run = {}) {
  return `네이버 플레이스 예약 기준 · ${fmtNumber(b2bAnalysisDays(run))}일`;
}

function b2bRevenueBasisText(run = {}) {
  return `네이버 플레이스 예약 가격·판매수량 · ${fmtNumber(b2bAnalysisDays(run))}일 기준`;
}

function b2bReportBasisText(run = {}) {
  return `${b2bDateRangeLabel(run)} · ${b2bReservationBasisText(run)}`;
}

function b2bMarketBriefModel(data = state.data || {}) {
  const run = data.run || {};
  const analysisDays = b2bAnalysisDays(run);
  const categoryProfile = activeLodgingCategoryProfile(data);
  const highReservationRate = finiteNumber(categoryProfile.highReservationRate, B2B_HIGH_RESERVATION_RATE);
  const lowReservationRate = finiteNumber(categoryProfile.lowReservationRate, B2B_LOW_RESERVATION_RATE);
  const items = data.availability?.items || [];
  const stats = data.availability?.stats || {};
  const sales = summarizeSales(items);
  const revenue = summarizeRevenue(items);
  const rate = sales.supply ? sales.sold / sales.supply : finiteNumber(stats.weightedSoldOutRate, NaN);
  const sold = finiteNumber(sales.sold, 0);
  const supply = finiteNumber(sales.supply, 0);
  const remainingSupply = Math.max(0, supply - sold);
  const averageRevenue = finiteNumber(stats.averageAdjustedEstimatedRevenue, 0) || finiteNumber(revenue.adjustedRevenue, 0);
  const revenueSampleCount = finiteNumber(stats.revenueSampleCount, 0);
  const revenueCoverage = Number(stats.revenueCoverageRate);
  const revenueNote = revenueSampleCount
    ? `표본 ${fmtNumber(revenueSampleCount)}개${Number.isFinite(revenueCoverage) ? ` · 커버 ${fmtRate(revenueCoverage)}` : ""}`
    : "표본 대기";
  const searchVolume = (data.regions || []).reduce((sum, region) => sum + finiteNumber(region.traffic?.totalSearchVolume, 0), 0);
  const platformStats = reportPlatformStats(items);
  const platformGapRatio = platformStats.otaCheckCount
    ? (platformStats.missingYeogi + platformStats.missingYanolja + platformStats.missingDdnayo) / (platformStats.otaCheckCount * 3)
    : 0;
  const dayUseCount = items.filter((item) => salesStats(item, "day").supply > 0).length;
  const reservationRows = items
    .map((item, index) => ({ item, index, lodging: salesStats(item, "lodging") }))
    .filter((row) => Number.isFinite(row.lodging.rate));
  const opportunityRows = reservationRows
    .sort((a, b) => a.lodging.rate - b.lodging.rate)
    .slice(0, 5);
  const salesSampleCount = items.filter((item) => Number.isFinite(salesStats(item, "lodging").rate)).length;
  const lowSalesCount = opportunityRows.filter((row) => row.lodging.rate <= lowReservationRate).length;
  const strongSalesCount = reservationRows.filter((row) => row.lodging.rate >= highReservationRate).length;
  const score = b2bCompetitionStrengthScore({
    rate,
    strongCount: strongSalesCount,
    itemCount: items.length,
    salesSampleCount,
    averageRevenue,
    revenueSampleCount,
    searchVolume,
    highReservationRate
  });
  const decision = b2bMarketDecision(score, rate, strongSalesCount, categoryProfile);
  const regions = (data.regions || []).slice(0, 4);
  const topRegion = regions[0] || {};
  return {
    run,
    keyword: activeKeyword(),
    categoryProfile,
    categoryKey: categoryProfile.key,
    categoryLabel: categoryProfile.label,
    unitLabel: categoryProfile.unitLabel,
    highReservationRate,
    lowReservationRate,
    highReservationLabel: b2bHighReservationLabel(categoryProfile),
    lowReservationLabel: b2bLowReservationLabel(categoryProfile),
    range: dateRangeLabel(run),
    longRange: b2bDateRangeLabel(run),
    analysisDays,
    reservationBasisText: b2bReservationBasisText(run),
    revenueBasisText: b2bRevenueBasisText(run),
    reportBasisText: b2bReportBasisText(run),
    itemCount: items.length,
    sold,
    supply,
    remainingSupply,
    salesSampleCount,
    rate,
    averageRevenue,
    revenueSampleCount,
    revenueCoverage,
    revenueNote,
    searchVolume,
    platformStats,
    platformGapRatio,
    dayUseCount,
    dayUseGapCount: Math.max(0, items.length - dayUseCount),
    opportunityRows,
    lowSalesCount,
    strongSalesCount,
    score,
    decision,
    regions,
    topRegion
  };
}

function b2bCompetitiveSnapshotModel(brief = b2bMarketBriefModel()) {
  const rankModel = b2bRankBoardModel();
  const highReservationLabel = brief.highReservationLabel || rankModel.highReservationLabel || b2bHighReservationLabel(brief.categoryProfile);
  const analysisDays = finiteNumber(brief.analysisDays, b2bAnalysisDays(brief.run || {}));
  const topRows = rankModel.rows.slice(0, 6).map((row) => {
    const insight = row.insight || companyRankInsight(row.item, row.index + 1);
    const revenue = finiteNumber(insight.revenue, 0);
    const itemIndex = row.linked ? finiteNumber(row.item.availabilityIndex, -1) : -1;
    const rank = finiteNumber(row.rank, row.index + 1);
    const productText = insight.dayUseKnown ? "숙박+데이" : "숙박 중심";
    const rateText = Number.isFinite(row.rate) ? fmtRate(row.rate) : "판매율 대기";
    const remainingText = row.linked ? `${fmtNumber(row.remaining)}실` : "상세 대기";
    const revenueText = revenue ? fmtWon(revenue) : "매출 표본 대기";
    const meta = row.linked
      ? `${rateText} · 잔여 ${remainingText} · ${productText}`
      : `${row.item.rankingSourceLabel || "네이버 노출"} · 예약 표본 대기`;
    return {
      itemIndex,
      rank,
      rankText: `${fmtNumber(rank)}위`,
      name: row.item.name || "업체명 확인",
      tone: insight.tone || "neutral",
      revenue,
      revenueText,
      rateText,
      remainingText,
      productText,
      meta
    };
  });
  const exposureRows = rankModel.rows.filter((row) => row.rank > 0 && row.rank <= 5);
  const topExposureRows = exposureRows.length ? exposureRows : rankModel.rows.slice(0, 5);
  const revenueRows = topRows.filter((row) => row.revenue > 0);
  const topRevenueTotal = revenueRows.reduce((sum, row) => sum + row.revenue, 0);
  const revenueValues = revenueRows.map((row) => row.revenue).filter((value) => value > 0);
  const revenueAverage = revenueValues.length ? revenueValues.reduce((sum, value) => sum + value, 0) / revenueValues.length : 0;
  const revenueMax = revenueValues.length ? Math.max(...revenueValues) : 0;
  const revenueMin = revenueValues.length ? Math.min(...revenueValues) : 0;
  const revenueLeader = topRows.slice().sort((a, b) => b.revenue - a.revenue)[0] || null;
  const remainingRooms = rankModel.gapRows.reduce((sum, row) => sum + finiteNumber(row.remaining, 0), 0);
  const trend = demandTrendSource();
  const trendStats = demandTrendStats(trend);
  const traffic = demandTrafficAggregate();
  const nextDemand = demandNextMonthProjection(traffic, trend, trendStats);
  const trendLabel = demandTrendLabel();
  let trendTone = "neutral";
  if (trend.reason) {
    trendTone = "watch";
  } else if (trend.hasSeries) {
    if (Number.isFinite(trendStats.recentChange) && trendStats.recentChange >= 0.12) trendTone = "strong";
    else if (Number.isFinite(trendStats.recentChange) && trendStats.recentChange <= -0.12) trendTone = "watch";
    else trendTone = "good";
  }
  const peakLabel = trendStats.peak ? `${trendStats.peak.label} 피크` : "피크 대기";
  const recentLabel = Number.isFinite(trendStats.recentChange)
    ? `최근 3개월 ${formatSignedRate(trendStats.recentChange)}`
    : "최근 추이 대기";
  const trendNote = trend.reason
    ? trend.reason
    : trend.hasSeries
      ? `${peakLabel} · ${recentLabel}`
      : "데이터랩 연동 대기";
  const cards = [
    {
      tone: revenueRows.length ? "strong" : "watch",
      label: "예상 매출 범위",
      value: revenueRows.length ? `평균 ${fmtWon(revenueAverage)}` : "표본 대기",
      note: revenueRows.length ? `최고 ${fmtWon(revenueMax)} · 최저 ${fmtWon(revenueMin)} · ${fmtNumber(analysisDays)}일 기준` : "가격·수량 표본 필요"
    },
    {
      tone: "neutral",
      label: "노출 1~5위",
      value: fmtNumber(topExposureRows.length),
      note: topRows[0] ? `${topRows[0].name} ${topRows[0].rankText}` : "순위 표본 대기"
    },
    {
      tone: rankModel.hotRows.length ? "hot" : "neutral",
      label: highReservationLabel,
      value: fmtNumber(rankModel.hotRows.length),
      note: brief.reservationBasisText || "네이버 플레이스 예약 기준"
    },
    {
      tone: nextDemand.tone || trendTone,
      label: nextDemand.label || "다음달 예상 검색량",
      value: nextDemand.value,
      note: nextDemand.note
    }
  ];
  const insights = [
    {
      label: "예상 매출",
      value: revenueRows.length
        ? `${fmtNumber(revenueRows.length)}개 업체의 ${fmtNumber(analysisDays)}일 기준 예상 매출 평균·최고·최저를 비교합니다.`
        : "상위 업체의 가격·수량 표본이 확보되면 경쟁 매출을 계산합니다."
    },
    {
      label: "노출 해석",
      value: topRows[0]
        ? `${topRows[0].rankText} ${topRows[0].name} 기준으로 상위 노출 경쟁권을 비교합니다.`
        : "네이버 노출 표본을 먼저 확인해야 합니다."
    },
    {
      label: "예약율 해석",
      value: rankModel.hotRows.length
        ? `${highReservationLabel} 업체 ${fmtNumber(rankModel.hotRows.length)}곳을 경쟁 기준으로 봅니다.`
        : `예약율 산출 표본 (네이버 플레이스 기준) ${fmtNumber(rankModel.linkedRows.length)}곳을 기준으로 비교합니다.`
    },
    {
      label: "검색량 보정",
      value: nextDemand.detailText || trendNote
    }
  ];
  return {
    rankModel,
    rows: topRows,
    cards,
    insights,
    revenueRows,
    revenueLeader,
    topRevenueTotal,
    revenueAverage,
    revenueMax,
    revenueMin,
    remainingRooms,
    trendLabel,
    trendNote,
    nextDemand,
    range: brief.range
  };
}

function b2bRevenueBenchmarkModel(brief = b2bMarketBriefModel(), data = state.data || {}) {
  const items = data.availability?.items || [];
  const run = brief.run || data.run || {};
  const analysisDays = finiteNumber(brief.analysisDays, b2bAnalysisDays(run));
  const revenueBasisText = brief.revenueBasisText || b2bRevenueBasisText(run);
  const rows = items.map((item, index) => {
    const profile = preciseRevenueProfile(item);
    const revenue = finiteNumber(profile.totalAdjustedRevenue, 0) || finiteNumber(profile.totalRevenue, 0);
    const baseRevenue = finiteNumber(profile.totalRevenue, 0);
    const gapRevenue = finiteNumber(profile.totalMissingPriceEstimatedRevenue, 0);
    const precision = profile.precision || {};
    const lodging = profile.lodging || {};
    const dayUse = profile.dayUse || {};
    const flow = salesFlowProfile(item);
    const status = collectionStatusProfile(item);
    const rank = finiteNumber(item.rank || item.overallRank || index + 1, index + 1);
    const itemIndex = finiteNumber(item.availabilityIndex, index);
    const avgPrice = finiteNumber(lodging.avgSoldUnitPrice, 0) || finiteNumber(dayUse.avgSoldUnitPrice, 0);
    const priced = finiteNumber(precision.priced, 0);
    const missing = finiteNumber(precision.missing, 0);
    const soldQuantity = finiteNumber(precision.soldQuantity, priced + missing);
    const offlineQuantity = finiteNumber(status.offlineQuantity, 0);
    const blockedQuantity = finiteNumber(status.structuralBlockedQuantity, 0);
    return {
      item,
      index,
      itemIndex,
      rank,
      name: item.name || "업체명 확인",
      revenue,
      baseRevenue,
      gapRevenue,
      avgPrice,
      precision,
      grade: precision.grade || "",
      tone: precision.tone || "neutral",
      priced,
      missing,
      soldQuantity,
      offlineQuantity,
      blockedQuantity,
      offlineEstimated: Boolean(status.offlineEstimated || offlineQuantity > 0),
      flow,
      lodging,
      dayUse
    };
  });
  const revenueRows = rows.filter((row) => row.revenue > 0);
  const precisionRows = rows.filter((row) => row.soldQuantity > 0 || row.revenue > 0);
  const revenueTotal = revenueRows.reduce((sum, row) => sum + row.revenue, 0);
  const baseTotal = revenueRows.reduce((sum, row) => sum + row.baseRevenue, 0);
  const gapRevenueTotal = revenueRows.reduce((sum, row) => sum + row.gapRevenue, 0);
  const averageRevenue = revenueRows.length ? revenueTotal / revenueRows.length : finiteNumber(brief.averageRevenue, 0);
  const revenueMax = revenueRows.length ? Math.max(...revenueRows.map((row) => row.revenue)) : 0;
  const revenueMin = revenueRows.length ? Math.min(...revenueRows.map((row) => row.revenue)) : 0;
  const pricedTotal = precisionRows.reduce((sum, row) => sum + row.priced, 0);
  const missingTotal = precisionRows.reduce((sum, row) => sum + row.missing, 0);
  const offlineRows = rows.filter((row) => row.offlineEstimated || row.offlineQuantity > 0);
  const offlineQuantityTotal = rows.reduce((sum, row) => sum + finiteNumber(row.offlineQuantity, 0), 0);
  const blockedQuantityTotal = rows.reduce((sum, row) => sum + finiteNumber(row.blockedQuantity, 0), 0);
  const soldQuantity = pricedTotal + missingTotal;
  const priceCoverage = soldQuantity ? pricedTotal / soldQuantity : NaN;
  const highPrecisionRows = precisionRows.filter((row) => ["A", "B"].includes(String(row.grade).toUpperCase()));
  const precisionScore = precisionRows.length
    ? Math.round(precisionRows.reduce((sum, row) => sum + finiteNumber(row.precision.score, 0), 0) / precisionRows.length)
    : 0;
  const topRows = revenueRows
    .slice()
    .sort((a, b) => b.revenue - a.revenue || a.rank - b.rank)
    .slice(0, 4);
  const benchmarkRows = topRows.length ? topRows : rows.slice(0, 4);
  const flow = aggregateFlowProfiles(items);
  const weekend = combineFlowMetrics([flow.friday, flow.saturday, flow.sunday]);
  const weekdayGap = Number.isFinite(weekend.rate) && Number.isFinite(flow.weekday.rate)
    ? weekend.rate - flow.weekday.rate
    : NaN;
  const decision = revenueRows.length >= Math.max(2, Math.ceil(items.length * 0.2))
    ? { tone: "strong", label: "매출 비교 가능", summary: "가격과 판매 수량이 연결된 표본으로 경쟁업체 매출 수준을 비교할 수 있습니다." }
    : precisionRows.length
      ? { tone: "watch", label: "표본 보완 필요", summary: "일부 업체는 가격 또는 수량 표본이 부족하므로 매출은 보조 지표로 해석합니다." }
      : { tone: "neutral", label: "매출 표본 대기", summary: "매출 산출에 필요한 가격과 판매 수량 표본이 더 필요합니다." };
  const cards = [
    {
      label: "예상 평균 매출",
      value: averageRevenue ? fmtWon(averageRevenue) : "대기",
      note: revenueRows.length ? `${fmtNumber(revenueRows.length)}개 표본 평균 · ${revenueBasisText}` : "가격·수량 표본 필요",
      tone: revenueRows.length ? "strong" : "watch"
    },
    {
      label: "최고 매출",
      value: revenueMax ? fmtWon(revenueMax) : "대기",
      note: topRows[0] ? `${topRows[0].name} · ${fmtNumber(topRows[0].rank)}위 · ${fmtNumber(analysisDays)}일 기준` : "상위 표본 대기",
      tone: revenueMax ? "hot" : "neutral"
    },
    {
      label: "최저 매출",
      value: revenueMin ? fmtWon(revenueMin) : "대기",
      note: revenueRows.length ? `${fmtNumber(revenueRows.length)}개 표본 중 최소 · ${fmtNumber(analysisDays)}일 기준` : "표본 대기",
      tone: revenueMin ? "neutral" : "watch"
    },
    {
      label: "오프라인 판매 추정",
      value: offlineQuantityTotal ? `${fmtNumber(offlineQuantityTotal)}개` : "특이 없음",
      note: offlineQuantityTotal
        ? `${fmtNumber(offlineRows.length)}곳 · 총량 감소/미오픈/차단 신호`
        : "총량 감소 신호 없음",
      tone: offlineQuantityTotal ? "watch" : "good"
    },
    {
      label: "주말 판매압력",
      value: Number.isFinite(weekend.rate) ? fmtRate(weekend.rate) : "대기",
      note: Number.isFinite(weekdayGap) ? `평일 대비 ${formatSignedRate(weekdayGap)}` : "요일 표본 필요",
      tone: Number.isFinite(weekend.rate) && weekend.rate >= 0.65 ? "hot" : "neutral"
    }
  ];
  const guideRows = [
    {
      tone: revenueRows.length ? "strong" : "watch",
      label: "매출 기준",
      value: `${fmtNumber(analysisDays)}일`,
      note: revenueRows.length
        ? `매출 표본 ${fmtNumber(revenueRows.length)}곳 · 네이버 예약 기준`
        : "가격·판매수량 표본 확보 필요"
    },
    {
      tone: missingTotal ? "watch" : "good",
      label: "가격 보완",
      value: missingTotal ? `${fmtNumber(missingTotal)}건` : "낮음",
      note: missingTotal
        ? `확인 ${fmtNumber(pricedTotal)}건 · 일부 평균가 보정`
        : "가격 보완 영향 낮음"
    },
    {
      tone: offlineQuantityTotal ? "watch" : "good",
      label: "오프라인 참고",
      value: offlineQuantityTotal ? `${fmtNumber(offlineQuantityTotal)}개` : "특이 없음",
      note: offlineQuantityTotal
        ? `운영 축소/상시 차단 ${fmtNumber(blockedQuantityTotal)}개 포함 가능`
        : "실판매 외 총량 감소 신호가 낮음"
    },
    {
      tone: "good",
      label: "요일 해석",
      value: Number.isFinite(flow.weekday.rate) ? fmtRate(flow.weekday.rate) : "대기",
      note: "평일·금요일·토요일·일요일 판매 흐름을 함께 반영"
    }
  ];
  return {
    rows,
    revenueRows,
    precisionRows,
    topRows,
    benchmarkRows,
    revenueTotal,
    averageRevenue,
    revenueMax,
    revenueMin,
    priceCoverage,
    pricedTotal,
    missingTotal,
    gapRevenueTotal,
    offlineRows,
    offlineQuantityTotal,
    blockedQuantityTotal,
    analysisDays,
    revenueBasisText,
    precisionScore,
    highPrecisionRows,
    flow,
    weekend,
    weekdayGap,
    decision,
    cards,
    guideRows
  };
}

function b2bMyLodgeAccountToken() {
  return compactSearchText(state.session?.memberId || state.session?.username || "guest") || "guest";
}

function b2bMyLodgeStorageKey() {
  return `${B2B_MY_LODGE_STORAGE_PREFIX}:${b2bMyLodgeAccountToken()}:account`;
}

function b2bMyLodgeStoredObject(key = "") {
  if (typeof localStorage === "undefined" || !key) return {};
  try {
    const raw = localStorage.getItem(key);
    const parsed = raw ? JSON.parse(raw) : {};
    return parsed && typeof parsed === "object" ? parsed : {};
  } catch {
    return {};
  }
}

function b2bMyLodgePersistentStoreValue(value = {}) {
  if (!value || typeof value !== "object" || !b2bMyLodgeHasStructuredShape(value)) return {};
  return {
    ...value,
    draft: {}
  };
}

function b2bMyLodgeLegacyStorageKeys() {
  if (typeof localStorage === "undefined") return [];
  const account = b2bMyLodgeAccountToken();
  const currentKey = b2bMyLodgeStorageKey();
  const prefix = `${B2B_MY_LODGE_STORAGE_PREFIX}:${account}:`;
  try {
    return Array.from({ length: localStorage.length }, (_, index) => localStorage.key(index))
      .filter((key) => key && key.startsWith(prefix) && key !== currentKey)
      .sort();
  } catch {
    return [];
  }
}

function clearB2BMyLodgeLegacyStorageKeys(keys = b2bMyLodgeLegacyStorageKeys()) {
  if (typeof localStorage === "undefined") return;
  keys.forEach((key) => {
    try {
      localStorage.removeItem(key);
    } catch {
      // Ignore browser storage failures; the current account key remains authoritative.
    }
  });
}

function b2bMyLodgeMergeStoredValues(primary = {}, legacyValues = []) {
  const stores = [primary, ...legacyValues].map((value) => b2bMyLodgeStoreFromValue(value));
  const primaryStore = stores[0] || { draft: {}, interestLodges: [] };
  const draft = b2bMyLodgeDraftHasInput(primaryStore.draft)
    ? primaryStore.draft
    : (stores.find((store) => b2bMyLodgeDraftHasInput(store.draft))?.draft || {});
  const seen = new Set();
  const interestLodges = [];
  stores.forEach((store) => {
    (store.interestLodges || []).forEach((lodge) => {
      const normalized = b2bNormalizeInterestLodge(lodge);
      if (!b2bMyLodgeDraftHasInput(normalized)) return;
      const key = compactSearchText(normalized.lodgingName) || normalized.id || b2bStableInterestLodgeId(normalized);
      if (seen.has(key)) return;
      seen.add(key);
      interestLodges.push(normalized);
    });
  });
  return {
    version: 2,
    draft,
    interestLodges: interestLodges.slice(0, B2B_INTEREST_LODGE_LIMIT)
  };
}

function readB2BMyLodgeStoredValue() {
  const key = b2bMyLodgeStorageKey();
  const memoryDraft = state.b2bMyLodgeDraft?.key === key ? state.b2bMyLodgeDraft.values : null;
  if (typeof localStorage === "undefined") return memoryDraft || {};
  try {
    if (memoryDraft) return memoryDraft;
    const primary = b2bMyLodgePersistentStoreValue(b2bMyLodgeStoredObject(key));
    const legacyKeys = b2bMyLodgeLegacyStorageKeys();
    const legacyValues = legacyKeys
      .map((legacyKey) => b2bMyLodgePersistentStoreValue(b2bMyLodgeStoredObject(legacyKey)))
      .filter((value) => value && Object.keys(value).length);
    if (!legacyValues.length) return Object.keys(primary).length ? primary : {};
    const merged = b2bMyLodgeMergeStoredValues(Object.keys(primary).length ? primary : {}, legacyValues);
    localStorage.setItem(key, JSON.stringify({ ...merged, draft: {} }));
    clearB2BMyLodgeLegacyStorageKeys(legacyKeys);
    return { ...merged, draft: {} };
  } catch {
    return memoryDraft || {};
  }
}

function readB2BMyLodgeStore() {
  return b2bMyLodgeStoreFromValue(readB2BMyLodgeStoredValue());
}

function readB2BMyLodgeDraft() {
  return readB2BMyLodgeStore().draft || {};
}

function readB2BInterestLodges() {
  return readB2BMyLodgeStore().interestLodges || [];
}

function b2bInterestLodgeFingerprint(interestLodges = []) {
  return JSON.stringify(
    (Array.isArray(interestLodges) ? interestLodges : [])
      .map((lodge) => b2bNormalizeInterestLodge(lodge))
      .map((lodge) => ({
        id: lodge.id,
        lodgingName: lodge.lodgingName,
        roomCount: lodge.roomCount,
        roomType: lodge.roomType,
        dayUseCount: lodge.dayUseCount,
        weekdayPrice: lodge.weekdayPrice,
        fridayPrice: lodge.fridayPrice,
        saturdayPrice: lodge.saturdayPrice,
        sundayPrice: lodge.sundayPrice,
        roomSegments: lodge.roomSegments,
        facilities: lodge.facilities,
        naverConnected: lodge.naverConnected,
        otaConnected: lodge.otaConnected,
        collectionSource: lodge.collectionSource,
        collectionPrecisionGrade: lodge.collectionPrecisionGrade,
        collectionPrecisionLabel: lodge.collectionPrecisionLabel,
        collectionPrecisionScore: lodge.collectionPrecisionScore,
        collectionPrecisionReasons: lodge.collectionPrecisionReasons,
        collectionPrecisionWarnings: lodge.collectionPrecisionWarnings,
        collectionBasis: lodge.collectionBasis,
        verifiedCorrectionApplied: lodge.verifiedCorrectionApplied,
        verifiedLodgingBasisTotal: lodge.verifiedLodgingBasisTotal,
        verifiedDayUseBasisTotal: lodge.verifiedDayUseBasisTotal,
        verifiedCorrectionLabel: lodge.verifiedCorrectionLabel,
        verifiedCorrectionSource: lodge.verifiedCorrectionSource,
        verifiedCorrectionNote: lodge.verifiedCorrectionNote,
        verifiedCorrectionUpdatedAt: lodge.verifiedCorrectionUpdatedAt,
        verifiedRoomSegments: lodge.verifiedRoomSegments,
        manualAdjusted: lodge.manualAdjusted,
        registeredAt: lodge.registeredAt
      }))
  );
}

async function syncB2BInterestLodgesToServer(interestLodges = readB2BInterestLodges()) {
  if (isAdminRole() || isAdminUserViewMode()) return null;
  state.b2bInterestLodgeSyncing = true;
  state.b2bInterestLodgeSyncError = "";
  try {
    const result = await fetchJson("/api/member/interest-lodges", {
      method: "PUT",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ interestLodges })
    });
    const store = readB2BMyLodgeStore();
    persistB2BMyLodgeStore(
      { ...store, interestLodges: result.interestLodges || [] },
      { syncInterestLodges: false }
    );
    state.b2bInterestLodgeServerLoaded = true;
    return result;
  } catch (error) {
    state.b2bInterestLodgeSyncError = error.message || "관심숙소 계정 저장에 실패했습니다.";
    return null;
  } finally {
    state.b2bInterestLodgeSyncing = false;
    if (!isAdminRole() && !isAdminUserViewMode() && document.querySelector(".b2b-my-lodge-board")) {
      renderReport();
    }
  }
}

async function loadB2BInterestLodgesFromServer() {
  if (isAdminRole() || isAdminUserViewMode()) {
    state.b2bInterestLodgeServerLoaded = false;
    state.b2bInterestLodgeSyncError = "";
    return;
  }
  const localStore = readB2BMyLodgeStore();
  try {
    const result = await fetchJson("/api/member/interest-lodges");
    const remoteStore = b2bMyLodgeStoreFromValue({
      version: 2,
      draft: {},
      interestLodges: result.interestLodges || []
    });
    const merged = b2bMyLodgeMergeStoredValues(remoteStore, [localStore]);
    const nextStore = {
      version: 2,
      draft: localStore.draft || {},
      interestLodges: merged.interestLodges || []
    };
    persistB2BMyLodgeStore(nextStore, { syncInterestLodges: false });
    state.b2bInterestLodgeServerLoaded = true;
    state.b2bInterestLodgeSyncError = "";
    if (b2bInterestLodgeFingerprint(nextStore.interestLodges) !== b2bInterestLodgeFingerprint(remoteStore.interestLodges)) {
      await syncB2BInterestLodgesToServer(nextStore.interestLodges);
    }
  } catch (error) {
    state.b2bInterestLodgeServerLoaded = false;
    state.b2bInterestLodgeSyncError = error.message || "관심숙소를 계정에서 불러오지 못했습니다.";
  }
}

function b2bMyLodgeNumber(value) {
  const number = optionalNumber(value);
  return Number.isFinite(number) ? Math.max(0, number) : 0;
}

function b2bMyLodgeInputNumberText(value) {
  const number = b2bMyLodgeNumber(value);
  return number > 0 ? fmtNumber(Math.round(number)) : "";
}

function formatB2BWonInput(input) {
  if (!input) return;
  const digits = String(input.value || "").replace(/[^\d]/g, "");
  input.value = digits ? Number(digits).toLocaleString("ko-KR") : "";
}

const B2B_MY_LODGE_SEGMENT_LIMIT = 8;
const B2B_INTEREST_LODGE_LIMIT = 2;
const B2B_MY_LODGE_PRICE_KEYS = ["weekdayPrice", "fridayPrice", "saturdayPrice", "sundayPrice"];
const B2B_MY_LODGE_COLLECTION_META_KEYS = [
  "collectedAt",
  "collectionRunId",
  "collectionSource",
  "collectionStatus",
  "collectionPrecisionGrade",
  "collectionPrecisionLabel",
  "collectionPrecisionTone",
  "collectionPrecisionScore",
  "collectionPrecisionReasons",
  "collectionPrecisionWarnings",
  "collectionBasis",
  "verifiedCorrectionApplied",
  "verifiedLodgingBasisTotal",
  "verifiedDayUseBasisTotal",
  "verifiedCorrectionLabel",
  "verifiedCorrectionSource",
  "verifiedCorrectionNote",
  "verifiedCorrectionUpdatedAt",
  "verifiedRoomSegments",
  "manualAdjusted",
  "manualAdjustedAt",
  "searchRegion",
  "addressRegion",
  "regionBoundaryStatus",
  "regionBoundaryLabel",
  "regionBoundaryDetail",
  "outsideSearchRegion",
  "address"
];

function b2bMyLodgeBlankSegment() {
  return {
    type: "",
    count: "",
    weekdayPrice: "",
    fridayPrice: "",
    saturdayPrice: "",
    sundayPrice: ""
  };
}

function b2bMyLodgeCleanSegment(row = {}) {
  return {
    type: String(row.type || row.roomType || "").trim().slice(0, 80),
    count: Math.round(b2bMyLodgeNumber(row.count ?? row.roomCount)),
    weekdayPrice: b2bMyLodgeNumber(row.weekdayPrice),
    fridayPrice: b2bMyLodgeNumber(row.fridayPrice),
    saturdayPrice: b2bMyLodgeNumber(row.saturdayPrice),
    sundayPrice: b2bMyLodgeNumber(row.sundayPrice)
  };
}

function b2bMyLodgeSegmentHasInput(row = {}) {
  return Boolean(
    String(row.type || "").trim() ||
    b2bMyLodgeNumber(row.count) > 0 ||
    B2B_MY_LODGE_PRICE_KEYS.some((key) => b2bMyLodgeNumber(row[key]) > 0)
  );
}

function b2bMyLodgeSegmentRows(draft = {}) {
  return (Array.isArray(draft.roomSegments) ? draft.roomSegments : [])
    .map((row) => b2bMyLodgeCleanSegment(row))
    .filter((row) => b2bMyLodgeSegmentHasInput(row))
    .slice(0, B2B_MY_LODGE_SEGMENT_LIMIT);
}

function b2bMyLodgeLegacySegment(draft = {}) {
  const row = b2bMyLodgeCleanSegment({
    type: draft.roomType,
    count: draft.roomCount,
    weekdayPrice: draft.weekdayPrice,
    fridayPrice: draft.fridayPrice,
    saturdayPrice: draft.saturdayPrice,
    sundayPrice: draft.sundayPrice
  });
  return b2bMyLodgeSegmentHasInput(row) ? row : null;
}

function b2bMyLodgeSegmentInputRows(draft = {}) {
  if (Array.isArray(draft.roomSegments) && draft.roomSegments.length) {
    return draft.roomSegments
      .map((row) => b2bMyLodgeCleanSegment(row))
      .slice(0, B2B_MY_LODGE_SEGMENT_LIMIT);
  }
  const legacy = b2bMyLodgeLegacySegment(draft);
  return legacy ? [legacy] : [];
}

function b2bMyLodgeCollectionTextList(value, limit = 5) {
  return (Array.isArray(value) ? value : String(value || "").split(/\s*[,·]\s*/))
    .map((item) => String(item || "").trim())
    .filter(Boolean)
    .filter((item, index, list) => list.findIndex((other) => compactSearchText(other) === compactSearchText(item)) === index)
    .slice(0, limit);
}

function b2bMyLodgeCollectionMetadata(draft = {}) {
  return B2B_MY_LODGE_COLLECTION_META_KEYS.reduce((acc, key) => {
    if (!Object.prototype.hasOwnProperty.call(draft, key)) return acc;
    if (key === "collectionPrecisionReasons" || key === "collectionPrecisionWarnings") {
      acc[key] = b2bMyLodgeCollectionTextList(draft[key], 5);
    } else if (key === "verifiedRoomSegments") {
      const rows = b2bMyLodgeSegmentInputRows({ roomSegments: draft[key] })
        .filter((row) => b2bMyLodgeSegmentHasInput(row));
      if (rows.length) acc[key] = rows;
    } else if (key === "manualAdjusted" || key === "outsideSearchRegion" || key === "verifiedCorrectionApplied") {
      acc[key] = Boolean(draft[key]);
    } else if (key === "collectionPrecisionScore") {
      const score = Math.round(b2bMyLodgeNumber(draft[key]));
      if (score > 0) acc[key] = Math.min(100, score);
    } else if (key === "verifiedLodgingBasisTotal" || key === "verifiedDayUseBasisTotal") {
      const total = Math.round(b2bMyLodgeNumber(draft[key]));
      if (total > 0) acc[key] = total;
    } else {
      acc[key] = String(draft[key] || "").trim();
    }
    return acc;
  }, {});
}

function b2bMyLodgeComparableSignature(value = {}) {
  const rows = b2bMyLodgeSegmentInputRows(value)
    .filter((row) => b2bMyLodgeSegmentHasInput(row))
    .map((row) => ({
      type: compactSearchText(row.type),
      count: Math.round(b2bMyLodgeNumber(row.count)),
      weekdayPrice: Math.round(b2bMyLodgeNumber(row.weekdayPrice)),
      fridayPrice: Math.round(b2bMyLodgeNumber(row.fridayPrice)),
      saturdayPrice: Math.round(b2bMyLodgeNumber(row.saturdayPrice)),
      sundayPrice: Math.round(b2bMyLodgeNumber(row.sundayPrice))
    }));
  return JSON.stringify({
    lodgingName: compactSearchText(value.lodgingName || ""),
    roomCount: Math.round(b2bMyLodgeNumber(value.roomCount)),
    dayUseCount: Math.round(b2bMyLodgeNumber(value.dayUseCount)),
    facilities: compactSearchText(value.facilities || ""),
    naverConnected: Boolean(value.naverConnected),
    otaConnected: Boolean(value.otaConnected),
    rows
  });
}

function b2bMyLodgeWasManuallyAdjusted(previous = {}, next = {}) {
  if (!previous.collectionSource && !previous.collectedAt) return false;
  return b2bMyLodgeComparableSignature(previous) !== b2bMyLodgeComparableSignature(next);
}

function b2bMyLodgeCollectionPrecisionInfo(draft = {}) {
  const label = String(draft.collectionPrecisionLabel || "").trim();
  const source = String(draft.collectionSource || "").trim();
  const visible = Boolean(label || source || draft.manualAdjusted);
  return {
    visible,
    grade: String(draft.collectionPrecisionGrade || "").trim(),
    label: label || (source ? "자동수집값" : draft.manualAdjusted ? "수동 보정값" : ""),
    tone: String(draft.collectionPrecisionTone || (draft.manualAdjusted ? "strong" : "neutral")).trim() || "neutral",
    score: Math.round(b2bMyLodgeNumber(draft.collectionPrecisionScore)),
    reasons: b2bMyLodgeCollectionTextList(draft.collectionPrecisionReasons, 4),
    warnings: b2bMyLodgeCollectionTextList(draft.collectionPrecisionWarnings, 3),
    basis: String(draft.collectionBasis || draft.collectionStatus || "").trim(),
    manualAdjusted: Boolean(draft.manualAdjusted),
    collectedAt: draft.collectedAt || "",
    manualAdjustedAt: draft.manualAdjustedAt || ""
  };
}

function b2bMyLodgeDraftHasInput(draft = {}) {
  if (!draft || typeof draft !== "object") return false;
  const roomSegments = b2bMyLodgeSegmentInputRows(draft).filter((row) => b2bMyLodgeSegmentHasInput(row));
  return Boolean(
    String(draft.lodgingName || "").trim() ||
    b2bMyLodgeNumber(draft.roomCount) > 0 ||
    String(draft.roomType || "").trim() ||
    b2bMyLodgeNumber(draft.dayUseCount) > 0 ||
    b2bMyLodgeAveragePrice(draft) > 0 ||
    roomSegments.length > 0 ||
    String(draft.facilities || "").trim()
  );
}

function b2bStableInterestLodgeId(lodge = {}) {
  const existing = String(lodge.id || "").trim();
  if (existing) return existing;
  const basis = compactSearchText([
    lodge.lodgingName,
    lodge.savedAt,
    lodge.collectedAt,
    lodge.roomCount,
    lodge.roomType
  ].filter(Boolean).join("-"));
  return `interest-${(basis || "lodge").slice(0, 72)}`;
}

function b2bInterestLodgeMatchKey(lodge = {}) {
  return compactSearchText([
    lodge.id,
    lodge.lodgingName,
    lodge.savedAt,
    lodge.collectedAt,
    lodge.roomCount,
    lodge.roomType
  ].filter(Boolean).join("|"));
}

function b2bInterestLodgeTargetIndex(interestLodges = [], lodgeId = "", fallbackIndex = -1) {
  const id = String(lodgeId || "").trim();
  const normalizedId = compactSearchText(id);
  const index = interestLodges.findIndex((lodge) => (
    String(lodge.id || "").trim() === id ||
    String(b2bStableInterestLodgeId(lodge) || "").trim() === id ||
    compactSearchText(lodge.id || "") === normalizedId ||
    compactSearchText(b2bStableInterestLodgeId(lodge)) === normalizedId ||
    b2bInterestLodgeMatchKey(lodge) === normalizedId
  ));
  if (index >= 0) return index;
  const number = Number(fallbackIndex);
  if (Number.isInteger(number) && number >= 0 && number < interestLodges.length) return number;
  return -1;
}

function b2bNewInterestLodgeId() {
  return `interest-${Date.now().toString(36)}-${Math.random().toString(36).slice(2, 8)}`;
}

function b2bNormalizeInterestLodge(lodge = {}) {
  const roomSegments = b2bMyLodgeSegmentInputRows(lodge)
    .filter((row) => b2bMyLodgeSegmentHasInput(row))
    .slice(0, B2B_MY_LODGE_SEGMENT_LIMIT);
  const segmentTotal = roomSegments.reduce((sum, row) => sum + Math.round(b2bMyLodgeNumber(row.count)), 0);
  const firstSegment = roomSegments[0] || {};
  const roomType = roomSegments.map((row) => row.type).filter(Boolean).slice(0, 4).join(", ");
  return {
    id: b2bStableInterestLodgeId(lodge),
    lodgingName: String(lodge.lodgingName || "").trim().slice(0, 80),
    roomCount: String(lodge.roomCount || (segmentTotal > 0 ? segmentTotal : "")).trim(),
    roomType: String(lodge.roomType || roomType || "").trim().slice(0, 80),
    dayUseCount: String(lodge.dayUseCount || "").trim(),
    weekdayPrice: String(lodge.weekdayPrice || firstSegment.weekdayPrice || "").trim(),
    fridayPrice: String(lodge.fridayPrice || firstSegment.fridayPrice || "").trim(),
    saturdayPrice: String(lodge.saturdayPrice || firstSegment.saturdayPrice || "").trim(),
    sundayPrice: String(lodge.sundayPrice || firstSegment.sundayPrice || "").trim(),
    roomSegments,
    facilities: String(lodge.facilities || "").trim().slice(0, 160),
    naverConnected: Boolean(lodge.naverConnected),
    otaConnected: Boolean(lodge.otaConnected),
    savedAt: lodge.savedAt || new Date().toISOString(),
    collectedAt: lodge.collectedAt || "",
    collectionRunId: lodge.collectionRunId || "",
    collectionSource: lodge.collectionSource || "",
    collectionStatus: lodge.collectionStatus || "",
    collectionPrecisionGrade: String(lodge.collectionPrecisionGrade || "").trim().slice(0, 12),
    collectionPrecisionLabel: String(lodge.collectionPrecisionLabel || "").trim().slice(0, 60),
    collectionPrecisionTone: String(lodge.collectionPrecisionTone || "").trim().slice(0, 20),
    collectionPrecisionScore: Math.round(b2bMyLodgeNumber(lodge.collectionPrecisionScore)),
    collectionPrecisionReasons: b2bMyLodgeCollectionTextList(lodge.collectionPrecisionReasons, 5),
    collectionPrecisionWarnings: b2bMyLodgeCollectionTextList(lodge.collectionPrecisionWarnings, 5),
    collectionBasis: String(lodge.collectionBasis || "").trim().slice(0, 220),
    verifiedCorrectionApplied: Boolean(lodge.verifiedCorrectionApplied),
    verifiedLodgingBasisTotal: Math.round(b2bMyLodgeNumber(lodge.verifiedLodgingBasisTotal)),
    verifiedDayUseBasisTotal: Math.round(b2bMyLodgeNumber(lodge.verifiedDayUseBasisTotal)),
    verifiedCorrectionLabel: String(lodge.verifiedCorrectionLabel || "").trim().slice(0, 80),
    verifiedCorrectionSource: String(lodge.verifiedCorrectionSource || "").trim().slice(0, 80),
    verifiedCorrectionNote: String(lodge.verifiedCorrectionNote || "").trim().slice(0, 180),
    verifiedCorrectionUpdatedAt: String(lodge.verifiedCorrectionUpdatedAt || "").trim().slice(0, 40),
    verifiedRoomSegments: b2bMyLodgeSegmentInputRows({ roomSegments: lodge.verifiedRoomSegments })
      .filter((row) => b2bMyLodgeSegmentHasInput(row)),
    manualAdjusted: Boolean(lodge.manualAdjusted),
    manualAdjustedAt: lodge.manualAdjustedAt || "",
    searchRegion: String(lodge.searchRegion || "").trim().slice(0, 120),
    addressRegion: String(lodge.addressRegion || "").trim().slice(0, 120),
    regionBoundaryStatus: String(lodge.regionBoundaryStatus || "").trim().slice(0, 40),
    regionBoundaryLabel: String(lodge.regionBoundaryLabel || "").trim().slice(0, 120),
    regionBoundaryDetail: String(lodge.regionBoundaryDetail || "").trim().slice(0, 220),
    outsideSearchRegion: Boolean(lodge.outsideSearchRegion),
    address: String(lodge.address || "").trim().slice(0, 220),
    registeredAt: lodge.registeredAt || ""
  };
}

function b2bMyLodgeHasStructuredShape(value = {}) {
  return Boolean(
    value &&
    typeof value === "object" &&
    (Array.isArray(value.interestLodges) || Object.prototype.hasOwnProperty.call(value, "draft"))
  );
}

function b2bNormalizeMyLodgeDraft(draft = {}) {
  if (!b2bMyLodgeDraftHasInput(draft)) return {};
  const normalized = b2bNormalizeInterestLodge(draft);
  return { ...normalized, id: "", registeredAt: "" };
}

function b2bInterestLodgeWasExplicitlyRegistered(lodge = {}) {
  const id = String(lodge.id || "").trim();
  return Boolean(lodge.registeredAt || /^interest-[a-z0-9]+-[a-z0-9]{6}$/i.test(id));
}

function b2bMyLodgeStoreFromValue(value = {}) {
  const source = value && typeof value === "object" ? value : {};
  if (b2bMyLodgeHasStructuredShape(source)) {
    return {
      version: 2,
      draft: source.draft && typeof source.draft === "object" ? source.draft : {},
      interestLodges: (Array.isArray(source.interestLodges) ? source.interestLodges : [])
        .map((lodge) => b2bNormalizeInterestLodge(lodge))
        .filter((lodge) => b2bMyLodgeDraftHasInput(lodge))
        .filter((lodge) => b2bInterestLodgeWasExplicitlyRegistered(lodge))
        .slice(0, B2B_INTEREST_LODGE_LIMIT)
    };
  }
  if (b2bMyLodgeDraftHasInput(source)) {
    return {
      version: 2,
      draft: b2bNormalizeMyLodgeDraft(source),
      interestLodges: []
    };
  }
  return { version: 2, draft: source, interestLodges: [] };
}

function b2bMyLodgeSegmentAverage(row = {}) {
  const weekday = b2bMyLodgeNumber(row.weekdayPrice);
  const friday = b2bMyLodgeNumber(row.fridayPrice);
  const saturday = b2bMyLodgeNumber(row.saturdayPrice);
  const sunday = b2bMyLodgeNumber(row.sundayPrice);
  const weighted = weekday * 4 + friday + saturday + sunday;
  if (weighted > 0) return weighted / 7;
  const values = [weekday, friday, saturday, sunday].filter((value) => value > 0);
  return values.length ? values.reduce((sum, value) => sum + value, 0) / values.length : 0;
}

function b2bMyLodgeAveragePriceFromSegments(rows = []) {
  let weightedTotal = 0;
  let weightedCount = 0;
  const unweighted = [];
  rows.forEach((row) => {
    const average = b2bMyLodgeSegmentAverage(row);
    if (!average) return;
    const count = Math.round(b2bMyLodgeNumber(row.count));
    if (count > 0) {
      weightedTotal += average * count;
      weightedCount += count;
    } else {
      unweighted.push(average);
    }
  });
  if (weightedCount > 0) return weightedTotal / weightedCount;
  return unweighted.length ? unweighted.reduce((sum, value) => sum + value, 0) / unweighted.length : 0;
}

function b2bMyLodgeSegmentPrice(row = {}, key = "weekdayPrice") {
  const direct = b2bMyLodgeNumber(row[key]);
  if (direct > 0) return direct;
  const weekday = b2bMyLodgeNumber(row.weekdayPrice);
  return weekday > 0 ? weekday : b2bMyLodgeSegmentAverage(row);
}

function b2bMyLodgeSegmentRevenue(rows = [], rates = {}, dayCounts = {}) {
  return rows.reduce((sum, row) => {
    const count = Math.round(b2bMyLodgeNumber(row.count));
    if (count <= 0) return sum;
    return sum +
      count * b2bMyLodgeSegmentPrice(row, "weekdayPrice") * b2bMyLodgeNumber(rates.weekday) * b2bMyLodgeNumber(dayCounts.weekday) +
      count * b2bMyLodgeSegmentPrice(row, "fridayPrice") * b2bMyLodgeNumber(rates.friday) * b2bMyLodgeNumber(dayCounts.friday) +
      count * b2bMyLodgeSegmentPrice(row, "saturdayPrice") * b2bMyLodgeNumber(rates.saturday) * b2bMyLodgeNumber(dayCounts.saturday) +
      count * b2bMyLodgeSegmentPrice(row, "sundayPrice") * b2bMyLodgeNumber(rates.sunday) * b2bMyLodgeNumber(dayCounts.sunday);
  }, 0);
}

function b2bMyLodgeAveragePrice(draft = {}) {
  const weekday = b2bMyLodgeNumber(draft.weekdayPrice);
  const friday = b2bMyLodgeNumber(draft.fridayPrice);
  const saturday = b2bMyLodgeNumber(draft.saturdayPrice);
  const sunday = b2bMyLodgeNumber(draft.sundayPrice);
  const weighted = weekday * 4 + friday + saturday + sunday;
  return weighted > 0 ? weighted / 7 : 0;
}

function b2bMyLodgeFacilities(value = "") {
  return String(value || "")
    .split(/[,/|\n]+/)
    .map((item) => item.trim())
    .filter(Boolean)
    .slice(0, 8);
}

function b2bWonNumber(value) {
  if (Number.isFinite(Number(value))) return Number(value);
  const text = String(value || "").replace(/,/g, "").replace(/\s+/g, "");
  if (!text) return 0;
  let total = 0;
  const eok = text.match(/([\d.]+)억/u);
  const man = text.match(/([\d.]+)만/u);
  const won = text.match(/([\d.]+)원/u);
  if (eok) total += Number(eok[1]) * 100000000;
  if (man) total += Number(man[1]) * 10000;
  if (!eok && !man && won) total += Number(won[1]);
  if (Number.isFinite(total) && total > 0) return Math.round(total);
  const numeric = Number(text.replace(/[^\d.]/g, ""));
  return Number.isFinite(numeric) ? numeric : 0;
}

function roundB2BLodgePrice(value) {
  const number = Number(value);
  if (!Number.isFinite(number) || number <= 0) return "";
  return String(Math.round(number / 1000) * 1000);
}

function b2bCollectedRunDays(item = {}) {
  const rowDays = Math.max(weeklyRows(item).length, weeklyRows(item, "day").length);
  return Math.max(
    1,
    finiteNumber(item.weeklyDays, 0),
    finiteNumber(item.dayUseWeeklyDays, 0),
    rowDays,
    bookingDays(state.data?.run || {}) || DEFAULT_BOOKING_DAYS
  );
}

function b2bCollectedSummaryTotal(summary = "", kind = "lodging") {
  const parts = String(summary || "")
    .split(/\s*·\s*/)
    .map((part) => part.trim())
    .filter(Boolean);
  const target = parts.find((part) => (
    kind === "day"
      ? /데이유즈|캠프닉/i.test(part) && /\d[\d,]*\s*\/\s*\d[\d,]*/.test(part)
      : !/데이유즈|캠프닉|미분류/i.test(part) && /\d[\d,]*\s*\/\s*\d[\d,]*/.test(part)
  )) || "";
  const match = target.match(/[\d,]+\s*\/\s*([\d,]+)/);
  const total = match ? optionalNumber(match[1]) : NaN;
  return Number.isFinite(total) && total > 0 ? total : 0;
}

function b2bNormalizeDailyStock(value, days = DEFAULT_BOOKING_DAYS, references = []) {
  const number = optionalNumber(value);
  if (!Number.isFinite(number) || number <= 0) return 0;
  const refValues = references
    .map((item) => optionalNumber(item))
    .filter((item) => Number.isFinite(item) && item > 0);
  const refMax = Math.max(0, ...refValues);
  const refMin = refValues.length ? Math.min(...refValues) : 0;
  if (days > 1 && refMin > 0 && number > refMin * 1.8) {
    const divided = number / days;
    if (divided > 0 && Math.abs(divided - refMin) <= Math.max(2, refMin * 0.35)) return divided;
  }
  if (days > 1 && refMax > 0 && number > refMax * 1.8) {
    const divided = number / days;
    if (divided > 0 && Math.abs(divided - refMax) <= Math.max(2, refMax * 0.35)) return divided;
  }
  return number;
}

function b2bCollectedStockReferenceValues(item = {}, kind = "lodging") {
  const days = b2bCollectedRunDays(item);
  const summaryTotal = b2bCollectedSummaryTotal(item.productTypeSummary, kind);
  const weeklyAverage = kind === "day"
    ? (optionalNumber(item.dayUseWeeklyTotalStock) > 0 ? optionalNumber(item.dayUseWeeklyTotalStock) / days : 0)
    : (optionalNumber(item.weeklyTotalStock) > 0 ? optionalNumber(item.weeklyTotalStock) / days : 0);
  const verified = b2bCollectedVerifiedCorrection(item);
  const candidates = kind === "day"
    ? [
        verified.dayUse,
        summaryTotal,
        weeklyAverage,
        item.verifiedDayUseBasisTotal,
        item.manualDayUseBasisTotal,
        item.dayUseTotalStock,
        item.dayUseWeeklyOperatingTotal,
        item.dayUseWeeklyBasisTotal,
        item.dayUseWeeklyMaxTotal
      ]
    : [
        verified.lodging,
        summaryTotal,
        weeklyAverage,
        item.verifiedLodgingBasisTotal,
        item.manualLodgingBasisTotal,
        item.nightTotalStock,
        item.totalRooms,
        item.rawTotalStock,
        item.weeklyOperatingTotal,
        item.weeklyBasisTotal,
        item.weeklyMaxTotal
      ];
  return candidates
    .map((value) => optionalNumber(value))
    .filter((value) => Number.isFinite(value) && value > 0);
}

function b2bCollectedVerifiedCorrection(item = {}) {
  const roomSegments = b2bMyLodgeSegmentInputRows({
    roomSegments:
      item.verifiedRoomSegments ||
      item.companyManualCorrection?.roomSegments ||
      item.companyProfile?.manualCorrection?.roomSegments ||
      []
  }).filter((row) => b2bMyLodgeSegmentHasInput(row));
  const roomSegmentTotal = roomSegments.reduce((sum, row) => sum + Math.round(b2bMyLodgeNumber(row.count)), 0);
  const lodging = optionalNumber(
    item.verifiedLodgingBasisTotal ??
    item.manualLodgingBasisTotal ??
    item.companyManualCorrection?.lodgingBasisTotal ??
    item.companyProfile?.manualCorrection?.lodgingBasisTotal
  );
  const dayUse = optionalNumber(
    item.verifiedDayUseBasisTotal ??
    item.manualDayUseBasisTotal ??
    item.companyManualCorrection?.dayUseBasisTotal ??
    item.companyProfile?.manualCorrection?.dayUseBasisTotal
  );
  const applied = Boolean(
    item.verifiedCorrectionApplied ||
    item.manualCorrectionApplied ||
    item.companyManualCorrection ||
    item.companyProfile?.manualCorrection ||
    (Number.isFinite(lodging) && lodging > 0) ||
    (Number.isFinite(dayUse) && dayUse > 0) ||
    roomSegments.length
  );
  return {
    applied,
    lodging: Number.isFinite(lodging) && lodging > 0 ? Math.round(lodging) : Math.round(roomSegmentTotal),
    dayUse: Number.isFinite(dayUse) && dayUse > 0 ? Math.round(dayUse) : 0,
    label: String(item.verifiedCorrectionLabel || "운영 검수값").trim(),
    source: String(item.verifiedCorrectionSource || "company_master").trim(),
    note: String(item.verifiedCorrectionNote || item.companyManualCorrection?.note || item.companyProfile?.manualCorrection?.note || "").trim(),
    updatedAt: String(item.verifiedCorrectionUpdatedAt || item.companyManualCorrection?.updatedAt || item.companyProfile?.manualCorrection?.updatedAt || "").trim(),
    roomSegments
  };
}

function b2bCollectedProductKind(row = {}) {
  const text = [row.saleType, row.bizItemSubType, row.name].filter(Boolean).join(" ");
  return /데이|day|캠프닉|campnic|camp_nic/i.test(text) ? "day" : "lodging";
}

function b2bCollectedProductRows(item = {}, kind = "lodging") {
  const rows = [
    ...(Array.isArray(item.weeklyProductDetails) ? item.weeklyProductDetails : []),
    ...(Array.isArray(item.itemDetails) ? item.itemDetails : [])
  ].filter((row) => row && typeof row === "object");
  const seen = new Set();
  return rows.filter((row) => {
    if (b2bCollectedProductKind(row) !== kind) return false;
    const name = b2bCleanCollectedRoomName(b2bCollectedRoomNameFromRow(row));
    if (!name) return false;
    const key = [
      row.date || "",
      row.key || row.bizItemId || name,
      row.total ?? row.stock ?? "",
      row.price ?? ""
    ].join("|");
    if (seen.has(key)) return false;
    seen.add(key);
    return true;
  });
}

function b2bCollectedProductRowKey(row = {}) {
  const name = b2bCleanCollectedRoomName(b2bCollectedRoomNameFromRow(row));
  return String(row.key || row.bizItemId || compactSearchText(name) || name).trim();
}

function b2bCollectedDayPriceKey(dateText = "") {
  const date = parseDate(dateText);
  if (!date) return "";
  const day = date.getDay();
  if (day === 5) return "fridayPrice";
  if (day === 6) return "saturdayPrice";
  if (day === 0) return "sundayPrice";
  return "weekdayPrice";
}

function b2bCollectedRepresentativePrice(values = []) {
  const prices = values
    .map((value) => roundB2BLodgePrice(value))
    .map((value) => optionalNumber(value))
    .filter((value) => Number.isFinite(value) && value > 0)
    .sort((a, b) => a - b);
  if (!prices.length) return "";
  const frequency = new Map();
  prices.forEach((price) => frequency.set(price, (frequency.get(price) || 0) + 1));
  const entries = [...frequency.entries()].sort((a, b) => {
    if (b[1] !== a[1]) return b[1] - a[1];
    return Math.abs(a[0] - prices[Math.floor(prices.length / 2)]) - Math.abs(b[0] - prices[Math.floor(prices.length / 2)]);
  });
  return String(entries[0][0]);
}

function b2bCollectedProductStockTotal(item = {}, kind = "lodging") {
  const rows = b2bCollectedProductRows(item, kind);
  if (!rows.length) return 0;
  const days = b2bCollectedRunDays(item);
  const stockReferences = b2bCollectedStockReferenceValues(item, kind);
  const byDate = new Map();
  rows.forEach((row) => {
    const dateKey = row.date || "basis";
    const total = optionalNumber(row.total ?? row.stock);
    const resolved = Number.isFinite(total) && total > 0
      ? b2bNormalizeDailyStock(total, days, stockReferences)
      : (/객실별|객실상품/i.test(row.listType || item.listType || "") ? 1 : 0);
    if (resolved <= 0) return;
    byDate.set(dateKey, (byDate.get(dateKey) || 0) + resolved);
  });
  const total = byDate.size ? Math.max(...byDate.values()) : 0;
  const cap = b2bCollectedDailyStockCap(item, kind);
  if (cap > 0 && total > cap * 1.8) return cap;
  return total;
}

function b2bCollectedDailyStockCap(item = {}, kind = "lodging") {
  const verified = b2bCollectedVerifiedCorrection(item);
  if (kind === "lodging" && verified.lodging > 0) return verified.lodging;
  if (kind === "day" && verified.dayUse > 0) return verified.dayUse;
  const days = b2bCollectedRunDays(item);
  const references = b2bCollectedStockReferenceValues(item, kind);
  const normalized = references
    .map((value) => b2bNormalizeDailyStock(value, days, references))
    .filter((value) => Number.isFinite(value) && value > 0)
    .sort((a, b) => a - b);
  if (!normalized.length) return 0;
  const median = normalized[Math.floor(normalized.length / 2)];
  const stable = normalized.filter((value) => value <= median * 1.5);
  return Math.max(...(stable.length ? stable : normalized));
}

function b2bCollectedBaseRoomName(value = "") {
  const cleaned = b2bCleanCollectedRoomName(value);
  return cleaned
    .replace(/\s*\([^)]*\)\s*$/g, "")
    .replace(/\s*(?:객실|글램핑|카라반|사이트)?\s*\d+\s*(?:호|번|동)?\s*$/i, "")
    .replace(/\s*[-_ ]+[A-Z]?\d+\s*$/i, "")
    .replace(/\s+/g, " ")
    .trim() || cleaned || "객실상품";
}

function b2bCollectedSegmentSignature(row = {}) {
  return B2B_MY_LODGE_PRICE_KEYS.map((key) => row[key] || "").join("/");
}

function b2bCompressCollectedSegments(segments = []) {
  if (segments.length <= B2B_MY_LODGE_SEGMENT_LIMIT) return segments;
  const grouped = new Map();
  segments.forEach((row) => {
    const baseName = b2bCollectedBaseRoomName(row.type);
    const signature = b2bCollectedSegmentSignature(row);
    const key = `${baseName}|${signature}`;
    const previous = grouped.get(key) || { ...row, type: baseName, count: 0, sourceNames: [] };
    previous.count = Math.round(b2bMyLodgeNumber(previous.count)) + Math.max(1, Math.round(b2bMyLodgeNumber(row.count)));
    previous.sourceNames.push(row.type);
    grouped.set(key, previous);
  });
  let rows = [...grouped.values()].map((row) => ({
    ...row,
    count: String(Math.round(b2bMyLodgeNumber(row.count))),
    type: row.sourceNames.length > 1 ? `${row.type} ${fmtNumber(row.sourceNames.length)}실` : row.type
  }));
  if (rows.length <= B2B_MY_LODGE_SEGMENT_LIMIT) return rows.slice(0, B2B_MY_LODGE_SEGMENT_LIMIT);
  const byPrice = new Map();
  rows.forEach((row) => {
    const signature = b2bCollectedSegmentSignature(row) || "가격확인";
    const previous = byPrice.get(signature) || { ...row, type: "객실상품", count: 0 };
    previous.count = Math.round(b2bMyLodgeNumber(previous.count)) + Math.max(1, Math.round(b2bMyLodgeNumber(row.count)));
    byPrice.set(signature, previous);
  });
  rows = [...byPrice.values()].map((row) => ({
    ...row,
    type: `${row.type} ${fmtNumber(row.count)}실`,
    count: String(Math.round(b2bMyLodgeNumber(row.count)))
  }));
  return rows.slice(0, B2B_MY_LODGE_SEGMENT_LIMIT);
}

function b2bCollectedProductSegments(item = {}) {
  const rows = b2bCollectedProductRows(item, "lodging");
  if (!rows.length) return [];
  const days = b2bCollectedRunDays(item);
  const stockReferences = b2bCollectedStockReferenceValues(item, "lodging");
  const byProduct = new Map();
  rows.forEach((row) => {
    const name = b2bCleanCollectedRoomName(b2bCollectedRoomNameFromRow(row));
    const key = b2bCollectedProductRowKey(row);
    const listType = row.listType || item.listType || "";
    const total = optionalNumber(row.total ?? row.stock);
    const count = Number.isFinite(total) && total > 0
      ? b2bNormalizeDailyStock(total, days, stockReferences)
      : (/객실별|객실상품/i.test(listType) ? 1 : 0);
    const current = byProduct.get(key) || {
      type: name,
      count: 0,
      prices: {
        weekdayPrice: [],
        fridayPrice: [],
        saturdayPrice: [],
        sundayPrice: []
      }
    };
    current.type = current.type || name;
    if (count > current.count) current.count = count;
    const priceKey = b2bCollectedDayPriceKey(row.date);
    const price = optionalNumber(row.price);
    if (priceKey && Number.isFinite(price) && price > 0) current.prices[priceKey].push(price);
    byProduct.set(key, current);
  });
  const segments = b2bNormalizeCollectedSegmentCounts([...byProduct.values()]
    .map((row) => ({
      type: row.type,
      count: row.count > 0 ? String(Math.round(row.count)) : "",
      weekdayPrice: b2bCollectedRepresentativePrice(row.prices.weekdayPrice),
      fridayPrice: b2bCollectedRepresentativePrice(row.prices.fridayPrice),
      saturdayPrice: b2bCollectedRepresentativePrice(row.prices.saturdayPrice),
      sundayPrice: b2bCollectedRepresentativePrice(row.prices.sundayPrice)
    }))
    .filter((row) => b2bMyLodgeSegmentHasInput(row)), item);
  return b2bCompressCollectedSegments(segments);
}

function b2bNormalizeCollectedSegmentCounts(segments = [], item = {}) {
  const cap = b2bCollectedDailyStockCap(item, "lodging");
  if (segments.length <= 1 || cap <= 0) return segments;
  const total = segments.reduce((sum, row) => sum + Math.round(b2bMyLodgeNumber(row.count)), 0);
  if (total <= cap * 1.8) return segments;
  const repeatedTotalRows = segments.filter((row) => b2bMyLodgeNumber(row.count) >= cap * 0.75).length;
  if (repeatedTotalRows < Math.ceil(segments.length * 0.5)) return segments;
  return segments.map((row) => ({ ...row, count: "" }));
}

function b2bCollectedRoomCount(item = {}) {
  const verified = b2bCollectedVerifiedCorrection(item);
  if (verified.lodging > 0) return String(verified.lodging);
  const days = b2bCollectedRunDays(item);
  const summaryTotal = b2bCollectedSummaryTotal(item.productTypeSummary, "lodging");
  const weeklyTotalAverage = optionalNumber(item.weeklyTotalStock) > 0 ? optionalNumber(item.weeklyTotalStock) / days : 0;
  const productTotal = b2bCollectedProductStockTotal(item, "lodging");
  const baseReferences = b2bCollectedStockReferenceValues(item, "lodging");
  const directCandidates = [
    productTotal,
    summaryTotal,
    item.manualLodgingBasisTotal,
    item.nightTotalStock,
    item.totalRooms,
    item.rawTotalStock
  ].map((value) => b2bNormalizeDailyStock(value, days, baseReferences)).filter((value) => value > 0);
  const directReference = directCandidates.length ? directCandidates : [summaryTotal];
  const candidates = [
    ...directCandidates,
    b2bNormalizeDailyStock(item.weeklyOperatingTotal, days, directReference),
    b2bNormalizeDailyStock(item.weeklyBasisTotal, days, directReference),
    b2bNormalizeDailyStock(item.weeklyMaxTotal, days, directReference),
    weeklyTotalAverage
  ].filter((value) => value > 0);
  return candidates.length ? String(Math.round(Math.max(...candidates))) : "";
}

function b2bCollectedRoomNameFromRow(row = {}) {
  return String(
    row.name ||
    row.productName ||
    row.itemName ||
    row.roomName ||
    row.title ||
    row.label ||
    ""
  ).trim();
}

function b2bCleanCollectedRoomName(value = "") {
  const text = String(value || "").replace(/\s+/g, " ").trim();
  if (!text) return "";
  if (/숙박상품\s*\d+종|예약가능\s*\d[\d,]*\s*\/\s*\d[\d,]*|판매완료|마감\s*\d[\d,]*\s*\/\s*\d[\d,]*|미분류\s*\d+종/i.test(text)) return "";
  return text.slice(0, 80);
}

function b2bCollectedRoomNames(item = {}) {
  const names = [];
  b2bCollectedProductRows(item, "lodging")
    .map(b2bCollectedRoomNameFromRow)
    .forEach((name) => {
      const cleaned = b2bCleanCollectedRoomName(name);
      if (cleaned) names.push(cleaned);
    });
  String(item.roomNamePreview || item.roomNames || item["객실명(일부)"] || "")
    .split(/\s*,\s*/)
    .forEach((name) => {
      const cleaned = b2bCleanCollectedRoomName(name);
      if (cleaned) names.push(cleaned);
    });
  const seen = new Set();
  return names.filter((name) => {
    const key = compactSearchText(name);
    if (!key || seen.has(key)) return false;
    seen.add(key);
    return true;
  }).slice(0, B2B_MY_LODGE_SEGMENT_LIMIT);
}

function b2bCollectedRoomType(item = {}) {
  const productNames = b2bCollectedRoomNames(item);
  return productNames.join(", ").slice(0, 80);
}

function b2bCollectedDayUseCount(item = {}) {
  const verified = b2bCollectedVerifiedCorrection(item);
  if (verified.dayUse > 0) return String(verified.dayUse);
  const days = b2bCollectedRunDays(item);
  const summaryTotal = b2bCollectedSummaryTotal(item.productTypeSummary, "day");
  const weeklyTotalAverage = optionalNumber(item.dayUseWeeklyTotalStock) > 0 ? optionalNumber(item.dayUseWeeklyTotalStock) / days : 0;
  const productTotal = b2bCollectedProductStockTotal(item, "day");
  const baseReferences = b2bCollectedStockReferenceValues(item, "day");
  const candidates = [
    productTotal,
    summaryTotal,
    item.manualDayUseBasisTotal,
    b2bNormalizeDailyStock(item.dayUseTotalStock, days, baseReferences),
    b2bNormalizeDailyStock(item.dayUseWeeklyOperatingTotal, days, baseReferences),
    b2bNormalizeDailyStock(item.dayUseWeeklyBasisTotal, days, baseReferences),
    b2bNormalizeDailyStock(item.dayUseWeeklyMaxTotal, days, baseReferences),
    weeklyTotalAverage
  ].filter((value) => value > 0);
  return candidates.length ? String(Math.round(Math.max(...candidates))) : "";
}

function b2bCollectedPriceFields(item = {}) {
  const result = {};
  const verifiedSegments = b2bCollectedVerifiedCorrection(item).roomSegments || [];
  const productPrices = {
    weekdayPrice: [],
    fridayPrice: [],
    saturdayPrice: [],
    sundayPrice: []
  };
  b2bCollectedProductRows(item, "lodging").forEach((row) => {
    const key = b2bCollectedDayPriceKey(row.date);
    const price = optionalNumber(row.price);
    if (key && Number.isFinite(price) && price > 0) productPrices[key].push(price);
  });
  B2B_MY_LODGE_PRICE_KEYS.forEach((key) => {
    result[key] = b2bCollectedRepresentativePrice(productPrices[key]);
  });
  const profile = preciseRevenueProfile(item);
  const keyByLabel = {
    "평일": "weekdayPrice",
    "금요일": "fridayPrice",
    "토요일": "saturdayPrice",
    "일요일": "sundayPrice"
  };
  (profile.lodgingDayRows || []).forEach((row) => {
    const key = keyByLabel[row.label];
    if (!key || result[key]) return;
    const priced = finiteNumber(row.pricedSoldOut, 0);
    const amount = b2bWonNumber(row.revenueText);
    const price = priced > 0 ? amount / priced : 0;
    const rounded = roundB2BLodgePrice(price);
    if (rounded) result[key] = rounded;
  });
  B2B_MY_LODGE_PRICE_KEYS.forEach((key) => {
    const verifiedPrice = b2bCollectedRepresentativePrice(verifiedSegments.map((row) => row[key]));
    if (verifiedPrice) result[key] = verifiedPrice;
  });
  return result;
}

function b2bCollectedRoomSegments(item = {}, prices = {}, current = {}) {
  const verifiedSegments = b2bCollectedVerifiedCorrection(item).roomSegments || [];
  if (verifiedSegments.length) return verifiedSegments;
  const productSegments = b2bCollectedProductSegments(item);
  if (productSegments.length) return productSegments;
  const names = b2bCollectedRoomNames(item);
  const roomCount = b2bCollectedRoomCount(item);
  const roomTotal = optionalNumber(roomCount);
  const sourceText = [item.listType, item.availabilityUnit, item.inventoryMemo, item.basis].filter(Boolean).join(" ");
  const isRoomUnitList = /객실별|객실상품/i.test(sourceText);
  const priceFields = B2B_MY_LODGE_PRICE_KEYS.reduce((acc, key) => {
    acc[key] = names.length <= 1 ? (prices[key] || "") : "";
    return acc;
  }, {});
  if (names.length) {
    return names.map((name) => ({
      type: name,
      count: isRoomUnitList && names.length > 1 ? "1" : (names.length === 1 && Number.isFinite(roomTotal) ? String(Math.round(roomTotal)) : ""),
      ...priceFields
    }));
  }
  const roomType = b2bCollectedRoomType(item) || current.roomType || "";
  const collectedSegment = {
    type: roomType,
    count: roomCount || current.roomCount || "",
    weekdayPrice: prices.weekdayPrice || "",
    fridayPrice: prices.fridayPrice || "",
    saturdayPrice: prices.saturdayPrice || "",
    sundayPrice: prices.sundayPrice || ""
  };
  return b2bMyLodgeSegmentHasInput(collectedSegment) ? [collectedSegment] : [];
}

function b2bCollectedFacilities(item = {}) {
  const coupon = naverCouponInfo(item);
  const productNames = b2bCollectedRoomNames(item)
    .slice(0, 3);
  return [
    item.productTypeSummary,
    item.category,
    item.businessCategory,
    ...productNames,
    coupon.visible ? `쿠폰: ${coupon.names || "노출 신호"}` : ""
  ].filter(Boolean).join(", ").slice(0, 160);
}

function b2bCollectedNaverConnected(item = {}) {
  return Boolean(
    item.hasInventory ||
    finiteNumber(item.weeklyTotalStock, 0) > 0 ||
    finiteNumber(item.nightTotalStock, 0) > 0 ||
    (Array.isArray(item.itemDetails) && item.itemDetails.length)
  );
}

function b2bCollectedWeeklyStockNormalized(item = {}, roomCount = "") {
  const days = b2bCollectedRunDays(item);
  const daily = b2bMyLodgeNumber(roomCount);
  if (days <= 1 || daily <= 0) return false;
  return [
    item.weeklyTotalStock,
    item.weeklyOperatingTotal,
    item.weeklyBasisTotal,
    item.weeklyMaxTotal,
    item.rawTotalStock,
    item.nightTotalStock
  ].some((value) => {
    const number = optionalNumber(value);
    if (!Number.isFinite(number) || number <= daily * 1.8) return false;
    return Math.abs(number / days - daily) <= Math.max(2, daily * 0.35);
  });
}

function b2bCollectedPrecisionProfile(item = {}, context = {}) {
  const roomSegments = Array.isArray(context.roomSegments) ? context.roomSegments : [];
  const prices = context.prices || {};
  const roomCount = context.roomCount || "";
  const verified = b2bCollectedVerifiedCorrection(item);
  const verifiedSegments = verified.roomSegments || [];
  const verifiedApplied = Boolean(verified.lodging || verified.dayUse || verifiedSegments.length);
  const productRows = b2bCollectedProductRows(item, "lodging");
  const namedSegments = roomSegments.filter((row) => String(row.type || "").trim()).length;
  const countedSegments = roomSegments.filter((row) => b2bMyLodgeNumber(row.count) > 0).length;
  const segmentCountTotal = roomSegments.reduce((sum, row) => sum + Math.round(b2bMyLodgeNumber(row.count)), 0);
  const segmentPriceKeys = new Set();
  roomSegments.forEach((row) => {
    B2B_MY_LODGE_PRICE_KEYS.forEach((key) => {
      if (b2bMyLodgeNumber(row[key]) > 0) segmentPriceKeys.add(key);
    });
  });
  B2B_MY_LODGE_PRICE_KEYS.forEach((key) => {
    if (b2bMyLodgeNumber(prices[key]) > 0) segmentPriceKeys.add(key);
  });
  const priceCoverage = segmentPriceKeys.size;
  const weeklyNormalized = b2bCollectedWeeklyStockNormalized(item, roomCount);
  let score = 0;
  if (productRows.length) score += 22;
  if (namedSegments) score += 20;
  if (countedSegments) score += 20;
  if (roomCount) score += 10;
  score += Math.min(24, priceCoverage * 6);
  if (weeklyNormalized) score += 4;
  if (verifiedApplied) score += 18;
  if (verifiedSegments.length) score += 12;
  if (verifiedApplied && (namedSegments || priceCoverage)) score = Math.max(score, 72);
  if (verifiedSegments.length && countedSegments && priceCoverage >= 3) score = Math.max(score, 84);
  score = Math.max(0, Math.min(100, Math.round(score)));
  const grade = score >= 82 ? "A" : score >= 64 ? "B" : score >= 42 ? "C" : "D";
  const autoLabel = {
    A: "정밀 자동수집",
    B: "자동수집 보완 필요",
    C: "부분 자동수집",
    D: "수동 확인 필요"
  }[grade];
  const label = verifiedSegments.length
    ? (priceCoverage >= 3 ? "검수 객실종류 기반 자동수집" : "검수 객실종류 우선·가격 보완")
    : verifiedApplied
    ? (priceCoverage >= 3 ? "검수값 기반 자동수집" : "검수값 우선·가격 보완")
    : autoLabel;
  const tone = {
    A: "good",
    B: "strong",
    C: "watch",
    D: "hot"
  }[grade];
  const reasons = [
    verified.lodging ? `운영 검수 객실 ${fmtNumber(verified.lodging)}실 우선 적용` : "",
    verified.dayUse ? `운영 검수 데이유즈 ${fmtNumber(verified.dayUse)}회 우선 적용` : "",
    verifiedSegments.length ? `운영 검수 객실종류 ${fmtNumber(verifiedSegments.length)}개 우선 적용` : "",
    productRows.length ? `상품 행 ${fmtNumber(productRows.length)}개 확인` : "",
    namedSegments ? `객실종류 ${fmtNumber(namedSegments)}개 확인` : "",
    countedSegments ? `상품별 수량 ${fmtNumber(countedSegments)}개 확인` : "",
    roomCount ? `하루 기준 객실 ${fmtNumber(roomCount)}실` : "",
    priceCoverage ? `요일가격 ${fmtNumber(priceCoverage)}/4개 확인` : "",
    weeklyNormalized ? "7일 누적 수량을 하루 기준으로 환산" : ""
  ].filter(Boolean);
  const warnings = [
    !namedSegments ? "객실종류명 직접 확인 권장" : "",
    !countedSegments && !verifiedApplied ? "상품별 수량 직접 확인 필요" : "",
    verified.lodging && segmentCountTotal > verified.lodging * 1.5 ? "상품별 수량은 총량 기준으로 재확인 권장" : "",
    verifiedSegments.length && priceCoverage < 4 ? "검수 객실종류의 일부 요일 가격 보완 권장" : "",
    !verifiedSegments.length && priceCoverage < 4 ? "일부 요일 가격 직접 보완 권장" : "",
    !roomCount ? "전체 객실수 직접 입력 필요" : ""
  ].filter(Boolean);
  return {
    grade,
    label,
    tone,
    score,
    reasons: b2bMyLodgeCollectionTextList(reasons, 5),
    warnings: b2bMyLodgeCollectionTextList(warnings, 4),
    basis: verifiedApplied
      ? `운영 검수값 + 네이버 ${fmtNumber(b2bCollectedRunDays(item))}일 상품/재고 기준`
      : `네이버 업체명 검색 · ${fmtNumber(b2bCollectedRunDays(item))}일 상품/재고 기준`,
    verified
  };
}

function b2bMyLodgeDraftFromCollectedItem(item = {}, result = {}, current = {}) {
  const prices = b2bCollectedPriceFields(item);
  const roomCount = b2bCollectedRoomCount(item);
  const dayUseCount = b2bCollectedDayUseCount(item);
  const facilities = b2bCollectedFacilities(item);
  const name = String(item.name || item.companyName || current.lodgingName || result.keyword || "").trim();
  const collectedSegments = b2bCollectedRoomSegments(item, prices, current);
  const currentSegments = b2bMyLodgeSegmentInputRows(current);
  const roomSegments = collectedSegments.length ? collectedSegments : currentSegments;
  const roomType = roomSegments.map((row) => row.type).filter(Boolean).slice(0, 4).join(", ") || b2bCollectedRoomType(item);
  const precision = b2bCollectedPrecisionProfile(item, { prices, roomCount, roomSegments });
  const collected = {
    ...current,
    lodgingName: name || current.lodgingName || "",
    roomCount: roomCount || current.roomCount || "",
    roomType: roomType || current.roomType || "",
    dayUseCount: dayUseCount || current.dayUseCount || "",
    weekdayPrice: prices.weekdayPrice || "",
    fridayPrice: prices.fridayPrice || "",
    saturdayPrice: prices.saturdayPrice || "",
    sundayPrice: prices.sundayPrice || "",
    roomSegments,
    facilities: facilities || current.facilities || "",
    naverConnected: b2bCollectedNaverConnected(item) || Boolean(current.naverConnected),
    otaConnected: Boolean(current.otaConnected),
    searchRegion: item.searchRegion || current.searchRegion || result.keyword || activeKeyword(),
    addressRegion: item.addressRegion || item.region || current.addressRegion || "",
    regionBoundaryStatus: item.regionBoundaryStatus || current.regionBoundaryStatus || "",
    regionBoundaryLabel: item.regionBoundaryLabel || current.regionBoundaryLabel || "",
    regionBoundaryDetail: item.regionBoundaryDetail || current.regionBoundaryDetail || "",
    outsideSearchRegion: Boolean(item.outsideSearchRegion || current.outsideSearchRegion),
    address: item.address || current.address || "",
    savedAt: new Date().toISOString(),
    collectedAt: new Date().toISOString(),
    collectionRunId: result.runId || "",
    collectionSource: "naver_company",
    collectionStatus: `${name || current.lodgingName || "관심숙소"} 자동 수집 완료 · ${precision.label}`,
    collectionPrecisionGrade: precision.grade,
    collectionPrecisionLabel: precision.label,
    collectionPrecisionTone: precision.tone,
    collectionPrecisionScore: precision.score,
    collectionPrecisionReasons: precision.reasons,
    collectionPrecisionWarnings: precision.warnings,
    collectionBasis: precision.basis,
    verifiedCorrectionApplied: Boolean(precision.verified?.applied),
    verifiedLodgingBasisTotal: precision.verified?.lodging || "",
    verifiedDayUseBasisTotal: precision.verified?.dayUse || "",
    verifiedCorrectionLabel: precision.verified?.label || "",
    verifiedCorrectionSource: precision.verified?.source || "",
    verifiedCorrectionNote: precision.verified?.note || "",
    verifiedCorrectionUpdatedAt: precision.verified?.updatedAt || "",
    verifiedRoomSegments: precision.verified?.roomSegments || [],
    manualAdjusted: false,
    manualAdjustedAt: ""
  };
  return collected;
}

function b2bMyLodgeRate(flow = {}, key = "all", fallback = 0.25) {
  const rate = flow?.[key]?.rate;
  if (Number.isFinite(rate)) return Math.max(0, Math.min(1, rate));
  return Math.max(0, Math.min(1, fallback));
}

function b2bMyLodgeBasisRun() {
  const run = state.data?.run || {};
  const checkIn = run.checkIn || els.checkInInput?.value || new Date().toISOString().slice(0, 10);
  return {
    ...run,
    checkIn,
    checkOut: isoAddDays(checkIn, DEFAULT_BOOKING_DAYS - 1),
    bookingRangeDays: DEFAULT_BOOKING_DAYS
  };
}

function b2bMyLodgeDayTypeCounts(run = {}) {
  const days = Math.max(1, bookingDays(run) || DEFAULT_BOOKING_DAYS);
  const start = parseDate(run.checkIn) || new Date();
  const counts = { weekday: 0, friday: 0, saturday: 0, sunday: 0 };
  for (let index = 0; index < days; index += 1) {
    const date = new Date(start);
    date.setDate(start.getDate() + index);
    const day = date.getDay();
    if (day === 5) counts.friday += 1;
    else if (day === 6) counts.saturday += 1;
    else if (day === 0) counts.sunday += 1;
    else counts.weekday += 1;
  }
  return counts;
}

function b2bMyLodgeDeltaText(value, base) {
  if (!Number.isFinite(value) || !Number.isFinite(base) || base <= 0) return "비교 대기";
  return formatSignedRate(value / base - 1);
}

function b2bMyLodgeDeltaTone(value, base) {
  if (!Number.isFinite(value) || !Number.isFinite(base) || base <= 0) return "neutral";
  const delta = value / base - 1;
  if (delta >= 0.2) return "good";
  if (delta <= -0.2) return "watch";
  return "strong";
}

function b2bMyLodgeComparisonConclusion(input = {}) {
  const hasEstimateBasis = Boolean(input.hasEstimateBasis);
  const weeklyRevenue = finiteNumber(input.weeklyRevenue, 0);
  const averageRevenue = finiteNumber(input.averageRevenue, 0);
  const topAverage = finiteNumber(input.topAverage, 0);
  const avgPrice = finiteNumber(input.avgPrice, 0);
  const marketAvgPrice = finiteNumber(input.marketAvgPrice, 0);
  const channelScore = Number(input.channelScore || 0);
  const locationLabel = input.locationConclusion?.label || "";
  const basisPeriod = input.basisPeriod || "";
  const basisDays = Number(input.basisDays || DEFAULT_BOOKING_DAYS);
  if (!hasEstimateBasis) {
    return {
      tone: "neutral",
      label: "입력 후 비교",
      headline: "객실종류별 수량과 요일 가격을 입력하면 바로 비교됩니다.",
      summary: "관심숙소의 7일 기준 예상 매출, 지역 평균, 상위권 대비 차이를 한 번에 계산합니다.",
      chips: [`${fmtNumber(basisDays)}일 기준`, "객실·가격 입력 대기"]
    };
  }
  let tone = "watch";
  let label = "보완 필요";
  let headline = "지역 평균 대비 보완할 항목을 확인하세요.";
  let summary = "가격대, 판매 채널, 객실 구성을 지역 평균과 함께 비교하는 것이 좋습니다.";
  if (topAverage > 0 && weeklyRevenue >= topAverage * 0.92) {
    tone = "good";
    label = "상위권 접근 가능";
    headline = "현재 입력값 기준으로 상위권 매출 표본과 비교할 수 있습니다.";
    summary = "주말 가격과 상위 노출 업체의 상품 구성을 우선 비교하면 운영 전략을 잡기 좋습니다.";
  } else if (averageRevenue > 0 && weeklyRevenue >= averageRevenue) {
    tone = "strong";
    label = "지역 평균 이상";
    headline = "지역 평균 매출보다 높은 조건으로 계산됩니다.";
    summary = "가격 경쟁력은 유지하면서 채널 노출과 객실 구성을 함께 점검하세요.";
  } else if (marketAvgPrice > 0 && avgPrice >= marketAvgPrice * 1.18) {
    tone = "watch";
    label = "가격 부담 점검";
    headline = "객실가는 높은 편인데 예상 매출은 평균보다 낮게 계산됩니다.";
    summary = "평일·일요일 가격 또는 패키지 구성을 조정할 여지가 있는지 확인하세요.";
  } else if (channelScore === 0) {
    tone = "watch";
    label = "채널 입력 필요";
    headline = "네이버와 OTA 노출 여부가 비어 있어 비교 정밀도가 낮습니다.";
    summary = "판매 채널을 입력하면 지역 평균과의 비교가 더 명확해집니다.";
  }
  const chips = [
    basisPeriod || `${fmtNumber(basisDays)}일 기준`,
    `예상 ${fmtWon(weeklyRevenue)}`,
    averageRevenue ? `지역 평균 ${b2bMyLodgeDeltaText(weeklyRevenue, averageRevenue)}` : "",
    topAverage ? `상위권 ${b2bMyLodgeDeltaText(weeklyRevenue, topAverage)}` : "",
    marketAvgPrice && avgPrice ? `객실가 ${b2bMyLodgeDeltaText(avgPrice, marketAvgPrice)}` : "",
    channelScore >= 2 ? "네이버+OTA" : channelScore === 1 ? "채널 1개" : "채널 미입력",
    locationLabel
  ].filter(Boolean).slice(0, 7);
  return { tone, label, headline, summary, chips };
}

function b2bMyLodgeOfflineMarketModel(revenueModel = b2bRevenueBenchmarkModel()) {
  const rows = (Array.isArray(revenueModel.rows) ? revenueModel.rows : [])
    .map((row) => {
      const status = collectionStatusProfile(row.item || {});
      const offlineQuantity = finiteNumber(status.offlineQuantity, 0);
      const blockedQuantity = finiteNumber(status.structuralBlockedQuantity, 0);
      return {
        name: row.name || row.item?.name || "업체명 확인",
        rank: row.rank,
        offlineQuantity,
        blockedQuantity,
        offlineEstimated: Boolean(status.offlineEstimated || offlineQuantity > 0),
        note: status.offlineEstimated
          ? "총량 감소·미오픈·차단 신호"
          : blockedQuantity > 0
            ? "운영 축소/상시 차단 신호"
            : "특이 신호 없음"
      };
    });
  const signalRows = rows
    .filter((row) => row.offlineEstimated || row.blockedQuantity > 0)
    .sort((a, b) => (b.offlineQuantity + b.blockedQuantity) - (a.offlineQuantity + a.blockedQuantity))
    .slice(0, 4);
  const offlineTotal = signalRows.reduce((sum, row) => sum + finiteNumber(row.offlineQuantity, 0), 0);
  const blockedTotal = signalRows.reduce((sum, row) => sum + finiteNumber(row.blockedQuantity, 0), 0);
  const signalCount = signalRows.length;
  return {
    tone: signalCount ? "watch" : "good",
    signalCount,
    offlineTotal,
    blockedTotal,
    signalRows,
    summary: signalCount
      ? `경쟁권 ${fmtNumber(signalCount)}곳에서 총량 감소 또는 차단 신호가 보입니다. 실제 판매와 운영 이슈를 구분해 해석해야 합니다.`
      : "현재 경쟁권 표본에서는 총량 감소나 차단 신호가 크게 보이지 않습니다."
  };
}

function b2bMyLodgeReferenceRows(revenueModel = b2bRevenueBenchmarkModel(), fallbackAverage = 0) {
  const sortedRevenueRows = (revenueModel.revenueRows || [])
    .filter((row) => row.revenue > 0)
    .slice()
    .sort((a, b) => b.revenue - a.revenue);
  const averageRevenue = finiteNumber(revenueModel.averageRevenue, 0) || finiteNumber(fallbackAverage, 0);
  const topSlice = sortedRevenueRows.slice(0, Math.min(3, sortedRevenueRows.length));
  const lowSlice = sortedRevenueRows.slice(Math.max(0, sortedRevenueRows.length - Math.min(3, sortedRevenueRows.length)));
  const topAverage = topSlice.length ? topSlice.reduce((sum, row) => sum + row.revenue, 0) / topSlice.length : 0;
  const lowAverage = lowSlice.length ? lowSlice.reduce((sum, row) => sum + row.revenue, 0) / lowSlice.length : 0;
  const marketAvgPriceRows = sortedRevenueRows.filter((row) => row.avgPrice > 0);
  const marketAvgPrice = marketAvgPriceRows.length
    ? marketAvgPriceRows.reduce((sum, row) => sum + row.avgPrice, 0) / marketAvgPriceRows.length
    : 0;
  return [
    {
      key: "top",
      tone: "good",
      label: "상위권 평균",
      name: topSlice.length ? `상위 ${fmtNumber(topSlice.length)}곳` : "상위 표본 대기",
      value: topAverage,
      price: topSlice.length ? topSlice.reduce((sum, row) => sum + finiteNumber(row.avgPrice, 0), 0) / topSlice.filter((row) => row.avgPrice > 0).length : 0,
      note: topAverage ? "상위 매출 표본 평균" : "매출 표본 필요"
    },
    {
      key: "average",
      tone: "strong",
      label: "지역 평균",
      name: `${fmtNumber(sortedRevenueRows.length)}곳 표본`,
      value: averageRevenue,
      price: marketAvgPrice,
      note: averageRevenue ? "지정 검색범위 평균" : "매출 표본 대기"
    },
    {
      key: "low",
      tone: "watch",
      label: "하위권 평균",
      name: lowSlice.length ? `하위 ${fmtNumber(lowSlice.length)}곳` : "하위 표본 대기",
      value: lowAverage,
      price: lowSlice.length ? lowSlice.reduce((sum, row) => sum + finiteNumber(row.avgPrice, 0), 0) / lowSlice.filter((row) => row.avgPrice > 0).length : 0,
      note: lowAverage ? "하위 매출 표본 평균" : "매출 표본 필요"
    }
  ].map((row) => ({
    ...row,
    price: Number.isFinite(row.price) && row.price > 0 ? row.price : 0
  }));
}

function b2bInterestLodgeComparisonRows(interestLodges = [], brief = b2bMarketBriefModel(), revenueModel = b2bRevenueBenchmarkModel(brief), previewModel = null) {
  const lodgeRows = (Array.isArray(interestLodges) ? interestLodges : [])
    .map((lodge, index) => {
      const model = b2bMyLodgeBenchmarkModel(brief, revenueModel, lodge);
      return {
        key: `interest-${index}`,
        tone: model.comparisonConclusion?.tone || "neutral",
        label: `관심숙소 ${fmtNumber(index + 1)}`,
        name: String(lodge.lodgingName || `관심숙소 ${index + 1}`).trim(),
        value: model.weeklyRevenue,
        price: model.avgPrice,
        rooms: model.roomCount,
        note: model.comparisonConclusion?.label || "비교 대기",
        channels: model.channelLabels.join(" + ") || "채널 미입력"
      };
    });
  const previewRow = previewModel?.hasInput ? [{
    key: "preview",
    tone: previewModel.comparisonConclusion?.tone || "mine",
    label: "입력 중",
    name: String(previewModel.draft?.lodgingName || "미리보기").trim(),
    value: previewModel.weeklyRevenue,
    price: previewModel.avgPrice,
    rooms: previewModel.roomCount,
    note: previewModel.hasEstimateBasis ? previewModel.comparisonConclusion?.label || "비교 중" : "매출 입력 대기",
    channels: previewModel.channelLabels.join(" + ") || "채널 미입력"
  }] : [];
  const referenceRows = b2bMyLodgeReferenceRows(revenueModel, brief.averageRevenue);
  const rows = [...lodgeRows, ...previewRow, ...referenceRows].filter((row) => row.value > 0 || row.key === "preview");
  const maxValue = Math.max(...rows.map((row) => finiteNumber(row.value, 0)), 1);
  return rows.map((row) => ({
    ...row,
    width: Math.max(row.value > 0 ? 8 : 0, Math.min(100, Math.round((finiteNumber(row.value, 0) / maxValue) * 100)))
  }));
}

function renderB2BMyLodgeComparisonBoard(interestLodges = [], brief = b2bMarketBriefModel(), revenueModel = b2bRevenueBenchmarkModel(brief), previewModel = null) {
  if (!interestLodges.length && !previewModel?.hasInput) return "";
  const rows = b2bInterestLodgeComparisonRows(interestLodges, brief, revenueModel, previewModel);
  if (!rows.length) return "";
  const basisPeriod = previewModel?.basisPeriod || b2bDateRangeLabel(state.data?.run || {}) || `${fmtNumber(DEFAULT_BOOKING_DAYS)}일 기준`;
  return `
    <article class="b2b-my-lodge-compare-board">
      <div class="b2b-my-lodge-subhead">
        <strong>7일 기준 매출 위치</strong>
        <small>${escapeHtml(basisPeriod)} · 관심숙소와 지역 표본 비교</small>
      </div>
      <div class="b2b-my-lodge-compare-list">
        ${rows.map((row) => `
          <div class="b2b-my-lodge-compare-row ${escapeHtml(row.tone)}" style="--bar:${row.width}%">
            <div>
              <span>${escapeHtml(row.label)}</span>
              <strong>${escapeHtml(row.name || row.label)}</strong>
              <small>${escapeHtml([row.rooms ? `${fmtNumber(row.rooms)}실` : "", row.price ? `객실가 ${fmtWon(row.price)}` : "", row.channels, row.note].filter(Boolean).join(" · "))}</small>
            </div>
            <i><b></b></i>
            <em>${row.value ? fmtWon(row.value) : "대기"}</em>
          </div>
        `).join("")}
      </div>
    </article>
  `;
}

function renderB2BMyLodgeOfflineBoard(revenueModel = b2bRevenueBenchmarkModel()) {
  const model = b2bMyLodgeOfflineMarketModel(revenueModel);
  if (!model.signalCount) return "";
  return `
    <article class="b2b-my-lodge-offline-board ${escapeHtml(model.tone)}">
      <div class="b2b-my-lodge-subhead">
        <strong>오프라인 판매/차단 추정</strong>
        <small>총량 감소가 보이는 경쟁업체를 별도 참고 지표로 표시합니다.</small>
      </div>
      <div class="b2b-my-lodge-offline-summary">
        <div><span>신호 업체</span><strong>${fmtNumber(model.signalCount)}곳</strong></div>
        <div><span>오프라인 추정</span><strong>${fmtNumber(model.offlineTotal)}개/회</strong></div>
        <div><span>차단·축소 추정</span><strong>${fmtNumber(model.blockedTotal)}개/회</strong></div>
      </div>
      <p>${escapeHtml(model.summary)}</p>
      <div class="b2b-my-lodge-offline-list">
        ${model.signalRows.map((row) => `
          <span>${escapeHtml(row.name)} · ${row.offlineQuantity ? `오프라인 ${fmtNumber(row.offlineQuantity)}개/회` : ""}${row.blockedQuantity ? `${row.offlineQuantity ? " · " : ""}차단 ${fmtNumber(row.blockedQuantity)}개/회` : ""}</span>
        `).join("")}
      </div>
    </article>
  `;
}

function b2bMyLodgeBenchmarkModel(brief = b2bMarketBriefModel(), revenueModel = b2bRevenueBenchmarkModel(brief), draftOverride = null) {
  const draft = draftOverride && typeof draftOverride === "object" ? draftOverride : readB2BMyLodgeDraft();
  const collectionPrecision = b2bMyLodgeCollectionPrecisionInfo(draft);
  const roomSegments = b2bMyLodgeSegmentRows(draft);
  const segmentRoomCount = roomSegments.reduce((sum, row) => sum + Math.round(b2bMyLodgeNumber(row.count)), 0);
  const roomCount = Math.round(b2bMyLodgeNumber(draft.roomCount)) || segmentRoomCount;
  const segmentTypes = roomSegments.map((row) => row.type).filter(Boolean);
  const roomType = String(draft.roomType || segmentTypes.slice(0, 4).join(", ")).trim();
  const dayUseCount = Math.round(b2bMyLodgeNumber(draft.dayUseCount));
  const weekdayPrice = b2bMyLodgeNumber(draft.weekdayPrice);
  const fridayPrice = b2bMyLodgeNumber(draft.fridayPrice);
  const saturdayPrice = b2bMyLodgeNumber(draft.saturdayPrice);
  const sundayPrice = b2bMyLodgeNumber(draft.sundayPrice);
  const avgPrice = roomSegments.length ? b2bMyLodgeAveragePriceFromSegments(roomSegments) : b2bMyLodgeAveragePrice(draft);
  const hasSegmentEstimateBasis = roomSegments.some((row) =>
    b2bMyLodgeNumber(row.count) > 0 && B2B_MY_LODGE_PRICE_KEYS.some((key) => b2bMyLodgeNumber(row[key]) > 0)
  );
  const hasInput = Boolean(String(draft.lodgingName || "").trim()) || roomCount > 0 || roomType || dayUseCount > 0 || avgPrice > 0 || roomSegments.length > 0;
  const hasEstimateBasis = hasSegmentEstimateBasis || (roomCount > 0 && avgPrice > 0);
  const fallbackRate = Number.isFinite(brief.rate) ? brief.rate : b2bMyLodgeRate(revenueModel.flow, "all", 0.25);
  const rates = {
    weekday: b2bMyLodgeRate(revenueModel.flow, "weekday", fallbackRate),
    friday: b2bMyLodgeRate(revenueModel.flow, "friday", fallbackRate),
    saturday: b2bMyLodgeRate(revenueModel.flow, "saturday", fallbackRate),
    sunday: b2bMyLodgeRate(revenueModel.flow, "sunday", fallbackRate)
  };
  const basisRun = b2bMyLodgeBasisRun();
  const basisPeriod = b2bDateRangeLabel(basisRun);
  const dayCounts = b2bMyLodgeDayTypeCounts(basisRun);
  const basisDays = Object.values(dayCounts).reduce((sum, count) => sum + count, 0);
  const legacyWeeklyRevenue = hasEstimateBasis
    ? Math.round((
      roomCount * weekdayPrice * rates.weekday * dayCounts.weekday +
      roomCount * fridayPrice * rates.friday * dayCounts.friday +
      roomCount * saturdayPrice * rates.saturday * dayCounts.saturday +
      roomCount * sundayPrice * rates.sunday * dayCounts.sunday
    ) / 1000) * 1000
    : 0;
  const segmentWeeklyRevenue = hasSegmentEstimateBasis
    ? Math.round(b2bMyLodgeSegmentRevenue(roomSegments, rates, dayCounts) / 1000) * 1000
    : 0;
  const weeklyRevenue = hasSegmentEstimateBasis ? segmentWeeklyRevenue : legacyWeeklyRevenue;
  const sortedRevenueRows = (revenueModel.revenueRows || [])
    .filter((row) => row.revenue > 0)
    .slice()
    .sort((a, b) => b.revenue - a.revenue);
  const topSlice = sortedRevenueRows.slice(0, Math.min(3, sortedRevenueRows.length));
  const lowSlice = sortedRevenueRows.slice(Math.max(0, sortedRevenueRows.length - Math.min(3, sortedRevenueRows.length)));
  const topAverage = topSlice.length ? topSlice.reduce((sum, row) => sum + row.revenue, 0) / topSlice.length : 0;
  const lowAverage = lowSlice.length ? lowSlice.reduce((sum, row) => sum + row.revenue, 0) / lowSlice.length : 0;
  const marketAvgPriceRows = sortedRevenueRows.filter((row) => row.avgPrice > 0);
  const marketAvgPrice = marketAvgPriceRows.length
    ? marketAvgPriceRows.reduce((sum, row) => sum + row.avgPrice, 0) / marketAvgPriceRows.length
    : 0;
  const averageRevenue = finiteNumber(revenueModel.averageRevenue, 0) || finiteNumber(brief.averageRevenue, 0);
  const maxRevenue = finiteNumber(revenueModel.revenueMax, 0);
  const maxChartValue = Math.max(weeklyRevenue, averageRevenue, topAverage, lowAverage, maxRevenue, 1);
  const channelLabels = [
    draft.naverConnected ? "네이버 노출" : "",
    draft.otaConnected ? "OTA 노출" : ""
  ].filter(Boolean);
  const channelScore = (draft.naverConnected ? 1 : 0) + (draft.otaConnected ? 1 : 0);
  const locationContext = b2bLocationScoreContext(brief);
  const lodgeBoundary = draft.regionBoundaryStatus || draft.addressRegion
    ? b2bBoundaryProfile({
      searchRegion: draft.searchRegion || brief.keyword || activeKeyword(),
      addressRegion: draft.addressRegion,
      region: draft.addressRegion,
      regionBoundaryStatus: draft.regionBoundaryStatus,
      regionBoundaryDetail: draft.regionBoundaryDetail,
      outsideSearchRegion: draft.outsideSearchRegion
    })
    : null;
  const locationConclusion = b2bLocationConclusion(locationContext, lodgeBoundary);
  const facilities = b2bMyLodgeFacilities(draft.facilities);
  const segmentBasisText = hasSegmentEstimateBasis
    ? `${fmtNumber(roomSegments.length)}개 객실종류 · 요일별 가격 기준`
    : "입력 객실수와 요일별 가격 기준";
  const benchmarkRows = [
    { label: "관심숙소", value: weeklyRevenue, note: segmentBasisText, tone: hasEstimateBasis ? "mine" : "neutral" },
    { label: "지역 평균", value: averageRevenue, note: `${fmtNumber(sortedRevenueRows.length)}개 매출 표본 평균`, tone: "strong" },
    { label: "상위권 평균", value: topAverage, note: topSlice.length ? `상위 ${fmtNumber(topSlice.length)}개 평균` : "상위 표본 대기", tone: "good" },
    { label: "하위권 평균", value: lowAverage, note: lowSlice.length ? `하위 ${fmtNumber(lowSlice.length)}개 평균` : "하위 표본 대기", tone: "watch" },
    { label: "매출 상위", value: maxRevenue, note: sortedRevenueRows[0]?.name || "최고 표본 대기", tone: "hot" }
  ].map((row) => ({
    ...row,
    width: Math.max(row.value > 0 ? 8 : 0, Math.min(100, Math.round((row.value / maxChartValue) * 100)))
  }));
  const cards = [
    {
      tone: hasEstimateBasis ? "mine" : "neutral",
      label: "내 예상 기간 매출",
      value: hasEstimateBasis ? fmtWon(weeklyRevenue) : "입력 대기",
      note: hasSegmentEstimateBasis
        ? `${fmtNumber(roomSegments.length)}개 객실종류 · ${fmtNumber(basisDays)}일 예약율 반영`
        : `${fmtNumber(basisDays)}일 검색기간 예약율 반영`
    },
    {
      tone: b2bMyLodgeDeltaTone(weeklyRevenue, averageRevenue),
      label: "지역 평균 대비",
      value: hasEstimateBasis ? b2bMyLodgeDeltaText(weeklyRevenue, averageRevenue) : "입력 대기",
      note: averageRevenue ? `지역 평균 ${fmtWon(averageRevenue)}` : "매출 표본 대기"
    },
    {
      tone: b2bMyLodgeDeltaTone(weeklyRevenue, topAverage),
      label: "상위권 대비",
      value: hasEstimateBasis ? b2bMyLodgeDeltaText(weeklyRevenue, topAverage) : "입력 대기",
      note: topAverage ? `상위권 평균 ${fmtWon(topAverage)}` : "상위 표본 대기"
    },
    {
      tone: marketAvgPrice && avgPrice >= marketAvgPrice ? "strong" : "watch",
      label: "평균 객실가",
      value: avgPrice ? fmtWon(avgPrice) : "입력 대기",
      note: marketAvgPrice ? `경쟁 평균 ${fmtWon(marketAvgPrice)}` : "가격 표본 대기"
    },
    {
      tone: channelScore >= 2 ? "good" : channelScore === 1 ? "strong" : "watch",
      label: "판매 채널",
      value: channelLabels.length ? channelLabels.join(" + ") : "미입력",
      note: "공유 재고 가능 · 매출 중복 가산 없음"
    },
    {
      tone: locationConclusion.tone,
      label: "입지 판단",
      value: locationConclusion.label,
      note: locationConclusion.scoreText ? `${locationConclusion.scoreText} · ${locationConclusion.sourceLabel}` : locationConclusion.sourceLabel
    }
  ];
  const comparisonConclusion = b2bMyLodgeComparisonConclusion({
    hasEstimateBasis,
    weeklyRevenue,
    averageRevenue,
    topAverage,
    avgPrice,
    marketAvgPrice,
    channelScore,
    locationConclusion,
    basisDays,
    basisPeriod
  });
  return {
    draft,
    hasInput,
    hasEstimateBasis,
    roomCount,
    roomType,
    dayUseCount,
    roomSegments,
    segmentRoomCount,
    avgPrice,
    weeklyRevenue,
    rates,
    dayCounts,
    basisDays,
    basisPeriod,
    cards,
    benchmarkRows,
    comparisonConclusion,
    locationConclusion,
    collectionPrecision,
    facilities,
    channelLabels,
    savedAt: draft.savedAt || "",
    storageKey: b2bMyLodgeStorageKey()
  };
}

function renderB2BMyLodgePrecisionNote(precision = {}) {
  if (!precision.visible) return "";
  const chips = [
    ...(precision.reasons || []),
    precision.manualAdjusted ? "수동 보정 반영" : "",
    ...(precision.warnings || []).map((item) => `보완: ${item}`)
  ].filter(Boolean).slice(0, 6);
  return `
    <div class="b2b-my-lodge-precision ${escapeHtml(precision.tone || "neutral")}">
      <div>
        <span>수집 정밀도</span>
        <strong>${escapeHtml(precision.label || "확인 필요")}${precision.grade ? ` · ${escapeHtml(precision.grade)}등급` : ""}</strong>
        <small>${escapeHtml(precision.basis || "자동수집 근거를 확인합니다.")}</small>
      </div>
      ${precision.score ? `<em>${fmtNumber(precision.score)}점</em>` : ""}
      ${chips.length ? `<p>${chips.map((chip) => `<b>${escapeHtml(chip)}</b>`).join("")}</p>` : ""}
    </div>
  `;
}

function renderB2BInterestLodgeCards(interestLodges = [], brief = b2bMarketBriefModel(), revenueModel = b2bRevenueBenchmarkModel(brief)) {
  if (!interestLodges.length) return "";
  return `
    <div class="b2b-interest-lodge-grid" aria-label="등록된 관심숙소">
      ${interestLodges.map((lodge, index) => {
        const model = b2bMyLodgeBenchmarkModel(brief, revenueModel, lodge);
        const name = String(lodge.lodgingName || `관심숙소 ${index + 1}`).trim();
        const actionId = lodge.id || b2bStableInterestLodgeId(lodge) || b2bInterestLodgeMatchKey(lodge) || `index-${index}`;
        const conclusion = model.comparisonConclusion || b2bMyLodgeComparisonConclusion(model);
        const precision = model.collectionPrecision || {};
        const facilities = model.facilities.length ? model.facilities.slice(0, 4) : [];
        const segmentLabels = model.roomSegments.map((row) => row.type).filter(Boolean).slice(0, 4);
        const chips = [
          precision.label ? precision.label : "",
          precision.manualAdjusted ? "수동 보정" : "",
          model.roomCount ? `${fmtNumber(model.roomCount)}실` : "",
          model.dayUseCount ? `데이유즈 ${fmtNumber(model.dayUseCount)}회` : "",
          ...segmentLabels,
          ...model.channelLabels,
          ...facilities
        ].filter(Boolean).slice(0, 8);
        return `
          <article class="b2b-interest-lodge-card">
            <div class="b2b-interest-lodge-card-head">
              <span>관심숙소 ${fmtNumber(index + 1)}</span>
              <strong>${escapeHtml(name)}</strong>
              <small>${escapeHtml(`${fmtNumber(model.basisDays || DEFAULT_BOOKING_DAYS)}일 기준 예상 매출 · ${model.basisPeriod || "기간 확인"}`)}</small>
              <em>${model.hasEstimateBasis ? fmtWon(model.weeklyRevenue) : "매출 입력 대기"}</em>
            </div>
            <div class="b2b-interest-lodge-decision ${escapeHtml(conclusion.tone)}">
              <span>비교 결론</span>
              <strong>${escapeHtml(conclusion.label)}</strong>
              <small>${escapeHtml(conclusion.headline)}</small>
            </div>
            ${precision.visible ? `<div class="b2b-interest-lodge-source ${escapeHtml(precision.tone || "neutral")}"><span>${escapeHtml(precision.label || "수집 기준")}</span><strong>${precision.score ? `${fmtNumber(precision.score)}점` : precision.manualAdjusted ? "수동 보정" : "근거 확인"}</strong><small>${escapeHtml(precision.basis || lodge.collectionStatus || "")}</small></div>` : ""}
            <div class="b2b-interest-lodge-metrics">
              <div><span>객실</span><strong>${model.roomCount ? `${fmtNumber(model.roomCount)}실` : "대기"}</strong></div>
              <div><span>평균 객실가</span><strong>${model.avgPrice ? fmtWon(model.avgPrice) : "대기"}</strong></div>
              <div><span>판매 채널</span><strong>${model.channelLabels.length ? escapeHtml(model.channelLabels.join(" + ")) : "미입력"}</strong></div>
            </div>
            <div class="b2b-interest-lodge-location ${escapeHtml(model.locationConclusion.tone)}">
              <span>입지 비교</span>
              <strong>${escapeHtml(model.locationConclusion.label)}</strong>
              <small>${escapeHtml(model.locationConclusion.headline)}</small>
            </div>
            <div class="b2b-interest-lodge-tags">
              ${chips.length ? chips.map((chip) => `<em>${escapeHtml(chip)}</em>`).join("") : "<em>상세 입력 대기</em>"}
            </div>
            <div class="b2b-interest-lodge-actions">
              <button class="secondary-button" type="button" data-b2b-interest-lodge-edit="${escapeHtml(actionId)}" data-b2b-interest-lodge-index="${index}">수정</button>
              <button class="ghost-button" type="button" data-b2b-interest-lodge-delete="${escapeHtml(actionId)}" data-b2b-interest-lodge-index="${index}">삭제</button>
            </div>
          </article>
        `;
      }).join("")}
    </div>
  `;
}

function renderB2BMyLodgeBenchmark(brief = b2bMarketBriefModel(), model = b2bMyLodgeBenchmarkModel(brief), revenueModelOverride = null) {
  const draft = model.draft || {};
  const name = String(draft.lodgingName || "").trim();
  const collecting = Boolean(state.b2bMyLodgeCollecting);
  const collectStatus = state.b2bMyLodgeCollectStatus || draft.collectionStatus || "";
  const revenueModel = revenueModelOverride || b2bRevenueBenchmarkModel(brief);
  const interestLodges = readB2BInterestLodges();
  const canRegisterMore = interestLodges.length < B2B_INTEREST_LODGE_LIMIT;
  const editorOpen = canRegisterMore && (Boolean(state.b2bMyLodgeExpanded) || collecting);
  const editingInterestLodge = Boolean(state.b2bMyLodgeEditing && b2bMyLodgeDraftHasInput(draft));
  const facilities = model.facilities.length ? model.facilities : ["시설 입력 대기"];
  const inputSegments = b2bMyLodgeSegmentInputRows(draft);
  const segmentRows = inputSegments.length ? inputSegments : [b2bMyLodgeBlankSegment()];
  const roomCountValue = draft.roomCount || (model.segmentRoomCount ? String(model.segmentRoomCount) : "");
  const segmentPriceValue = (row, key) => escapeHtml(b2bMyLodgeInputNumberText(row[key]));
  const segmentRowHtml = segmentRows.map((row, index) => `
    <div class="b2b-room-segment-row" data-b2b-room-segment-row>
      <label>
        <span>객실 종류</span>
        <input name="segmentType" type="text" maxlength="80" value="${escapeHtml(row.type || "")}" placeholder="글램핑, 카라반">
      </label>
      <label>
        <span>수량</span>
        <input name="segmentCount" type="number" min="0" step="1" inputmode="numeric" value="${escapeHtml(row.count || "")}" placeholder="예: 6">
      </label>
      <label>
        <span>평일</span>
        <input name="segmentWeekdayPrice" type="text" inputmode="numeric" data-b2b-won-input value="${segmentPriceValue(row, "weekdayPrice")}" placeholder="120,000">
      </label>
      <label>
        <span>금</span>
        <input name="segmentFridayPrice" type="text" inputmode="numeric" data-b2b-won-input value="${segmentPriceValue(row, "fridayPrice")}" placeholder="160,000">
      </label>
      <label>
        <span>토</span>
        <input name="segmentSaturdayPrice" type="text" inputmode="numeric" data-b2b-won-input value="${segmentPriceValue(row, "saturdayPrice")}" placeholder="220,000">
      </label>
      <label>
        <span>일</span>
        <input name="segmentSundayPrice" type="text" inputmode="numeric" data-b2b-won-input value="${segmentPriceValue(row, "sundayPrice")}" placeholder="140,000">
      </label>
      <button class="b2b-room-segment-remove" type="button" data-b2b-room-segment-remove="${index}" aria-label="객실종류 삭제" ${segmentRows.length <= 1 ? "disabled" : ""}>×</button>
    </div>
  `).join("");
  return `
    <div class="b2b-my-lodge-board">
      <div class="b2b-my-lodge-head">
        <div>
          <span>비교 기준 설정</span>
          <strong>내 숙소 정보 입력</strong>
          <p>비교할 숙소를 최대 2곳까지 저장하고, 객실종류별 수량·요일 가격으로 지역 평균·상위권 매출 표본과 비교합니다.</p>
        </div>
        <div class="b2b-my-lodge-head-actions">
          <em>${state.b2bInterestLodgeSyncing ? "저장 중" : state.b2bInterestLodgeSyncError ? "저장 확인 필요" : "계정 저장"}</em>
          <em>${fmtNumber(interestLodges.length)}/${fmtNumber(B2B_INTEREST_LODGE_LIMIT)} 등록</em>
          ${canRegisterMore ? `
            <button class="b2b-my-lodge-toggle" type="button" data-b2b-my-lodge-toggle aria-expanded="${editorOpen ? "true" : "false"}">
              <span aria-hidden="true">${editorOpen ? "−" : "+"}</span>
              <b>${editorOpen ? "접기" : "등록"}</b>
            </button>
          ` : ""}
        </div>
      </div>
      ${state.b2bInterestLodgeSyncError ? `<div class="b2b-my-lodge-sync-note">${escapeHtml(state.b2bInterestLodgeSyncError)} 브라우저에는 임시 보관되어 있습니다.</div>` : ""}
      ${renderB2BInterestLodgeCards(interestLodges, brief, revenueModel)}
      ${renderB2BMyLodgeComparisonBoard(interestLodges, brief, revenueModel, editorOpen && model.hasInput ? model : null)}
      ${interestLodges.length || (editorOpen && model.hasInput) ? renderB2BMyLodgeOfflineBoard(revenueModel) : ""}
      ${canRegisterMore && editorOpen ? `
      <form class="b2b-my-lodge-form" data-b2b-my-lodge-form>
        <label class="b2b-my-lodge-field name">
          <span>숙소명</span>
          <input name="lodgingName" type="text" maxlength="80" value="${escapeHtml(name)}" placeholder="지역명 + 운영업체명">
        </label>
        <label class="b2b-my-lodge-field">
          <span>객실 수(총량)</span>
          <input name="roomCount" type="number" min="0" step="1" value="${escapeHtml(roomCountValue)}" placeholder="12">
        </label>
        <label class="b2b-my-lodge-field">
          <span>데이유즈</span>
          <input name="dayUseCount" type="number" min="0" step="1" inputmode="numeric" value="${escapeHtml(draft.dayUseCount ?? "")}" placeholder="예: 6">
        </label>
        <label class="b2b-my-lodge-field facilities">
          <span>시설</span>
          <input name="facilities" type="text" maxlength="160" value="${escapeHtml(draft.facilities || "")}" placeholder="개별화장실, 수영장, 바비큐">
        </label>
        <div class="b2b-room-segment-panel" data-b2b-room-segments>
          <div class="b2b-room-segment-head">
            <div>
              <strong>객실종류별 가격</strong>
              <span>객실 종류를 추가해 세그먼트별 객실수와 평일·금·토·일 가격을 입력합니다.</span>
            </div>
            <button class="secondary-button" type="button" data-b2b-room-segment-add ${segmentRows.length >= B2B_MY_LODGE_SEGMENT_LIMIT ? "disabled" : ""}>객실종류 +</button>
          </div>
          <div class="b2b-room-segment-list">
            ${segmentRowHtml}
          </div>
        </div>
        <div class="b2b-my-lodge-checks" aria-label="판매 채널 참고">
          <label><input name="naverConnected" type="checkbox" ${draft.naverConnected ? "checked" : ""}> 네이버 노출</label>
          <label><input name="otaConnected" type="checkbox" ${draft.otaConnected ? "checked" : ""}> OTA 노출</label>
        </div>
        <div class="b2b-my-lodge-channel-note">네이버/OTA는 같은 객실 재고를 공유할 수 있어 매출 산정에는 중복 가산하지 않습니다.</div>
        <div class="b2b-my-lodge-actions">
          <button class="secondary-button collect" type="button" data-b2b-my-lodge-collect ${collecting ? "disabled" : ""}>${collecting ? "숙소명 찾는 중" : "숙소명으로 찾기"}</button>
          <button class="primary-button" type="button" data-b2b-my-lodge-save>${editingInterestLodge ? "수정 저장" : "등록하기"}</button>
          <button class="secondary-button" type="button" data-b2b-my-lodge-clear ${model.hasInput ? "" : "disabled"}>입력 초기화</button>
        </div>
        ${collectStatus ? `<div class="b2b-my-lodge-collect-status ${collecting ? "loading" : ""}">${escapeHtml(collectStatus)}</div>` : ""}
        ${renderB2BMyLodgePrecisionNote(model.collectionPrecision || {})}
      </form>
      ` : !canRegisterMore ? `
        <div class="b2b-interest-lodge-limit">
          <strong>관심숙소는 최대 ${fmtNumber(B2B_INTEREST_LODGE_LIMIT)}곳까지 등록됩니다.</strong>
          <span>다른 숙소를 비교하려면 기존 관심숙소를 수정하거나 삭제하세요.</span>
        </div>
      ` : ""}
      ${canRegisterMore && editorOpen && model.hasInput ? `
      <div class="b2b-my-lodge-result ${model.hasEstimateBasis ? "ready" : "empty"}">
        <article class="b2b-my-lodge-main">
          <span>${escapeHtml(`${fmtNumber(model.basisDays || DEFAULT_BOOKING_DAYS)}일 기준 예상 매출 · ${model.basisPeriod || "기간 확인"}`)}</span>
          <strong>${model.hasEstimateBasis ? fmtWon(model.weeklyRevenue) : "입력 후 비교"}</strong>
          <small>${escapeHtml(name || "관심숙소 미리보기")} · 객실수/요일가격 × 경쟁권 예약율: 평일 ${fmtRate(model.rates.weekday)} · 금 ${fmtRate(model.rates.friday)} · 토 ${fmtRate(model.rates.saturday)} · 일 ${fmtRate(model.rates.sunday)}</small>
          <div class="b2b-my-lodge-tags">
            <em>${fmtNumber(model.roomCount)}실</em>
            ${model.roomType ? `<em>${escapeHtml(model.roomType)}</em>` : ""}
            ${model.dayUseCount ? `<em>데이유즈 ${fmtNumber(model.dayUseCount)}회</em>` : ""}
            ${facilities.map((item) => `<em>${escapeHtml(item)}</em>`).join("")}
          </div>
        </article>
        <div class="b2b-my-lodge-cards">
          ${model.cards.map((card) => `
            <article class="${escapeHtml(card.tone)}">
              <span>${escapeHtml(card.label)}</span>
              <strong>${escapeHtml(card.value)}</strong>
              <small>${escapeHtml(card.note)}</small>
            </article>
          `).join("")}
        </div>
        <article class="b2b-my-lodge-decision ${escapeHtml(model.comparisonConclusion.tone)}">
          <span>비교 결론</span>
          <strong>${escapeHtml(model.comparisonConclusion.label)}</strong>
          <p>${escapeHtml(model.comparisonConclusion.summary)}</p>
          <div>
            ${model.comparisonConclusion.chips.map((chip) => `<em>${escapeHtml(chip)}</em>`).join("")}
          </div>
        </article>
        ${renderB2BMyLodgePrecisionNote(model.collectionPrecision || {})}
        <article class="b2b-my-lodge-chart">
          <div class="b2b-my-lodge-subhead">
            <strong>매출 포지션 비교</strong>
            <small>관심숙소 vs 지역 평균·상위권·하위권·매출 상위</small>
          </div>
          ${model.benchmarkRows.map((row) => `
            <div class="b2b-my-lodge-row ${escapeHtml(row.tone)}" style="--bar:${row.width}%">
              <span>${escapeHtml(row.label)}</span>
              <i><b></b></i>
              <strong>${row.value ? fmtWon(row.value) : "대기"}</strong>
              <small>${escapeHtml(row.note)}</small>
            </div>
          `).join("")}
        </article>
      </div>
      ` : ""}
    </div>
  `;
}

function collectB2BMyLodgeSegmentFormRows({ includeBlank = false } = {}) {
  const form = document.querySelector("[data-b2b-my-lodge-form]");
  if (!form) return [];
  const rows = Array.from(form.querySelectorAll("[data-b2b-room-segment-row]"))
    .map((row) => {
      const rowValue = (name) => String(row.querySelector(`[name="${name}"]`)?.value || "").trim();
      const rowNumber = (name) => {
        const number = b2bMyLodgeNumber(rowValue(name));
        return number > 0 ? String(Math.round(number)) : "";
      };
      return {
        type: rowValue("segmentType").slice(0, 80),
        count: rowNumber("segmentCount"),
        weekdayPrice: rowNumber("segmentWeekdayPrice"),
        fridayPrice: rowNumber("segmentFridayPrice"),
        saturdayPrice: rowNumber("segmentSaturdayPrice"),
        sundayPrice: rowNumber("segmentSundayPrice")
      };
    })
    .slice(0, B2B_MY_LODGE_SEGMENT_LIMIT);
  return includeBlank ? rows : rows.filter((row) => b2bMyLodgeSegmentHasInput(row));
}

function collectB2BMyLodgeFormValues() {
  const form = document.querySelector("[data-b2b-my-lodge-form]");
  if (!form) return null;
  const currentDraft = readB2BMyLodgeDraft();
  const formData = new FormData(form);
  const value = (name) => String(formData.get(name) || "").trim();
  const numberValue = (name) => {
    const number = b2bMyLodgeNumber(value(name));
    return number > 0 ? String(Math.round(number)) : "";
  };
  const segmentRows = collectB2BMyLodgeSegmentFormRows();
  const segmentTotal = segmentRows.reduce((sum, row) => sum + Math.round(b2bMyLodgeNumber(row.count)), 0);
  const firstSegment = segmentRows[0] || {};
  const roomType = segmentRows.map((row) => row.type).filter(Boolean).slice(0, 4).join(", ");
  const values = {
    lodgingName: value("lodgingName").slice(0, 80),
    roomCount: numberValue("roomCount") || (segmentTotal > 0 ? String(segmentTotal) : ""),
    roomType: roomType.slice(0, 80),
    dayUseCount: numberValue("dayUseCount"),
    weekdayPrice: firstSegment.weekdayPrice || "",
    fridayPrice: firstSegment.fridayPrice || "",
    saturdayPrice: firstSegment.saturdayPrice || "",
    sundayPrice: firstSegment.sundayPrice || "",
    roomSegments: segmentRows,
    facilities: value("facilities").slice(0, 160),
    naverConnected: Boolean(form.querySelector('input[name="naverConnected"]')?.checked),
    otaConnected: Boolean(form.querySelector('input[name="otaConnected"]')?.checked),
    savedAt: new Date().toISOString()
  };
  const metadata = b2bMyLodgeCollectionMetadata(currentDraft);
  const manualAdjusted = b2bMyLodgeWasManuallyAdjusted(currentDraft, values);
  const next = {
    ...values,
    ...metadata,
    manualAdjusted: Boolean(metadata.manualAdjusted || manualAdjusted),
    manualAdjustedAt: metadata.manualAdjustedAt || (manualAdjusted ? new Date().toISOString() : "")
  };
  if (manualAdjusted) {
    next.collectionStatus = `${next.lodgingName || "관심숙소"} 수동 보정 반영 · 자동 수집값에서 일부 수정`;
  }
  return next;
}

function persistB2BMyLodgeStore(store = {}, options = {}) {
  const { syncInterestLodges = true } = options;
  const values = {
    version: 2,
    draft: store.draft && typeof store.draft === "object" ? store.draft : {},
    interestLodges: (Array.isArray(store.interestLodges) ? store.interestLodges : [])
      .map((lodge) => b2bNormalizeInterestLodge(lodge))
      .filter((lodge) => b2bMyLodgeDraftHasInput(lodge))
      .slice(0, B2B_INTEREST_LODGE_LIMIT)
  };
  state.b2bMyLodgeDraft = { key: b2bMyLodgeStorageKey(), values };
  try {
    if (typeof localStorage !== "undefined") {
      localStorage.setItem(b2bMyLodgeStorageKey(), JSON.stringify({ ...values, draft: {} }));
      clearB2BMyLodgeLegacyStorageKeys();
    }
  } catch {
    // The comparison still renders from memory if browser storage is blocked.
  }
  if (syncInterestLodges && !isAdminRole()) {
    syncB2BInterestLodgesToServer(values.interestLodges);
  }
}

function persistB2BMyLodgeDraft(values = {}) {
  const store = readB2BMyLodgeStore();
  persistB2BMyLodgeStore({ ...store, draft: values }, { syncInterestLodges: false });
}

function saveB2BMyLodgeBenchmark() {
  const values = collectB2BMyLodgeFormValues();
  if (!values) return;
  const store = readB2BMyLodgeStore();
  const interestLodges = Array.isArray(store.interestLodges) ? store.interestLodges.slice(0, B2B_INTEREST_LODGE_LIMIT) : [];
  if (interestLodges.length >= B2B_INTEREST_LODGE_LIMIT) {
    state.b2bMyLodgeCollectStatus = `관심숙소는 최대 ${fmtNumber(B2B_INTEREST_LODGE_LIMIT)}곳까지 등록할 수 있습니다.`;
    state.b2bMyLodgeExpanded = false;
    renderReport();
    return;
  }
  if (!b2bMyLodgeDraftHasInput(values) || !String(values.lodgingName || "").trim()) {
    state.b2bMyLodgeCollectStatus = "관심숙소명을 먼저 입력하세요.";
    state.b2bMyLodgeExpanded = true;
    persistB2BMyLodgeStore({ ...store, draft: values, interestLodges }, { syncInterestLodges: false });
    renderReport();
    document.querySelector(".b2b-my-lodge-board")?.scrollIntoView({ behavior: "smooth", block: "nearest" });
    return;
  }
  const lodge = b2bNormalizeInterestLodge({
    ...values,
    id: b2bNewInterestLodgeId(),
    savedAt: new Date().toISOString(),
    registeredAt: new Date().toISOString()
  });
  interestLodges.push(lodge);
  state.b2bMyLodgeCollectStatus = "";
  state.b2bMyLodgeExpanded = false;
  state.b2bMyLodgeEditing = false;
  persistB2BMyLodgeStore({ ...store, draft: {}, interestLodges });
  renderReport();
  document.querySelector(".b2b-my-lodge-board")?.scrollIntoView({ behavior: "smooth", block: "nearest" });
}

function editB2BInterestLodge(lodgeId = "", fallbackIndex = -1) {
  const store = readB2BMyLodgeStore();
  const interestLodges = Array.isArray(store.interestLodges) ? store.interestLodges : [];
  const targetIndex = b2bInterestLodgeTargetIndex(interestLodges, lodgeId, fallbackIndex);
  const target = targetIndex >= 0 ? interestLodges[targetIndex] : null;
  if (!target) {
    state.b2bMyLodgeCollectStatus = "수정할 관심숙소를 찾지 못했습니다. 화면을 새로고침한 뒤 다시 시도하세요.";
    renderReport();
    return;
  }
  state.b2bMyLodgeCollectStatus = `${target.lodgingName || "관심숙소"} 정보를 수정합니다. 저장하면 다시 카드로 등록됩니다.`;
  state.b2bMyLodgeExpanded = true;
  state.b2bMyLodgeEditing = true;
  persistB2BMyLodgeStore({
    ...store,
    draft: { ...target, id: "" },
    interestLodges: interestLodges.filter((_, index) => index !== targetIndex)
  });
  renderReport();
  document.querySelector(".b2b-my-lodge-board")?.scrollIntoView({ behavior: "smooth", block: "nearest" });
}

function deleteB2BInterestLodge(lodgeId = "", fallbackIndex = -1) {
  const store = readB2BMyLodgeStore();
  const interestLodges = Array.isArray(store.interestLodges) ? store.interestLodges : [];
  const targetIndex = b2bInterestLodgeTargetIndex(interestLodges, lodgeId, fallbackIndex);
  const next = targetIndex >= 0 ? interestLodges.filter((_, index) => index !== targetIndex) : interestLodges;
  state.b2bMyLodgeCollectStatus = targetIndex < 0 ? "삭제할 관심숙소를 찾지 못했습니다." : "관심숙소를 삭제했습니다.";
  state.b2bMyLodgeExpanded = false;
  state.b2bMyLodgeEditing = false;
  persistB2BMyLodgeStore({ ...store, interestLodges: next });
  renderReport();
  document.querySelector(".b2b-my-lodge-board")?.scrollIntoView({ behavior: "smooth", block: "nearest" });
}

function updateB2BMyLodgeRoomSegments(action = "add", index = -1) {
  const values = collectB2BMyLodgeFormValues() || readB2BMyLodgeDraft() || {};
  state.b2bMyLodgeExpanded = true;
  const displayedRows = collectB2BMyLodgeSegmentFormRows({ includeBlank: true });
  const rows = (displayedRows.length ? displayedRows : b2bMyLodgeSegmentInputRows(values)).slice(0, B2B_MY_LODGE_SEGMENT_LIMIT);
  if (!rows.length) rows.push(b2bMyLodgeBlankSegment());
  if (action === "add" && rows.length < B2B_MY_LODGE_SEGMENT_LIMIT) {
    rows.push(b2bMyLodgeBlankSegment());
  }
  if (action === "remove" && rows.length > 1 && index >= 0 && index < rows.length) {
    rows.splice(index, 1);
  }
  values.roomSegments = rows;
  persistB2BMyLodgeDraft(values);
  renderReport();
  document.querySelector("[data-b2b-room-segments]")?.scrollIntoView({ behavior: "smooth", block: "nearest" });
}

async function collectB2BMyLodgeByName() {
  if (state.b2bMyLodgeCollecting) return;
  const current = collectB2BMyLodgeFormValues() || {};
  const lodgingName = String(current.lodgingName || "").trim();
  if (!lodgingName) {
    state.b2bMyLodgeCollectStatus = "숙소명을 먼저 입력하세요.";
    state.b2bMyLodgeExpanded = true;
    renderReport();
    return;
  }
  const payload = {
    lodgingName,
    checkIn: state.data?.run?.checkIn || els.checkInInput?.value || "",
    checkOut: state.data?.run?.checkOut || els.checkOutInput?.value || "",
    detailRankRanges: "1-5",
    bookingRangeDays: DEFAULT_BOOKING_DAYS,
    bookingRangePlaceLimit: 3
  };
  state.b2bMyLodgeCollecting = true;
  state.b2bMyLodgeExpanded = true;
  state.b2bMyLodgeCollectStatus = `${lodgingName} 자동 수집을 시작합니다. 네이버 업체명 검색 기준입니다.`;
  state.b2bMyLodgeCollectResult = null;
  persistB2BMyLodgeDraft(current);
  renderReport();
  try {
    const result = await fetchJson("/api/b2b-my-lodge-collect", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify(payload)
    });
    const item = result.selectedItem || (Array.isArray(result.candidateItems) ? result.candidateItems[0] : null);
    if (!item) throw new Error("일치하는 네이버 업체를 찾지 못했습니다. 숙소명을 더 정확히 입력하세요.");
    const values = b2bMyLodgeDraftFromCollectedItem(item, result, current);
    state.b2bMyLodgeCollectResult = result;
    state.b2bMyLodgeCollectStatus = `${values.lodgingName || lodgingName} 자동 수집 완료 · ${values.collectionPrecisionLabel || "수집 근거 확인"}`;
    values.collectionStatus = state.b2bMyLodgeCollectStatus;
    persistB2BMyLodgeDraft(values);
  } catch (error) {
    state.b2bMyLodgeCollectStatus = `자동 수집 실패: ${error.message}`;
  } finally {
    state.b2bMyLodgeCollecting = false;
    renderReport();
    document.querySelector(".b2b-my-lodge-board")?.scrollIntoView({ behavior: "smooth", block: "nearest" });
  }
}

function clearB2BMyLodgeBenchmark() {
  const store = readB2BMyLodgeStore();
  state.b2bMyLodgeCollectStatus = "";
  state.b2bMyLodgeCollectResult = null;
  state.b2bMyLodgeExpanded = false;
  state.b2bMyLodgeEditing = false;
  persistB2BMyLodgeStore({ ...store, draft: {} }, { syncInterestLodges: false });
  renderReport();
  document.querySelector(".b2b-my-lodge-board")?.scrollIntoView({ behavior: "smooth", block: "nearest" });
}

function renderB2BRevenueBenchmark(brief = b2bMarketBriefModel(), model = b2bRevenueBenchmarkModel(brief)) {
  if (!model.rows.length) return "";
  return `
    <div class="b2b-revenue-board ${escapeHtml(model.decision.tone)}">
      <div class="b2b-revenue-head">
        <div>
          <span>매출 근거</span>
          <strong>예상 매출 표본 비교</strong>
          <p>${escapeHtml(`${model.decision.summary} ${model.revenueBasisText}입니다.`)}</p>
        </div>
        <em>${escapeHtml(model.decision.label)}</em>
      </div>
      <div class="b2b-revenue-grid">
        ${model.cards.map((card) => `
          <article class="${escapeHtml(card.tone)}">
            <span>${escapeHtml(card.label)}</span>
            <strong>${escapeHtml(card.value)}</strong>
            <small>${escapeHtml(card.note)}</small>
          </article>
        `).join("")}
      </div>
      <div class="b2b-revenue-layout">
        <article class="b2b-revenue-list">
          <div class="b2b-revenue-subhead">
            <strong>매출 벤치마크 업체</strong>
            <small>평균·최고·최저는 ${escapeHtml(model.revenueBasisText)}으로 표시합니다.</small>
          </div>
          ${model.benchmarkRows.map((row) => {
            const attrs = row.itemIndex >= 0 ? `type="button" data-open-company="${row.itemIndex}"` : `type="button" disabled`;
            const revenueText = row.revenue ? fmtWon(row.revenue) : "매출 표본 대기";
            const priceTextValue = row.avgPrice ? `평균가 ${fmtWon(row.avgPrice)}` : "가격 표본 대기";
            const rateText = Number.isFinite(row.flow.all.rate) ? fmtRate(row.flow.all.rate) : "판매율 대기";
            const offlineText = row.offlineQuantity
              ? `오프라인 ${fmtNumber(row.offlineQuantity)}개 추정`
              : row.blockedQuantity
                ? `차단/운영축소 ${fmtNumber(row.blockedQuantity)}개`
                : "";
            const metaText = [rateText, priceTextValue, offlineText].filter(Boolean).join(" · ");
            return `
              <button class="b2b-revenue-row ${escapeHtml(row.tone)}" ${attrs}>
                <span>${fmtNumber(row.rank)}위</span>
                <strong>${escapeHtml(row.name)}</strong>
                <em>${escapeHtml(revenueText)}</em>
                <small>${escapeHtml(metaText)}</small>
              </button>
            `;
          }).join("")}
        </article>
        <article class="b2b-revenue-guide">
          <div class="b2b-revenue-subhead">
            <strong>비교 기준</strong>
            <small>할인 옵션은 제외하고, 가격 보완과 오프라인 신호는 참고값으로 봅니다.</small>
          </div>
          ${model.guideRows.map((row) => `
            <div class="${escapeHtml(row.tone)}">
              <span>${escapeHtml(row.label)}</span>
              <strong>${escapeHtml(row.value)}</strong>
              <small>${escapeHtml(row.note)}</small>
            </div>
          `).join("")}
        </article>
      </div>
    </div>
  `;
}

function b2bStrategyBoardModel(brief = b2bMarketBriefModel(), revenueModel = b2bRevenueBenchmarkModel(brief)) {
  const rankModel = b2bRankBoardModel();
  const highReservationRate = finiteNumber(brief.highReservationRate, rankModel.highReservationRate || B2B_HIGH_RESERVATION_RATE);
  const highReservationLabel = brief.highReservationLabel || rankModel.highReservationLabel || b2bHighReservationLabel(brief.categoryProfile);
  const mapModel = b2bRegionMapModel();
  const trend = demandTrendSource();
  const trendStats = demandTrendStats(trend);
  const nextDemand = demandNextMonthProjection(demandTrafficAggregate(), trend, trendStats);
  const revenueCoverage = brief.itemCount ? revenueModel.revenueRows.length / brief.itemCount : NaN;
  const outsideCount = finiteNumber(mapModel.outsideCount, 0);
  const gapCount = finiteNumber(rankModel.gapRows.length, 0);
  const hotCount = finiteNumber(rankModel.hotRows.length, 0);
  const trendRising = Number.isFinite(trendStats.recentChange) && trendStats.recentChange >= 0.12;
  const trendFalling = Number.isFinite(trendStats.recentChange) && trendStats.recentChange <= -0.12;
  const peakNow = trend.hasSeries && Number.isFinite(trendStats.peakRatio) && trendStats.peakRatio >= 0.82;
  const revenueReady = revenueModel.revenueRows.length > 0;
  const priceCoverage = revenueModel.priceCoverage;
  const offlineQuantity = finiteNumber(revenueModel.offlineQuantityTotal, 0);
  const weekendRate = revenueModel.weekend?.rate;
  const weekdayRate = revenueModel.flow?.weekday?.rate;
  let decision = {
    tone: "neutral",
    label: "관찰 필요",
    summary: "최소 1주일, 주 1회 이상 반복 수집 후 경쟁권 방향 판단이 가능합니다."
  };
  if (revenueReady && (trendRising || peakNow) && hotCount >= 1) {
    decision = {
      tone: "hot",
      label: `${highReservationLabel} 경쟁권`,
      summary: `매출 표본과 수요 신호가 동시에 잡힙니다. ${highReservationLabel} 업체의 가격과 주말 재고를 먼저 비교합니다.`
    };
  } else if (hotCount >= 2 || (Number.isFinite(brief.rate) && brief.rate >= highReservationRate)) {
    decision = {
      tone: "strong",
      label: "경쟁 활발권",
      summary: "예약율이 높은 경쟁업체가 보여 가격대, 객실 구성, 주말 판매 흐름을 비교하기 좋은 권역입니다."
    };
  } else if (outsideCount > 0) {
    decision = {
      tone: "watch",
      label: "반경 경쟁권",
      summary: "검색 지역 밖 업체도 노출됩니다. 행정구역보다 네이버 반경 경쟁권 기준으로 비교합니다."
    };
  } else if (trendFalling || !revenueReady) {
    decision = {
      tone: "watch",
      label: "표본 보완권",
      summary: "매출 또는 수요 표본이 부족합니다. 현재 값은 방향성 판단용으로 보고 표본 보완을 병행합니다."
    };
  }
  const demandLabel = trend.reason
    ? "추세 대기"
    : trend.hasSeries
      ? demandTrendLabel()
      : "데이터랩 대기";
  const topRegion = mapModel.topRegion || brief.topRegion || {};
  const topRevenue = revenueModel.topRows?.[0] || null;
  const topRank = rankModel.rows?.[0] || null;
  const cards = [
    {
      tone: revenueReady ? "strong" : "watch",
      label: "매출 판단",
      value: revenueModel.averageRevenue ? fmtWon(revenueModel.averageRevenue) : "대기",
      note: revenueReady
        ? `표본 ${fmtNumber(revenueModel.revenueRows.length)}개 · ${fmtNumber(revenueModel.analysisDays || brief.analysisDays)}일 기준${offlineQuantity ? ` · 오프라인 ${fmtNumber(offlineQuantity)}개` : ""}`
        : "가격·수량 표본 필요"
    },
    {
      tone: hotCount ? "hot" : "neutral",
      label: "노출 판단",
      value: `${fmtNumber(rankModel.rows.length)}개`,
      note: `${highReservationLabel} ${fmtNumber(hotCount)}개 · 예약 표본 ${fmtNumber(rankModel.linkedRows.length)}곳`
    },
    {
      tone: nextDemand.tone || (trendRising || peakNow ? "hot" : trendFalling ? "watch" : "good"),
      label: nextDemand.label || "다음달 검색량",
      value: nextDemand.value,
      note: nextDemand.note
    },
    {
      tone: outsideCount ? "watch" : "good",
      label: "권역 판단",
      value: outsideCount ? `${fmtNumber(outsideCount)}곳` : "지역권",
      note: topRegion.region || topRegion.name || "지역 표본 기준"
    }
  ];
  const actionRows = [
    {
      tone: revenueReady ? "strong" : "watch",
      label: "가격 포지션",
      value: topRevenue?.revenue ? fmtWon(topRevenue.revenue) : "표본 대기",
      detail: topRevenue
        ? `${topRevenue.name} 기준으로 평균가, 요일 판매 흐름, 오프라인 신호를 함께 비교합니다.`
        : "매출 표본이 확보되면 상위 업체 가격대를 기준으로 비교합니다.",
      tab: "report",
      button: "매출 보기"
    },
    {
      tone: hotCount ? "hot" : "neutral",
      label: "노출 대응",
      value: topRank ? `${fmtNumber(topRank.rank)}위` : "대기",
      detail: hotCount
        ? `${highReservationLabel} 업체 ${fmtNumber(hotCount)}개를 가격·상품 벤치마크로 봅니다.`
        : "상위 노출 업체의 예약율과 매출 표본을 기준값으로 봅니다.",
      tab: "rank",
      button: "순위 보기"
    },
    {
      tone: Number.isFinite(weekendRate) && weekendRate >= 0.65 ? "hot" : "good",
      label: "요일 전략",
      value: Number.isFinite(weekendRate) ? fmtRate(weekendRate) : "대기",
      detail: Number.isFinite(weekendRate) && Number.isFinite(weekdayRate)
        ? `주말 ${fmtRate(weekendRate)} · 평일 ${fmtRate(weekdayRate)} 기준으로 요일별 가격 차이를 봅니다.`
        : "평일·금요일·토요일·일요일 판매 흐름 표본이 확보되면 요일별 전략을 분리합니다.",
      tab: "demand",
      button: "수요 보기"
    },
    {
      tone: outsideCount ? "watch" : "good",
      label: "권역 전략",
      value: outsideCount ? "반경권" : "지역권",
      detail: outsideCount
        ? "네이버 반경 노출로 들어오는 타지역 업체까지 경쟁군에 포함합니다."
        : "현재 표본은 검색 지역권 중심으로 비교합니다.",
      tab: "map",
      button: "지도 보기"
    }
  ];
  const checklist = [
    {
      tone: revenueReady ? "strong" : "watch",
      label: "매출 기준값",
      note: revenueReady
        ? `평균 ${fmtWon(revenueModel.averageRevenue)} · 상위 ${topRevenue?.revenue ? fmtWon(topRevenue.revenue) : "대기"}`
        : "가격과 수량 표본을 먼저 확보"
    },
    {
      tone: rankModel.rows.length ? "good" : "watch",
      label: "분석 범위",
      note: rankModel.rows.length
        ? `네이버 플레이스 ${fmtNumber(rankModel.rows.length)}개 · ${fmtNumber(brief.analysisDays || revenueModel.analysisDays)}일 · 매출 표본 ${Number.isFinite(revenueCoverage) ? fmtRate(revenueCoverage) : "대기"}`
        : "검색 범위 표본 대기"
    },
    {
      tone: nextDemand.tone || (trendRising || peakNow ? "hot" : "neutral"),
      label: `${nextDemand.targetMonthLabel || "다음달"} 수요`,
      note: nextDemand.detailText || nextDemand.note || (trend.reason || (trend.hasSeries ? `${demandLabel} · ${trendStats.peak?.label || "피크 대기"}` : "데이터랩 추세 대기"))
    }
  ];
  return {
    decision,
    cards,
    actionRows,
    checklist
  };
}

function b2bSimpleSummaryModel(
  brief = b2bMarketBriefModel(),
  strategyModel = b2bStrategyBoardModel(brief),
  revenueModel = b2bRevenueBenchmarkModel(brief),
  snapshotModel = b2bCompetitiveSnapshotModel(brief)
) {
  const decision = strategyModel.decision || brief.decision || {};
  const rankModel = snapshotModel.rankModel || b2bRankBoardModel();
  const highReservationRate = finiteNumber(brief.highReservationRate, rankModel.highReservationRate || B2B_HIGH_RESERVATION_RATE);
  const lowReservationRate = finiteNumber(brief.lowReservationRate, rankModel.lowReservationRate || B2B_LOW_RESERVATION_RATE);
  const trend = demandTrendSource();
  const trendStats = demandTrendStats(trend);
  const nextDemand = snapshotModel.nextDemand || demandNextMonthProjection(demandTrafficAggregate(), trend, trendStats);
  const revenueReady = revenueModel.revenueRows.length > 0;
  const priceCoverage = revenueModel.priceCoverage;
  const revenueSampleText = revenueReady
    ? `${fmtNumber(revenueModel.revenueRows.length)}개 매출 표본`
    : "매출 표본 대기";
  const hotCount = finiteNumber(rankModel.hotRows?.length, 0);
  const gapCount = finiteNumber(rankModel.gapRows?.length, 0);
  const competitionScore = Math.max(0, Math.min(100, Math.round(finiteNumber(brief.score, 0))));
  const actualReservationRate = Number.isFinite(brief.rate)
    ? brief.rate
    : (Number.isFinite(rankModel.rate) ? rankModel.rate : NaN);
  const analysisDays = finiteNumber(brief.analysisDays, b2bAnalysisDays(brief.run || {}));
  const reservationBasisText = brief.reservationBasisText || b2bReservationBasisText(brief.run || {});
  const offlineQuantity = finiteNumber(revenueModel.offlineQuantityTotal, 0);
  const reservationSampleNote = brief.salesSampleCount
    ? `예약율 산출 표본 (네이버 플레이스 기준) ${fmtNumber(brief.salesSampleCount)}곳 · ${fmtNumber(analysisDays)}일`
    : "예약율 산출 표본 (네이버 플레이스 기준) 대기";
  const revenueCardNote = [
    revenueSampleText,
    `${fmtNumber(analysisDays)}일 기준`,
    Number.isFinite(priceCoverage) ? `가격 확인 ${fmtRate(priceCoverage)}` : "",
    offlineQuantity ? `오프라인 ${fmtNumber(offlineQuantity)}개 추정` : ""
  ].filter(Boolean).join(" · ");
  const revenueMeter = revenueReady
    ? Math.max(18, Math.min(100, Math.round((revenueModel.revenueRows.length / Math.max(1, rankModel.rows.length || brief.itemCount)) * 100)))
    : 0;
  const searchMeter = Number.isFinite(nextDemand.change)
    ? Math.max(0, Math.min(100, Math.round(50 + nextDemand.change * 100)))
    : (nextDemand.projectedVolume ? 55 : 0);
  const summaryByTone = {
    hot: "수요와 매출 신호가 강합니다. 상위 경쟁업체의 가격대와 주말 판매 압력을 먼저 보세요.",
    strong: "경쟁이 활발한 권역입니다. 상위 경쟁업체의 예약율, 매출, 상품 구성을 함께 비교하세요.",
    watch: "권역 또는 표본 변수가 있습니다. 반경 경쟁권과 매출 표본을 보완해서 판단하세요.",
    neutral: "현재는 관찰 구간입니다. 경쟁업체 표본을 더 쌓아 방향성을 확인하세요."
  };
  const cards = [
    {
      tone: competitionScore >= 78 ? "hot" : competitionScore >= 64 ? "strong" : competitionScore >= 50 ? "watch" : "neutral",
      label: "경쟁강도",
      value: `${fmtNumber(competitionScore)}점`,
      note: `지정 검색범위 ${fmtNumber(rankModel.rows.length || brief.itemCount)}곳 비교`,
      barValue: competitionScore,
      meterLabel: "강도 점수"
    },
    {
      tone: Number.isFinite(actualReservationRate) && actualReservationRate >= highReservationRate
        ? "hot"
        : Number.isFinite(actualReservationRate) && actualReservationRate <= lowReservationRate
          ? "watch"
          : "strong",
      label: "실제 예약 지표",
      value: Number.isFinite(actualReservationRate) ? fmtRate(actualReservationRate) : "확인필요",
      note: reservationSampleNote,
      barValue: Number.isFinite(actualReservationRate) ? Math.round(actualReservationRate * 100) : 0,
      meterLabel: "예약 표본"
    },
    {
      tone: revenueReady ? "strong" : "watch",
      label: "예상 평균 매출",
      value: revenueModel.averageRevenue ? fmtWon(revenueModel.averageRevenue) : fmtWon(brief.averageRevenue),
      note: revenueCardNote,
      barValue: revenueMeter,
      meterLabel: revenueReady ? `표본 ${fmtNumber(revenueModel.revenueRows.length)}곳` : "대기"
    },
    {
      tone: nextDemand.tone || (trend.reason ? "watch" : trend.hasSeries ? "good" : "neutral"),
      label: nextDemand.label || "다음달 예상 검색량",
      value: nextDemand.value,
      note: nextDemand.note,
      barValue: searchMeter,
      meterLabel: "월별 예측"
    }
  ];
  const actions = [
    {
      tone: revenueReady ? "strong" : "watch",
      label: "매출 기준 확인",
      detail: revenueReady ? "평균 매출과 상위 업체 가격대를 비교" : "가격·수량 표본을 먼저 확인",
      tab: "report"
    },
    {
      tone: gapCount || hotCount ? "strong" : "neutral",
      label: "순위경쟁 확인",
      detail: "수집기간중 노출 순서, 예약율 확인",
      tab: "rank"
    },
    {
      tone: trend.hasSeries ? "good" : "watch",
      label: "예상 검색량 확인",
      detail: "수집기간중 월별검색량과 흐름을 확인",
      tab: "demand"
    }
  ];
  return {
    decision,
    headline: decision.label || brief.decision.label || "경쟁 리포트",
    summary: summaryByTone[decision.tone] || decision.summary || brief.decision.summary,
    cards,
    actions,
    dataNote: `${brief.categoryLabel || "숙박업"} · ${brief.longRange || brief.range} · ${reservationBasisText} · ${fmtNumber(brief.itemCount)}개 경쟁업체`
  };
}

