function adminDbProvinceQuickBoard(grouped = [], filters = {}) {
  const totalRows = grouped.reduce((sum, province) => sum + (province.rows || []).length, 0);
  const totalRegions = grouped.reduce((sum, province) => sum + (province.regions || []).length, 0);
  const cards = [
    {
      key: "all",
      label: "전체",
      rows: grouped.flatMap((province) => province.rows || []),
      regions: totalRegions
    },
    ...grouped.map((province) => ({
      key: province.key || "unknown",
      label: province.label || "미분류",
      rows: province.rows || [],
      regions: (province.regions || []).length
    }))
  ];
  return `
    <section class="admin-db-province-board" aria-label="광역/도 빠른 분류">
      <div class="admin-db-province-board-head">
        <div>
          <span>광역/도</span>
          <strong>지역 선택</strong>
          <small>광역 선택 후 시군구와 업체 목록을 확인합니다.</small>
        </div>
        <mark>${fmtNumber(grouped.length)}개 광역 · ${fmtNumber(totalRows)}개 업체</mark>
      </div>
      <div class="admin-db-province-card-grid">
        ${cards.map((card) => {
          const rows = card.rows || [];
          const revenueRows = rows.filter((row) => row.metrics?.revenue > 0);
          const averageRevenue = revenueRows.length
            ? revenueRows.reduce((sum, row) => sum + row.metrics.revenue, 0) / revenueRows.length
            : 0;
          const lowConfidence = rows.filter((row) => row.metrics?.lowConfidence || row.metrics?.confidenceScore <= 2).length;
          const decisionNeeded = rows.filter((row) => adminDbStatusMatches(row, "decision_queue")).length;
          const active = card.key === "all" ? filters.province === "all" : filters.province === card.key;
          return `
            <button type="button" class="${active ? "active" : ""}" data-admin-db-province-card="${escapeHtml(card.key)}">
              <span>${escapeHtml(card.label)}</span>
              <strong>${fmtNumber(rows.length)}곳</strong>
              <small>${fmtNumber(card.regions || 0)}개 지역 · 평균 ${fmtWon(averageRevenue)}</small>
              <em>낮은 신뢰 ${fmtNumber(lowConfidence)} · 판단 필요 ${fmtNumber(decisionNeeded)}</em>
            </button>
          `;
        }).join("")}
      </div>
    </section>
  `;
}

function adminDbRegionQuickBoard(grouped = [], filters = {}) {
  if (filters.province === "all") return "";
  const province = grouped.find((item) => item.key === filters.province) || grouped[0] || null;
  if (!province || !(province.regions || []).length) return "";
  const cards = [
    {
      key: "all",
      label: `${province.label || "선택 광역"} 전체`,
      rows: province.rows || [],
      regions: (province.regions || []).length
    },
    ...(province.regions || []).map((region) => ({
      key: region.key || "unknown",
      label: region.label || "지역 미확인",
      rows: region.rows || [],
      regions: 1
    }))
  ];
  return `
    <section class="admin-db-region-board" aria-label="시군구 빠른 분류">
      <div class="admin-db-region-board-head">
        <div>
          <span>시군구 2차 분류</span>
          <strong>${escapeHtml(province.label || "선택 광역")} 안에서 업체를 지역별로 좁힙니다</strong>
          <small>시군구 카드를 누르면 해당 지역 업체 리스트와 수정 버튼을 바로 확인합니다.</small>
        </div>
        <mark>${fmtNumber((province.regions || []).length)}개 지역 · ${fmtNumber((province.rows || []).length)}개 업체</mark>
      </div>
      <div class="admin-db-region-card-grid">
        ${cards.map((card) => {
          const rows = card.rows || [];
          const revenueRows = rows.filter((row) => row.metrics?.revenue > 0);
          const averageRevenue = revenueRows.length
            ? revenueRows.reduce((sum, row) => sum + row.metrics.revenue, 0) / revenueRows.length
            : 0;
          const lowConfidence = rows.filter((row) => row.metrics?.lowConfidence || row.metrics?.confidenceScore <= 2).length;
          const confirmNeeded = rows.filter((row) => row.metrics?.collection?.key === "confirm_needed").length;
          const active = card.key === "all" ? filters.region === "all" : filters.region === card.key;
          return `
            <button type="button" class="${active ? "active" : ""}" data-admin-db-region-card="${escapeHtml(card.key)}" data-admin-db-region-card-province="${escapeHtml(province.key || "all")}">
              <span>${escapeHtml(card.label)}</span>
              <strong>${fmtNumber(rows.length)}곳</strong>
              <small>${fmtNumber(card.regions || 0)}개 지역 · 평균 ${fmtWon(averageRevenue)}</small>
              <em>낮은 신뢰 ${fmtNumber(lowConfidence)} · 확인 수집 ${fmtNumber(confirmNeeded)}</em>
            </button>
          `;
        }).join("")}
      </div>
    </section>
  `;
}

function adminDbMissingRegion(row = {}) {
  const classification = row.metrics?.classification || {};
  return !classification.region
    || !row.provinceKey
    || !row.regionKey
    || row.provinceKey === "unknown"
    || row.regionKey.endsWith(":unknown");
}

function adminDbAuditStats(rows = []) {
  const total = rows.length;
  const lowConfidence = rows.filter((row) => row.metrics.lowConfidence || row.metrics.confidenceScore <= 2).length;
  const confirmNeeded = rows.filter((row) => row.metrics.collection?.key === "confirm_needed").length;
  const manualCount = rows.filter((row) => row.metrics.manualCorrection).length;
  const revenueRows = rows.filter((row) => row.metrics.revenue > 0).length;
  const otaLinked = rows.filter((row) => ADMIN_DB_MANAGED_CHANNELS.some(([key]) => row.metrics.channels?.[key])).length;
  const unreviewed = rows.filter((row) => !row.metrics.adminReview && !row.company?.adminReview).length;
  const missingRegion = rows.filter(adminDbMissingRegion).length;
  const missingRevenue = Math.max(0, total - revenueRows);
  const missingOta = Math.max(0, total - otaLinked);
  const ratio = (count) => total ? count / total : 0;
  const penalty = ratio(lowConfidence) * 32
    + ratio(confirmNeeded) * 26
    + ratio(unreviewed) * 18
    + ratio(missingRevenue) * 14
    + ratio(missingOta) * 6
    + ratio(missingRegion) * 4;
  const score = Math.max(0, Math.min(100, Math.round(100 - penalty)));
  const tone = score >= 85 ? "good" : score >= 70 ? "watch" : "hot";
  const nextAction = confirmNeeded
    ? "확인 수집"
    : lowConfidence
      ? "수량 보정"
      : unreviewed
        ? "관리자 검수"
        : missingRevenue
          ? "매출 표본 보강"
          : "유지 관리";
  return {
    total,
    lowConfidence,
    confirmNeeded,
    manualCount,
    revenueRows,
    otaLinked,
    unreviewed,
    missingRegion,
    missingRevenue,
    missingOta,
    score,
    tone,
    nextAction
  };
}

function adminDbAuditChecklist(stats = {}) {
  return [
    ["지역카드", stats.missingRegion ? `${fmtNumber(stats.missingRegion)}곳 확인` : "완료", !stats.missingRegion],
    ["수량 신뢰", stats.lowConfidence ? `${fmtNumber(stats.lowConfidence)}곳 보강` : "완료", !stats.lowConfidence],
    ["매출 표본", stats.missingRevenue ? `${fmtNumber(stats.missingRevenue)}곳 보강` : "완료", !stats.missingRevenue],
    ["채널", stats.missingOta ? `${fmtNumber(stats.missingOta)}곳 확인` : "완료", !stats.missingOta],
    ["관리자 검수", stats.unreviewed ? `${fmtNumber(stats.unreviewed)}곳 대기` : "완료", !stats.unreviewed]
  ];
}

function adminDbAuditRegions(rows = []) {
  const map = new Map();
  rows.forEach((row) => {
    const key = row.regionKey || "unknown";
    if (!map.has(key)) {
      map.set(key, {
        key,
        provinceKey: row.provinceKey || "unknown",
        provinceLabel: row.provinceLabel || "미분류",
        regionLabel: row.localityLabel || row.regionLabel || "지역 미확인",
        rows: []
      });
    }
    map.get(key).rows.push(row);
  });
  return Array.from(map.values()).map((region) => {
    const stats = adminDbAuditStats(region.rows);
    return { ...region, stats };
  }).sort((a, b) =>
    a.stats.score - b.stats.score
    || b.stats.confirmNeeded - a.stats.confirmNeeded
    || b.stats.lowConfidence - a.stats.lowConfidence
    || b.rows.length - a.rows.length
    || a.regionLabel.localeCompare(b.regionLabel, "ko-KR")
  );
}

function adminDbAuditCompanyTasks(row = {}) {
  const metrics = row.metrics || {};
  const tasks = [];
  if (metrics.collection?.key === "confirm_needed") tasks.push("확인 수집");
  if (metrics.lowConfidence || metrics.confidenceScore <= 2) tasks.push("수량 신뢰 보강");
  if (!metrics.revenue) tasks.push("매출 표본 보강");
  if (!metrics.channels?.count) tasks.push("OTA 채널 확인");
  if (!metrics.adminReview && !row.company?.adminReview) tasks.push("관리자 검수");
  if (metrics.stockVariance) tasks.push("총량 변동 확인");
  if (metrics.workType?.key === "manual" || metrics.adminReview?.status === "manual_needed") tasks.push("보정값 입력");
  return [...new Set(tasks.length ? tasks : ["유지 관리"])];
}

function adminDbAuditGateRows(stats = {}) {
  const total = stats.total || 0;
  return [
    {
      key: "region",
      label: "지역 매칭",
      value: stats.missingRegion ? `${fmtNumber(stats.missingRegion)}곳 확인` : "완료",
      done: !stats.missingRegion,
      action: "지역카드 확인"
    },
    {
      key: "confidence",
      label: "수량 신뢰",
      value: stats.lowConfidence ? `${fmtNumber(stats.lowConfidence)}곳 보강` : "완료",
      done: !stats.lowConfidence,
      action: "수량 보정"
    },
    {
      key: "revenue",
      label: "매출 표본",
      value: `${fmtNumber(stats.revenueRows || 0)}/${fmtNumber(total)}`,
      done: total ? stats.revenueRows >= total : true,
      action: "가격·판매 보강"
    },
    {
      key: "channel",
      label: "채널 확인",
      value: `${fmtNumber(stats.otaLinked || 0)}/${fmtNumber(total)}`,
      done: !stats.missingOta,
      action: "OTA 확인"
    },
    {
      key: "review",
      label: "관리자 검수",
      value: stats.unreviewed ? `${fmtNumber(stats.unreviewed)}곳 대기` : "완료",
      done: !stats.unreviewed,
      action: "판정 저장"
    },
    {
      key: "confirm",
      label: "확인 수집",
      value: stats.confirmNeeded ? `${fmtNumber(stats.confirmNeeded)}곳 필요` : "완료",
      done: !stats.confirmNeeded,
      action: "확인 수집"
    }
  ];
}

function adminDbAuditCompletionPanel(region = {}) {
  const stats = region.stats || adminDbAuditStats(region.rows || []);
  const gates = adminDbAuditGateRows(stats);
  const doneCount = gates.filter((gate) => gate.done).length;
  const ready = doneCount === gates.length;
  const ratio = gates.length ? Math.round((doneCount / gates.length) * 100) : 100;
  const nextGate = gates.find((gate) => !gate.done);
  return `
    <div class="admin-db-audit-gate ${ready ? "good" : "watch"}">
      <div class="admin-db-audit-gate-head">
        <div>
          <span>지역카드 공개 전 기준</span>
          <strong>${ready ? "감수 완료 가능" : `${fmtNumber(doneCount)}/${fmtNumber(gates.length)}개 기준 통과`}</strong>
          <small>${escapeHtml(ready ? "지역카드와 업체 DB를 운영 기준으로 사용할 수 있습니다." : `${nextGate?.label || "남은 기준"}부터 정리하면 됩니다.`)}</small>
        </div>
        <mark>${fmtNumber(ratio)}%</mark>
      </div>
      <div class="admin-db-audit-gatebar" aria-hidden="true"><i style="width:${Math.max(4, ratio)}%"></i></div>
      <div class="admin-db-audit-gates">
        ${gates.map((gate) => `
          <article class="${gate.done ? "good" : "watch"}">
            <span>${escapeHtml(gate.label)}</span>
            <strong>${escapeHtml(gate.value)}</strong>
            <small>${escapeHtml(gate.done ? "통과" : gate.action)}</small>
          </article>
        `).join("")}
      </div>
      <div class="admin-db-audit-gate-actions">
        <button type="button" data-admin-db-region-link data-admin-db-province-key="${escapeHtml(region.provinceKey || "")}" data-admin-db-region-key="${escapeHtml(region.key || "")}">지역 전체 보기</button>
        <button type="button" data-admin-db-region-confirm data-admin-db-province-key="${escapeHtml(region.provinceKey || "")}" data-admin-db-region-key="${escapeHtml(region.key || "")}">확인 수집 대상</button>
      </div>
    </div>
  `;
}

function adminDbAuditDetailPanel(region = null) {
  if (!region) return "";
  const rows = (region.rows || [])
    .filter((row) => {
      const metrics = row.metrics || {};
      return metrics.collection?.key === "confirm_needed"
        || metrics.lowConfidence
        || metrics.confidenceScore <= 2
        || !metrics.revenue
        || !metrics.channels?.count
        || !metrics.adminReview
        || metrics.stockVariance;
    })
    .sort((a, b) => adminDbWorkPriority(b) - adminDbWorkPriority(a) || (a.metrics.rank || 9999) - (b.metrics.rank || 9999));
  const stats = region.stats || adminDbAuditStats(region.rows || []);
  const queueRows = rows.slice(0, 8);
  return `
    <div class="admin-db-audit-detail" data-admin-db-audit-detail="${escapeHtml(region.key || "")}">
      <div class="admin-db-audit-detail-head">
        <div>
          <span>선택 지역 감수 큐</span>
          <strong>${escapeHtml(region.provinceLabel || "미분류")} · ${escapeHtml(region.regionLabel || "지역 미확인")}</strong>
          <small>점수가 낮은 원인을 업체 단위로 풀어서 확인합니다. 확인 수집과 상세 수정을 여기서 바로 시작합니다.</small>
        </div>
        <mark class="${escapeHtml(stats.tone || "watch")}">${fmtNumber(stats.score)}점 · ${escapeHtml(stats.nextAction || "확인")}</mark>
      </div>
      <div class="admin-db-audit-detail-grid">
        ${[
          ["확인 수집", `${fmtNumber(stats.confirmNeeded)}곳`, "신뢰도 보강 대상"],
          ["낮은 신뢰", `${fmtNumber(stats.lowConfidence)}곳`, "총량·상품 구조 확인"],
          ["매출 표본", `${fmtNumber(stats.revenueRows)}/${fmtNumber(stats.total)}`, "가격·판매 수량 연결"],
          ["관리자 검수", `${fmtNumber(stats.unreviewed)}곳`, "판정값 저장 대기"]
        ].map(([label, value, note]) => `
          <article>
            <span>${escapeHtml(label)}</span>
            <strong>${escapeHtml(value)}</strong>
            <small>${escapeHtml(note)}</small>
          </article>
        `).join("")}
      </div>
      ${adminDbAuditCompletionPanel(region)}
      <div class="admin-db-audit-queue">
        ${queueRows.length ? queueRows.map((row) => {
          const company = row.company || {};
          const metrics = row.metrics || {};
          const tasks = adminDbAuditCompanyTasks(row);
          return `
            <article class="${escapeHtml(metrics.collection?.tone || metrics.workType?.tone || "watch")}">
              <div>
                <span>${escapeHtml([metrics.rank ? `${fmtNumber(metrics.rank)}위` : "", metrics.category?.label, metrics.collection?.label].filter(Boolean).join(" · "))}</span>
                <strong>${escapeHtml(company.primaryName || "업체명 확인")}</strong>
                <small>${escapeHtml(adminDbWorkReason(row))}</small>
              </div>
              <div class="admin-db-audit-task-tags">
                ${tasks.map((task) => `<em>${escapeHtml(task)}</em>`).join("")}
              </div>
              <div class="admin-db-audit-company-actions">
                <button type="button" data-queue-recrawl-company="${escapeHtml(company.companyId || "")}" data-queue-recrawl-source="admin_region_audit_queue" data-queue-recrawl-autostart="1">확인 수집</button>
                <button type="button" data-admin-db-company-select="${escapeHtml(company.companyId || "")}">상세 수정</button>
              </div>
            </article>
          `;
        }).join("") : `<p class="admin-db-more">이 지역은 현재 우선 감수할 업체가 없습니다.</p>`}
      </div>
      ${rows.length > queueRows.length ? `<p class="admin-db-more">상위 ${fmtNumber(queueRows.length)}개만 먼저 표시합니다. 지역 보기로 전체 업체를 확인할 수 있습니다.</p>` : ""}
    </div>
  `;
}

function adminDbAuditBoard(rows = []) {
  const regions = adminDbAuditRegions(rows);
  const priority = regions.filter((region) => region.stats.score < 85 || region.stats.confirmNeeded || region.stats.lowConfidence || region.stats.unreviewed);
  const shown = (priority.length ? priority : regions).slice(0, 8);
  if (!shown.length) return "";
  const overall = adminDbAuditStats(rows);
  const selectedRegion = regions.find((region) => region.key === state.adminDbAuditRegionKey) || shown[0] || regions[0] || null;
  if (selectedRegion) state.adminDbAuditRegionKey = selectedRegion.key;
  return `
    <section class="admin-db-audit-panel">
      <div class="admin-db-audit-head">
        <div>
          <span>지역카드 사전 감수</span>
          <strong>지역별로 먼저 확인할 DB를 압축합니다</strong>
          <small>낮은 신뢰도, 확인 수집, 매출 표본, OTA 연결, 관리자 검수 상태를 지역 단위로 묶어 봅니다.</small>
        </div>
        <mark class="${escapeHtml(overall.tone)}">${fmtNumber(overall.score)}점 · ${escapeHtml(overall.nextAction)}</mark>
      </div>
      <div class="admin-db-audit-list">
        ${shown.map((region) => {
          const stats = region.stats;
          const active = selectedRegion && selectedRegion.key === region.key;
          return `
            <article class="${escapeHtml(stats.tone)} ${active ? "active" : ""}">
              <div class="admin-db-audit-title">
                <div>
                  <span>${escapeHtml(region.provinceLabel)}</span>
                  <strong>${escapeHtml(region.regionLabel)}</strong>
                  <small>${fmtNumber(stats.total)}개 업체 · ${escapeHtml(stats.nextAction)}</small>
                </div>
                <b>${fmtNumber(stats.score)}점</b>
              </div>
              <div class="admin-db-audit-scorebar" aria-hidden="true"><i style="width:${Math.max(4, stats.score)}%"></i></div>
              <div class="admin-db-audit-stats">
                ${[
                  ["확인 수집", `${fmtNumber(stats.confirmNeeded)}곳`],
                  ["낮은 신뢰", `${fmtNumber(stats.lowConfidence)}곳`],
                  ["매출 표본", `${fmtNumber(stats.revenueRows)}/${fmtNumber(stats.total)}`],
                  ["OTA", `${fmtNumber(stats.otaLinked)}/${fmtNumber(stats.total)}`]
                ].map(([label, value]) => `
                  <span><small>${escapeHtml(label)}</small><strong>${escapeHtml(value)}</strong></span>
                `).join("")}
              </div>
              <div class="admin-db-audit-checks">
                ${adminDbAuditChecklist(stats).map(([label, value, done]) => `
                  <em class="${done ? "good" : "watch"}">${escapeHtml(label)} · ${escapeHtml(value)}</em>
                `).join("")}
              </div>
              <div class="admin-db-audit-actions">
                <button type="button" data-admin-db-audit-select="${escapeHtml(region.key)}">감수 큐</button>
                <button type="button" data-admin-db-region-link data-admin-db-province-key="${escapeHtml(region.provinceKey)}" data-admin-db-region-key="${escapeHtml(region.key)}">지역 보기</button>
                <button type="button" data-admin-db-region-confirm data-admin-db-province-key="${escapeHtml(region.provinceKey)}" data-admin-db-region-key="${escapeHtml(region.key)}">확인 수집만</button>
              </div>
            </article>
          `;
        }).join("")}
      </div>
      ${adminDbAuditDetailPanel(selectedRegion)}
    </section>
  `;
}

function adminDbChannelChips(channels = {}) {
  const statuses = channels.statuses || {};
  const saved = ADMIN_DB_CHANNEL_OPTIONS
    .filter(([key]) => statuses[key])
    .map(([key, label]) => {
      const entry = statuses[key] || {};
      return `<em class="${escapeHtml(adminDbChannelStatusTone(entry.status))}">${escapeHtml(`${label} ${entry.statusLabel || adminDbChannelStatusLabel(entry.status)}`)}</em>`;
    });
  if (saved.length) return saved.join("");
  const chips = ADMIN_DB_CHANNEL_OPTIONS.filter(([key]) => channels[key]).map(([, label]) => `<em class="good">${escapeHtml(label)}</em>`);
  return chips.length ? chips.join("") : `<em class="watch">채널 확인</em>`;
}

function adminDbFeatureChips(features = {}) {
  const options = [
    ["pool", "수영장"],
    ["seminar", "세미나실"],
    ["pet", "애견동반"],
    ["bbq", "바베큐"]
  ];
  const chips = options.filter(([key]) => features[key]).map(([, label]) => `<em>${escapeHtml(label)}</em>`);
  return chips.length ? chips.join("") : `<em>시설 미분류</em>`;
}

function adminDbFeatureSummary(features = {}) {
  const labels = [
    features.pool ? "수영장" : "",
    features.seminar ? "세미나실" : "",
    features.pet ? "애견동반" : "",
    features.bbq ? "바베큐" : ""
  ].filter(Boolean);
  if (!labels.length) return "시설 미분류";
  return compactListText(labels, labels.join(" · "), 2);
}

function adminDbCollectionChip(collection = {}) {
  return `<em class="${escapeHtml(collection.tone || "neutral")}">${escapeHtml(collection.label || "자동수집")}</em>`;
}

function adminDbCompanyCompactTags(row = {}) {
  const metrics = row.metrics || {};
  const workType = metrics.workType || { label: "검수 대기", tone: "watch" };
  const tags = [
    { label: workType.label || "검수 대기", tone: workType.tone || "watch" },
    { label: metrics.collection?.label || "자동수집", tone: metrics.collection?.tone || "neutral" },
    { label: metrics.roomTotal ? `${fmtNumber(metrics.roomTotal)}실` : "", tone: "neutral" },
    { label: adminDbChannelSummary(metrics), tone: metrics.channels?.count ? "good" : "watch" }
  ];
  return tags
    .filter((tag) => tag.label)
    .slice(0, 4)
    .map((tag) => `<em class="${escapeHtml(tag.tone || "neutral")}">${escapeHtml(tag.label)}</em>`)
    .join("");
}

function adminDbWorkReason(row = {}) {
  const metrics = row.metrics || {};
  const workType = metrics.workType || {};
  const issues = metrics.issues || [];
  if (metrics.lowConfidence) return "수량 신뢰도가 낮아 객실 총량과 상품 구성을 먼저 확인해야 합니다.";
  if (workType.key === "manual") return "보정이 필요한 상태입니다. 객실수/상품별 수량을 확정하세요.";
  if (workType.key === "recrawl") return "총량 변동 또는 조건 변화가 있어 같은 기간으로 재수집이 필요합니다.";
  if (!metrics.revenue) return "매출 표본이 없어 가격 또는 판매수량 연결 상태를 확인해야 합니다.";
  if (!Number.isFinite(metrics.rate)) return "예약율 표본이 없어 네이버 예약 기준 판매율 확인이 필요합니다.";
  if (!metrics.adminReview) return "검수 전 업체입니다. 확인/완료/보정/보류 중 하나로 정리하세요.";
  return issues.slice(0, 2).join(" · ") || "추가 확인 후 상태를 확정하세요.";
}

function adminDbChannelSummary(metrics = {}) {
  const channels = metrics.channels || {};
  if (channels.manualNeeded) return `채널 확인필요 ${fmtNumber(channels.manualNeeded)}`;
  const labels = ADMIN_DB_MANAGED_CHANNELS.map(([key, label]) => channels[key] ? label : "").filter(Boolean);
  if (labels.length) return labels.join(" · ");
  return channels.naver ? "네이버만" : "채널 확인 필요";
}

function adminDbReservationStockText(metrics = {}) {
  const category = metrics.category || activeLodgingCategoryProfile();
  const unitLabel = b2bReservationUnitLabel(category);
  const lodging = metrics.lodging || {};
  const sold = optionalNumber(lodging.totalSold ?? lodging.weeklyTotalSoldOut ?? lodging.soldOutRooms);
  const supply = optionalNumber(lodging.totalSupply ?? lodging.weeklyTotalStock ?? lodging.totalRooms);
  if (Number.isFinite(sold) && Number.isFinite(supply) && supply > 0) {
    return `${fmtNumber(sold)}/${fmtNumber(supply)} ${unitLabel}`;
  }
  if (Number.isFinite(metrics.rate)) return `${fmtRate(metrics.rate)} · 수량 확인`;
  return "예약 표본 확인";
}

function adminDbProductSummary(company = {}, metrics = {}) {
  const latest = metrics.latest || company.inventory?.latest || {};
  const signal = metrics.signal || latest.salesSignal || {};
  const segments = Array.isArray(company.manualCorrection?.segments) ? company.manualCorrection.segments : [];
  const text = String(
    latest.productTypeSummary
    || latest.inventoryProductSummary
    || signal.productTypeSummary
    || segments.map((segment) => segment.name || segment.roomType).filter(Boolean).join(" · ")
    || ""
  ).trim();
  if (text) return compactListText(text.split(/\s*[·,|/]\s*/).filter(Boolean), text, 2);
  return metrics.category?.label ? `${metrics.category.label} 상품` : "상품 구성 확인";
}

function adminDbCouponSummary(company = {}, metrics = {}) {
  const coupon = naverCouponInfo({ companyProfile: company });
  const visible = Boolean(coupon.visible || metrics.couponVisible);
  return {
    visible,
    named: Boolean(coupon.named),
    value: coupon.named ? "쿠폰명 확인" : visible ? "쿠폰 노출" : "미확인",
    note: visible ? (coupon.names || coupon.detail || "네이버 쿠폰 노출 신호") : "네이버 화면 수동 확인",
    tone: coupon.named ? "good" : visible ? "watch" : "neutral"
  };
}

function adminDbB2BMetricCards(row = {}) {
  const company = row.company || {};
  const metrics = row.metrics || {};
  const coupon = adminDbCouponSummary(company, metrics);
  return [
    {
      label: "네이버 노출",
      value: metrics.rank ? `${fmtNumber(metrics.rank)}위` : "순위 대기",
      note: "지정 검색범위 기준",
      tone: metrics.rank ? "good" : "watch"
    },
    {
      label: "예약 판매율",
      value: Number.isFinite(metrics.rate) ? fmtRate(metrics.rate) : "확인 필요",
      note: adminDbReservationStockText(metrics),
      tone: Number.isFinite(metrics.rate) ? b2bRateTone(metrics.rate, "neutral", metrics.category) : "watch"
    },
    {
      label: "예상 7일 매출",
      value: metrics.revenue ? fmtWon(metrics.revenue) : "대기",
      note: metrics.revenue ? revenueAdjustmentNote(metrics.revenueImpact) : "가격·판매수량 표본 대기",
      tone: metrics.revenue ? "good" : "watch"
    },
    {
      label: "객실/상품",
      value: metrics.roomTotal ? `${fmtNumber(metrics.roomTotal)}실` : "수량 확인",
      note: adminDbProductSummary(company, metrics),
      tone: metrics.roomTotal ? "neutral" : "watch"
    },
    {
      label: "쿠폰",
      value: coupon.value,
      note: coupon.note,
      tone: coupon.tone
    },
    {
      label: "플랫폼",
      value: `${fmtNumber(metrics.channels?.count || 0)}개`,
      note: adminDbChannelSummary(metrics),
      tone: metrics.channels?.count ? "neutral" : "watch"
    }
  ];
}

function adminDbRequiredCheckChannels(row = {}) {
  const metrics = row.metrics || {};
  const channels = [];
  if (!Number.isFinite(metrics.rate) || !metrics.revenue || metrics.lowConfidence) channels.push("네이버 예약");
  if (!metrics.channels?.count || metrics.collection?.needsConfirm) channels.push("OTA");
  if (metrics.lowConfidence || metrics.stockVariance || metrics.signal?.lodgingStructuralBlockedTotal) channels.push("전화예약/오프라인");
  if (adminDbCouponSummary(row.company || {}, metrics).visible) channels.push("네이버 쿠폰");
  return Array.from(new Set(channels)).slice(0, 4);
}

function adminDbInternalJudgmentCards(row = {}) {
  const company = row.company || {};
  const metrics = row.metrics || {};
  const workType = metrics.workType || { label: "확인 필요", tone: "watch" };
  const collection = metrics.collection || {};
  const review = metrics.adminReview || company.adminReview || {};
  const channels = adminDbRequiredCheckChannels(row);
  const correction = manualCorrectionHasValue(company.manualCorrection);
  return [
    {
      label: "관리 상태",
      value: workType.label || "확인 필요",
      note: adminDbWorkReason(row),
      tone: workType.tone || "watch"
    },
    {
      label: "수량 신뢰도",
      value: metrics.confidenceGrade || "대기",
      note: correction ? "관리자 보정값 우선" : (metrics.lowConfidence ? "총량/상품 구조 확인" : "자동수집 기준"),
      tone: metrics.confidenceTone || (metrics.lowConfidence ? "hot" : "watch")
    },
    {
      label: "수집 구분",
      value: collection.label || "자동수집",
      note: collection.detail || collection.note || "저장값 기준",
      tone: collection.tone || "neutral"
    },
    {
      label: "필요 확인 채널",
      value: channels.length ? `${fmtNumber(channels.length)}개` : "추가 없음",
      note: channels.join(" · ") || "현재 표본 기준 유지",
      tone: channels.length ? "watch" : "good"
    },
    {
      label: "보정값",
      value: correction ? "적용" : "미적용",
      note: correction ? "보정값 우선" : "자동수집값 기준",
      tone: correction ? "good" : "neutral"
    },
    {
      label: "검수 기록",
      value: review.label || companyAdminReviewLabel(review.status),
      note: review.note || companyReviewContextText(review.context || {}) || "상태 저장 대기",
      tone: review.status ? "good" : "watch"
    }
  ];
}

function adminDbSelectedDecisionCards(row = {}, requiredChannels = []) {
  const company = row.company || {};
  const metrics = row.metrics || {};
  const workType = metrics.workType || { label: "확인 필요", tone: "watch" };
  const correction = manualCorrectionHasValue(company.manualCorrection);
  const review = metrics.adminReview || company.adminReview || {};
  const b2bBasis = [
    metrics.rank ? `노출 ${fmtNumber(metrics.rank)}위` : "노출 대기",
    Number.isFinite(metrics.rate) ? `예약율 ${fmtRate(metrics.rate)}` : "예약율 확인",
    metrics.revenue ? `매출 ${fmtWon(metrics.revenue)}` : "매출 대기"
  ].join(" · ");
  return [
    {
      label: "1. 현재 판단",
      value: workType.label || "확인 필요",
      note: adminDbWorkReason(row),
      tone: workType.tone || "watch"
    },
    {
      label: "2. B2B 기준",
      value: metrics.revenue || Number.isFinite(metrics.rate) ? "확인 가능" : "근거 보강",
      note: b2bBasis,
      tone: metrics.revenue && Number.isFinite(metrics.rate) ? "good" : "watch"
    },
    {
      label: "3. 기준값 수정",
      value: correction ? "적용됨" : (metrics.lowConfidence ? "필요" : "대기"),
      note: correction ? "보정값 우선" : (metrics.lowConfidence ? "객실 총량·상품 구조 확인" : "자동수집값 기준"),
      tone: correction ? "good" : (metrics.lowConfidence ? "hot" : "neutral")
    },
    {
      label: "4. 확인 수집",
      value: requiredChannels.length ? `${fmtNumber(requiredChannels.length)}개 채널` : "추가 없음",
      note: requiredChannels.join(" · ") || "현재 표본 유지",
      tone: requiredChannels.length ? "watch" : "good"
    },
    {
      label: "5. 판단 저장",
      value: review.label || companyAdminReviewLabel(review.status) || "미검수",
      note: review.note || companyReviewContextText(review.context || {}) || "확인/보정/보류 중 하나로 확정",
      tone: review.status ? "good" : "watch"
    }
  ];
}

function adminDbSelectedNextAction(row = {}, requiredChannels = []) {
  const company = row.company || {};
  const metrics = row.metrics || {};
  const workType = metrics.workType || { label: "확인 필요", tone: "watch" };
  const review = metrics.adminReview || company.adminReview || {};
  const workKey = workType.key || "";
  const needsCorrection = metrics.lowConfidence
    || workKey === "manual"
    || review.status === "manual_needed"
    || metrics.confidenceScore <= 2;
  const needsCollect = requiredChannels.length
    || metrics.collection?.needsConfirm
    || ["recrawl", "missingRevenue", "missingReservation"].includes(workKey)
    || metrics.stockVariance;
  if (needsCorrection) {
    return {
      label: "기준값 수정",
      title: "객실 총량·상품 구조를 먼저 보정",
      note: metrics.lowConfidence ? "자동 수집 신뢰도가 낮아 보정값을 우선 적용해야 합니다." : "관리자가 확인한 기준값을 저장하면 비교 지표가 다시 계산됩니다.",
      tone: "hot",
      foldKey: "correction"
    };
  }
  if (needsCollect) {
    return {
      label: "확인 수집",
      title: requiredChannels.length ? `${requiredChannels.join(" · ")} 확인` : "같은 조건으로 다시 수집",
      note: "수량·가격·예약율 표본을 같은 기간과 검색범위로 보강합니다.",
      tone: "watch",
      foldKey: "collect",
      runCollect: true
    };
  }
  if (!review.status) {
    return {
      label: "검수 저장",
      title: "확인/완료/보류 중 하나로 확정",
      note: "수집값이 충분하면 검수 상태를 저장해 업체 관리 목록을 정리합니다.",
      tone: workType.tone || "watch",
      foldKey: "review"
    };
  }
  return {
    label: "지표 확인",
    title: "사업자 화면 기준 최종 확인",
    note: "보정·검수값이 반영된 노출, 예약율, 매출 지표를 확인합니다.",
    tone: "good",
    foldKey: "b2b"
  };
}

function adminDbSelectedDecisionPanel(row = {}, issues = [], requiredChannels = []) {
  const company = row.company || {};
  const metrics = row.metrics || {};
  const workType = metrics.workType || { label: "확인 필요", tone: "watch" };
  const currentReason = adminDbWorkReason(row);
  const nextAction = adminDbSelectedNextAction(row, requiredChannels);
  const selectedId = company.companyId || "";
  const issueItems = (issues.length ? issues : [adminDbWorkReason(row)]).filter(Boolean).slice(0, 3);
  const decisionCards = adminDbSelectedDecisionCards(row, requiredChannels);
  return `
    <section class="admin-db-selected-decision ${escapeHtml(workType.tone || "watch")}" aria-label="상세 작업 요약">
      <div class="admin-db-selected-decision-head">
        <div>
          <span>현재 판단</span>
          <strong>${escapeHtml(workType.label || "확인 필요")}</strong>
          <small>${escapeHtml(currentReason)}</small>
        </div>
        <mark>${escapeHtml(nextAction.label)}</mark>
      </div>
      <div class="admin-db-selected-next-grid">
        <article class="${escapeHtml(workType.tone || "watch")}">
          <span>현재 상태</span>
          <strong>${escapeHtml(workType.label || "확인 필요")}</strong>
          <small>${escapeHtml(currentReason)}</small>
        </article>
        <article class="${escapeHtml(nextAction.tone || "watch")}">
          <span>다음 행동</span>
          <strong>${escapeHtml(nextAction.title)}</strong>
          <small>${escapeHtml(nextAction.note)}</small>
        </article>
      </div>
      <div class="admin-db-selected-next-actions">
        ${nextAction.runCollect && selectedId ? `<button type="button" data-queue-recrawl-company="${escapeHtml(selectedId)}" data-queue-recrawl-source="admin_db_decision" data-queue-recrawl-autostart="1">확인 수집 실행</button>` : ""}
        <button type="button" data-admin-db-open-fold="${escapeHtml(nextAction.foldKey || "review")}">${escapeHtml(nextAction.label)} 열기</button>
        <button type="button" data-admin-db-open-fold="b2b">비교 지표</button>
      </div>
      <details class="admin-db-selected-stage-fold">
        <summary>
          <span>처리 흐름 보기</span>
          <small>지표 확인, 보정, 수집, 검수 저장 순서</small>
        </summary>
        <div class="admin-db-selected-task-rail">
          ${decisionCards.map(adminDbSelectedMetricCard).join("")}
        </div>
      </details>
      ${issueItems.length ? `
        <div class="admin-db-selected-issues compact">
          ${issueItems.map((issue) => `<em class="${escapeHtml(workType.tone || "watch")}">${escapeHtml(issue)}</em>`).join("")}
        </div>
      ` : ""}
    </section>
  `;
}

function adminDbSelectedFoldBlock({ label = "", title = "", note = "", body = "", open = false, tone = "", foldKey = "" } = {}) {
  if (!body) return "";
  return `
    <details class="admin-db-selected-fold ${escapeHtml(tone || "")}" ${foldKey ? `data-admin-db-fold="${escapeHtml(foldKey)}"` : ""} ${open ? "open" : ""}>
      <summary>
        <div>
          <span>${escapeHtml(label)}</span>
          <strong>${escapeHtml(title)}</strong>
        </div>
        <small>${escapeHtml(note)}</small>
      </summary>
      <div class="admin-db-selected-fold-body">
        ${body}
      </div>
    </details>
  `;
}

function adminDbSelectedMetricCard(card = {}) {
  return `
    <article class="${escapeHtml(card.tone || "neutral")}">
      <span>${escapeHtml(card.label || "")}</span>
      <strong>${escapeHtml(card.value || "")}</strong>
      <small>${escapeHtml(card.note || "")}</small>
    </article>
  `;
}

function adminDbSelectedSectionHead(label = "", title = "", note = "") {
  return `
    <div class="admin-db-selected-section-head">
      <div>
        <span>${escapeHtml(label)}</span>
        <strong>${escapeHtml(title)}</strong>
        <small>${escapeHtml(note)}</small>
      </div>
    </div>
  `;
}

function adminDbSelectedAppliedCards(row = {}) {
  const company = row.company || {};
  const metrics = row.metrics || {};
  const review = metrics.adminReview || company.adminReview || {};
  const correction = manualCorrectionHasValue(company.manualCorrection);
  const correctionSegments = manualCorrectionRoomSegments(company.manualCorrection);
  const correctionRooms = correctionSegments.reduce((sum, segment) => sum + Math.round(Math.max(0, optionalNumber(segment.count) || 0)), 0);
  const basisRoomTotal = correctionRooms || finiteNumber(company.manualCorrection?.lodgingBasisTotal, 0) || finiteNumber(metrics.roomTotal, 0);
  const productNote = correctionSegments.length
    ? compactListText(correctionSegments.map((segment) => segment.type || "객실종류").filter(Boolean), "", 2)
    : adminDbProductSummary(company, metrics);
  return [
    {
      label: "최종 기준",
      value: correction ? "관리자 보정" : (metrics.sourceLabel || "자동수집"),
      note: correction ? "보정값 우선 적용" : "자동수집값 기준",
      tone: correction ? "good" : "neutral"
    },
    {
      label: "노출",
      value: metrics.rank ? `${fmtNumber(metrics.rank)}위` : "순위 대기",
      note: "네이버 플레이스 기준",
      tone: metrics.rank ? "good" : "watch"
    },
    {
      label: "예약율",
      value: Number.isFinite(metrics.rate) ? fmtRate(metrics.rate) : "확인 필요",
      note: adminDbReservationStockText(metrics),
      tone: Number.isFinite(metrics.rate) ? b2bRateTone(metrics.rate, "neutral", metrics.category) : "watch"
    },
    {
      label: "7일 매출",
      value: metrics.revenue ? fmtWon(metrics.revenue) : "대기",
      note: metrics.revenue ? revenueAdjustmentNote(metrics.revenueImpact) : "가격·판매수량 표본 필요",
      tone: metrics.revenue ? "good" : "watch"
    },
    {
      label: "객실·상품",
      value: basisRoomTotal ? `${fmtNumber(basisRoomTotal)}실` : "수량 확인",
      note: productNote,
      tone: basisRoomTotal ? "neutral" : "watch"
    },
    {
      label: "검수",
      value: review.label || companyAdminReviewLabel(review.status) || "미검수",
      note: review.note || companyReviewContextText(review.context || {}) || "상태 저장 대기",
      tone: review.status ? "good" : "watch"
    }
  ];
}

function adminDbSelectedAppliedValuesHtml(row = {}) {
  return `
    <section class="admin-db-applied-values" aria-label="최종 적용값">
      <div class="admin-db-applied-head">
        <span>최종 적용값</span>
        <strong>현재 B2B 반영 기준</strong>
      </div>
      <div class="admin-db-applied-grid">
        ${adminDbSelectedAppliedCards(row).map(adminDbSelectedMetricCard).join("")}
      </div>
    </section>
  `;
}

function adminDbWorkPriority(row = {}) {
  const metrics = row.metrics || {};
  const workType = metrics.workType || {};
  const order = {
    manual: 100,
    unreviewed: 88,
    recrawl: 82,
    missingRevenue: 76,
    missingReservation: 70,
    reviewed: 24,
    publicReady: 10
  };
  return (order[workType.key] || 40)
    + (metrics.lowConfidence ? 24 : 0)
    + (metrics.stockVariance ? 18 : 0)
    + (!metrics.revenue ? 12 : 0)
    + (!metrics.adminReview ? 8 : 0);
}

function adminDbWorkRows(rows = []) {
  return rows
    .filter((row) => {
      const metrics = row.metrics || {};
      const key = metrics.workType?.key || "";
      return metrics.lowConfidence
        || !metrics.adminReview
        || ["manual", "recrawl", "missingRevenue", "missingReservation"].includes(key);
    })
    .sort((a, b) => adminDbWorkPriority(b) - adminDbWorkPriority(a) || (a.metrics.rank || 9999) - (b.metrics.rank || 9999));
}

function adminDbWorkPanel(rows = []) {
  const workRows = adminDbWorkRows(rows);
  const lowConfidence = rows.filter((row) => row.metrics.lowConfidence || row.metrics.confidenceScore <= 2).length;
  const unreviewed = rows.filter((row) => !row.metrics.adminReview).length;
  const recrawl = rows.filter((row) => row.metrics.workType?.key === "recrawl" || row.metrics.stockVariance).length;
  const manual = rows.filter((row) => row.metrics.workType?.key === "manual" || row.metrics.adminReview?.status === "manual_needed").length;
  const ready = rows.filter((row) => ["publicReady", "reviewed"].includes(row.metrics.workType?.key || "")).length;
  return `
    <section class="admin-db-work-panel">
      <div class="admin-db-work-head">
        <div>
          <span>관리자 처리 보드</span>
          <strong>신뢰도 낮은 업체부터 상태를 정리합니다.</strong>
          <small>업체 관리에서 바로 검수 상태를 저장하고, 필요한 업체는 확인 수집 또는 보정 화면으로 이동합니다.</small>
        </div>
        <mark>${fmtNumber(workRows.length)}곳 처리 대상</mark>
      </div>
      <div class="admin-db-work-summary">
        ${[
          ["낮은 신뢰", lowConfidence, "총량/상품 확인", "hot"],
          ["미검수", unreviewed, "상태 결정 전", "watch"],
          ["재수집", recrawl, "조건 재확인", "watch"],
          ["보정 필요", manual, "관리자 보정", "hot"],
          ["정리됨", ready, "완료/컨택/보류", "good"]
        ].map(([label, count, note, tone]) => `
          <article class="${escapeHtml(tone)}">
            <span>${escapeHtml(label)}</span>
            <strong>${fmtNumber(count)}</strong>
            <small>${escapeHtml(note)}</small>
          </article>
        `).join("")}
      </div>
      <div class="admin-db-work-list">
        ${workRows.length ? workRows.slice(0, 6).map((row) => {
          const company = row.company || {};
          const metrics = row.metrics || {};
          const workType = metrics.workType || { label: "확인 필요", tone: "watch" };
          return `
            <article class="${escapeHtml(workType.tone || "watch")}">
              <div class="admin-db-work-title">
                <div>
                  <b>${escapeHtml(company.primaryName || "업체명 확인")}</b>
                  <small>${escapeHtml([row.provinceLabel, row.localityLabel, metrics.rank ? `${fmtNumber(metrics.rank)}위` : "", metrics.category?.label].filter(Boolean).join(" · "))}</small>
                </div>
                <span>${escapeHtml(workType.label || "확인 필요")}</span>
              </div>
              <p>${escapeHtml(adminDbWorkReason(row))}</p>
              <div class="admin-db-work-actions">
                <button type="button" data-queue-recrawl-company="${escapeHtml(company.companyId || "")}" data-queue-recrawl-source="admin_db" data-queue-recrawl-autostart="1">확인 수집</button>
                <button type="button" data-admin-db-company-select="${escapeHtml(company.companyId || "")}">상세 수정</button>
              </div>
              ${companyReviewActionsHtml(company, true, "admin_db")}
            </article>
          `;
        }).join("") : `<p class="admin-db-more">현재 필터 조건에서는 우선 처리할 업체가 없습니다.</p>`}
      </div>
    </section>
  `;
}

function adminDbConfirmCollectRows(rows = []) {
  return rows
    .filter((row) => row.metrics?.collection?.key === "confirm_needed")
    .sort((a, b) => adminDbWorkPriority(b) - adminDbWorkPriority(a) || (a.metrics.rank || 9999) - (b.metrics.rank || 9999));
}

function adminDbConfirmCollectFocus(row = {}) {
  const metrics = row.metrics || {};
  const company = row.company || {};
  const workKey = metrics.workType?.key || "";
  const decision = companyDecisionQueueProfile(company);
  const criteria = new Set((decision.criteria || []).map((criterion) => criterion.key));
  const focus = [];
  if (metrics.lowConfidence || metrics.confidenceScore <= 2 || criteria.has("quantity") || criteria.has("capacity")) focus.push("객실 총량·상품 수량");
  if (metrics.stockVariance) focus.push("날짜별 총량 변동");
  if (!metrics.revenue || workKey === "missingRevenue" || criteria.has("revenue")) focus.push("요일별 가격·매출 표본");
  if (!Number.isFinite(metrics.rate) || workKey === "missingReservation") focus.push("네이버 예약율 표본");
  if (!metrics.channels?.count || criteria.has("ota")) focus.push("OTA·채널 노출");
  if (metrics.adminReview?.status === "manual_needed") focus.push("관리자 보정값 확인");
  return [...new Set(focus.length ? focus : ["기본 표본 재확인"])];
}

function adminDbConfirmCollectionPlan(row = {}) {
  const company = row.company || {};
  const metrics = row.metrics || {};
  const decision = companyDecisionQueueProfile(company);
  const profile = companyNeedsCorrection(company);
  const plan = companyQueueRecrawlPlan(company, profile, decision);
  const eta = crawlEtaForPlan(plan);
  const dateText = plan.dateText || [plan.checkIn, plan.checkOut].filter(Boolean).join("~") || dateRangeLabel(state.data?.run || {});
  const focus = adminDbConfirmCollectFocus(row);
  return {
    decision,
    profile,
    plan,
    eta,
    dateText,
    focus,
    tone: metrics.collection?.tone || metrics.workType?.tone || "watch"
  };
}

function adminDbConfirmPlanLine(row = {}) {
  const { plan, eta, dateText } = adminDbConfirmCollectionPlan(row);
  return `기준 ${plan.keyword || activeKeyword()} · 상세 ${plan.range || "1-20"}위 · ${dateText || "최근 수집 기간"} · 예상 ${crawlEtaShortText(eta)}`;
}

function adminDbConfirmCollectPlanHtml(row = {}) {
  const company = row.company || {};
  const metrics = row.metrics || {};
  const workKey = metrics.workType?.key || "";
  const shouldShow = metrics.collection?.needsConfirm || ["manual", "recrawl", "missingRevenue", "missingReservation"].includes(workKey);
  if (!shouldShow || !company.companyId) return "";
  const { plan, eta, dateText, focus, tone } = adminDbConfirmCollectionPlan(row);
  const cards = [
    ["기준 키워드", plan.keyword || activeKeyword(), plan.keywordSource || "업체 기준"],
    ["검색 범위", `${plan.range || "1-20"}위`, plan.regionScope ? `지역 ${plan.regionScope}` : "검색어 기준"],
    ["수집 기간", dateText || "최근 수집 기간", `${plan.checkIn || "체크인"}~${plan.checkOut || "체크아웃"}`],
    ["예상 시간", crawlEtaShortText(eta), crawlEtaSourceText(eta)]
  ];
  return `
    <div class="admin-db-confirm-plan ${escapeHtml(tone)}">
      <div class="admin-db-confirm-head">
        <div>
          <span>관리자 확인 수집</span>
          <strong>수집 조건을 먼저 고정합니다</strong>
          <small>신뢰도가 낮은 업체는 같은 기간·지정 범위로 다시 수집한 뒤 수량·가격·예약율 근거를 보강합니다.</small>
        </div>
        <button type="button" data-queue-recrawl-company="${escapeHtml(company.companyId || "")}" data-queue-recrawl-source="admin_confirm_collect">수집 설정 적용</button>
      </div>
      <div class="admin-db-confirm-grid">
        ${cards.map(([label, value, note]) => `
          <article>
            <span>${escapeHtml(label)}</span>
            <strong>${escapeHtml(value || "확인 필요")}</strong>
            <small>${escapeHtml(note || "관리자 확인")}</small>
          </article>
        `).join("")}
      </div>
      <div class="admin-db-confirm-focus">
        <span>확인 포인트</span>
        <div>${focus.map((item) => `<em>${escapeHtml(item)}</em>`).join("")}</div>
      </div>
      ${recrawlRangePresetHtml({ companyId: company.companyId || "", selectedRange: plan.range || "1-20", source: "admin_confirm_collect" })}
    </div>
  `;
}

function adminDbRecheckToneLabel(tone = "same") {
  return {
    good: "개선",
    bad: "악화",
    same: "유지",
    watch: "대기"
  }[tone] || "유지";
}

function adminDbRecheckComparisonRows(comparison = {}) {
  if (!comparison.hasComparison) return [];
  const before = comparison.before || {};
  const current = comparison.current || {};
  const beforeRevenue = effectiveRevenueValue(before);
  const currentRevenue = effectiveRevenueValue(current);
  return [
    {
      label: "수량 신뢰도",
      before: before.grade ? `${before.grade} · ${before.structureLabel || "구조 확인"}` : "이전 없음",
      current: current.grade ? `${current.grade} · ${current.structureLabel || "구조 확인"}` : "최신 없음",
      tone: queueDeltaTone(before.gradeScore, current.gradeScore, true),
      note: current.quantityWeak ? "구조 확인 필요" : "수량 안정"
    },
    {
      label: "예약율",
      before: Number.isFinite(before.averageRate) ? fmtRate(before.averageRate) : "확인 필요",
      current: Number.isFinite(current.averageRate) ? fmtRate(current.averageRate) : "확인 필요",
      tone: queueDeltaTone(before.averageRate, current.averageRate, true),
      note: `${fmtNumber(current.totalSold)}건 판매 · ${fmtNumber(current.totalSupply)}건 기준`
    },
    {
      label: "가격 표본",
      before: `${fmtNumber(before.totalPricedSoldOut)}건 · 누락 ${fmtNumber(before.totalMissingPriceSoldOut)}`,
      current: `${fmtNumber(current.totalPricedSoldOut)}건 · 누락 ${fmtNumber(current.totalMissingPriceSoldOut)}`,
      tone: before.totalMissingPriceSoldOut !== current.totalMissingPriceSoldOut
        ? queueDeltaTone(before.totalMissingPriceSoldOut, current.totalMissingPriceSoldOut, false)
        : queueDeltaTone(before.totalPricedSoldOut, current.totalPricedSoldOut, true),
      note: current.totalMissingPriceSoldOut ? "가격 누락 남음" : "가격 누락 없음"
    },
    {
      label: "판매 공백",
      before: `${fmtNumber(before.gapCount)}유형`,
      current: `${fmtNumber(current.gapCount)}유형`,
      tone: queueDeltaTone(before.gapCount, current.gapCount, false),
      note: current.gapCount ? "요일별 공백 확인" : "공백 완화"
    },
    {
      label: "총량 변동",
      before: before.stockVariance ? "있음" : "없음",
      current: current.stockVariance ? "있음" : "없음",
      tone: queueBooleanResolvedTone(before.stockVariance, current.stockVariance),
      note: current.stockVariance ? "날짜별 총량 변동" : "총량 안정"
    },
    {
      label: "오프라인 추정",
      before: before.offlineEstimated ? `${fmtNumber(before.offlineQuantity)}건` : "신호 없음",
      current: current.offlineEstimated ? `${fmtNumber(current.offlineQuantity)}건` : "신호 없음",
      tone: queueBooleanResolvedTone(before.offlineEstimated, current.offlineEstimated),
      note: current.offlineDetail || (current.offlineEstimated ? "미오픈/차단·총량차 반영" : "추정 신호 없음")
    },
    {
      label: "예상 매출",
      before: fmtWon(beforeRevenue),
      current: fmtWon(currentRevenue),
      tone: queueDeltaTone(beforeRevenue, currentRevenue, true),
      note: `변화 ${formatSignedWon(currentRevenue - beforeRevenue)}`
    }
  ];
}

function adminDbRecheckOutcomeHtml(row = {}) {
  const company = row.company || {};
  if (!company.companyId) return "";
  const profile = companyNeedsCorrection(company);
  const decision = companyDecisionQueueProfile(company);
  const comparison = companyRecrawlComparison(company);
  const recommendation = companyRecrawlAutoRecommendation(company, profile, decision, comparison);
  const latestDate = comparison.latest?.collectedAt ? compactDateTime(comparison.latest.collectedAt) : "최신 수집 대기";
  const previousDate = comparison.previous?.collectedAt ? compactDateTime(comparison.previous.collectedAt) : "이전 수집 대기";
  const statusLabel = companyAdminReviewLabel(recommendation.status) || recommendation.label || "판정 대기";
  const firstReason = (recommendation.reasons || []).filter(Boolean)[0] || "확인 수집 결과를 보고 관리자 처리 상태를 결정합니다.";
  const applyButton = recommendation.status
    ? `<button type="button" data-company-review-action="${escapeHtml(recommendation.status)}" data-company-id="${escapeHtml(company.companyId || "")}" data-company-review-source="admin_recheck_outcome">추천 적용</button>`
    : "";
  if (!comparison.hasComparison) {
    return `
      <div class="admin-db-recheck-panel watch">
        <div class="admin-db-recheck-head">
          <div>
            <span>확인 수집 결과 판정</span>
            <strong>전후 비교 대기</strong>
            <small>${escapeHtml(`${previousDate} → ${latestDate}`)}</small>
          </div>
          <mark>비교 대기</mark>
        </div>
        <div class="admin-db-recheck-summary">
          ${[
            ["비교 상태", "대기", "이전/최신 수집값 필요"],
            ["추천 처리", statusLabel, recommendation.label || "수집 후 자동 판정"],
            ["다음 행동", "확인 수집", firstReason]
          ].map(([label, value, note]) => `
            <article>
              <span>${escapeHtml(label)}</span>
              <strong>${escapeHtml(value)}</strong>
              <small>${escapeHtml(note)}</small>
            </article>
          `).join("")}
        </div>
        <p>확인 수집을 실행하면 이전/최신 수량·가격·예약율 근거를 비교합니다.</p>
        <div class="admin-db-recheck-actions">
          <button type="button" data-queue-recrawl-company="${escapeHtml(company.companyId || "")}" data-queue-recrawl-source="admin_recheck_outcome">확인 수집 설정</button>
          ${applyButton}
        </div>
      </div>
    `;
  }
  const rows = adminDbRecheckComparisonRows(comparison);
  return `
    <div class="admin-db-recheck-panel ${escapeHtml(comparison.tone || "same")}">
      <div class="admin-db-recheck-head">
        <div>
          <span>확인 수집 결과 판정</span>
          <strong>${escapeHtml(`개선 ${fmtNumber(comparison.improved || 0)} · 악화 ${fmtNumber(comparison.worsened || 0)}`)}</strong>
          <small>${escapeHtml(`${previousDate} → ${latestDate}`)}</small>
        </div>
        <mark>${escapeHtml(recommendation.label || adminDbRecheckToneLabel(comparison.tone))}</mark>
      </div>
      <div class="admin-db-recheck-summary">
        ${[
          ["이전 수집", previousDate, "비교 기준"],
          ["최신 수집", latestDate, "확인 수집 결과"],
          ["자동 판정", statusLabel, firstReason],
          ["다음 처리", recommendation.label || adminDbRecheckToneLabel(comparison.tone), "추천 적용 후 검수 이력에 기록"]
        ].map(([label, value, note]) => `
          <article>
            <span>${escapeHtml(label)}</span>
            <strong>${escapeHtml(value)}</strong>
            <small>${escapeHtml(note)}</small>
          </article>
        `).join("")}
      </div>
      <div class="admin-db-recheck-grid">
        ${rows.map((item) => `
          <article class="${escapeHtml(item.tone || "same")}">
            <span>${escapeHtml(item.label)}</span>
            <strong>${escapeHtml(`${item.before} → ${item.current}`)}</strong>
            <small>${escapeHtml(item.note || adminDbRecheckToneLabel(item.tone))}</small>
          </article>
        `).join("")}
      </div>
      <div class="admin-db-recheck-actions">
        ${applyButton}
        <button type="button" data-queue-recrawl-company="${escapeHtml(company.companyId || "")}" data-queue-recrawl-source="admin_recheck_outcome">확인 수집 재설정</button>
      </div>
    </div>
  `;
}

function adminDbChannelStatusOptions(selected = "") {
  return [
    ["unknown", "미확인"],
    ["exposed", "노출"],
    ["not_found", "미노출"],
    ["needs_manual", "확인필요"],
    ["blocked", "수집불가"]
  ].map(([value, label]) => `<option value="${value}" ${selected === value ? "selected" : ""}>${label}</option>`).join("");
}

function adminDbChannelExposureForm(row = {}, channelKey = "", label = "") {
  const company = row.company || {};
  const entry = adminDbChannelExposureMap(company)[channelKey] || {};
  const status = entry.status || "unknown";
  const searchUrl = entry.url || adminDbChannelFallbackSearchUrl(channelKey, company);
  const checked = entry.checkedAt ? compactDateTime(entry.checkedAt) : "확인 전";
  const confidence = Number.isFinite(Number(entry.confidence)) ? ` · 신뢰 ${fmtNumber(entry.confidence)}%` : "";
  return `
    <div class="admin-db-channel-row ${escapeHtml(adminDbChannelStatusTone(status))}" data-surface="light" data-company-channel-form data-company-id="${escapeHtml(company.companyId || "")}" data-channel-key="${escapeHtml(channelKey)}">
      <div class="admin-db-channel-row-head">
        <div>
          <strong>${escapeHtml(label)}</strong>
          <small>${escapeHtml(`${adminDbChannelStatusLabel(status)} · ${checked}${confidence}`)}</small>
        </div>
        <span>${escapeHtml(entry.source === "automatic" ? "자동" : entry.source === "manual" ? "수동" : "대기")}</span>
      </div>
      <div class="admin-db-channel-fields">
        <label>
          <span>상태</span>
          <select data-company-channel-status>${adminDbChannelStatusOptions(status)}</select>
        </label>
        <label>
          <span>URL</span>
          <input type="url" data-company-channel-url value="${escapeHtml(entry.url || "")}" placeholder="${escapeHtml(searchUrl || "확인 URL")}">
        </label>
        <label>
          <span>가격</span>
          <input type="text" data-company-channel-price value="${escapeHtml(entry.price || "")}" placeholder="예: 120,000원">
        </label>
        <label>
          <span>메모</span>
          <input type="text" data-company-channel-note value="${escapeHtml(entry.note || "")}" placeholder="예: 유사명 확인 필요">
        </label>
      </div>
      <div class="admin-db-channel-actions">
        ${searchUrl ? `<a href="${escapeHtml(searchUrl)}" target="_blank" rel="noreferrer">검색 열기</a>` : ""}
        <button type="button" data-company-channel-save>저장</button>
        <button type="button" data-company-channel-clear>삭제</button>
      </div>
    </div>
  `;
}

function adminDbChannelExposurePanel(row = {}) {
  const company = row.company || {};
  if (!company.companyId) return "";
  const channels = row.metrics?.channels || {};
  const checkedCount = Object.values(channels.statuses || {}).filter(Boolean).length;
  const exposedCount = ADMIN_DB_MANAGED_CHANNELS.filter(([key]) => channels[key]).length;
  const manualCount = channels.manualNeeded || 0;
  return `
    <section class="admin-db-channel-panel" data-surface="light">
      <div class="admin-db-channel-head">
        <div>
          <span>채널 노출 확인</span>
          <strong>네이버 외 OTA 노출을 업체별로 정리합니다.</strong>
          <small>야놀자·떠나요·ONDA는 자동 확인, 여기어때·Airbnb는 검색 링크 기반 수동 확인으로 저장합니다.</small>
        </div>
        <button type="button" data-company-channel-auto data-company-id="${escapeHtml(company.companyId || "")}">자동 확인</button>
      </div>
      <div class="admin-db-channel-summary">
        ${[
          ["확인 채널", checkedCount, "저장된 상태"],
          ["노출", exposedCount, "네이버 제외"],
          ["확인필요", manualCount, "수동/차단 포함"]
        ].map(([label, value, note]) => `
          <article data-surface="light">
            <span>${escapeHtml(label)}</span>
            <strong>${fmtNumber(value)}</strong>
            <small>${escapeHtml(note)}</small>
          </article>
        `).join("")}
      </div>
      <div class="admin-db-channel-list">
        ${ADMIN_DB_MANAGED_CHANNELS.map(([key, label]) => adminDbChannelExposureForm(row, key, label)).join("")}
      </div>
    </section>
  `;
}

function adminDbCollectionPanel(rows = []) {
  const confirmRows = adminDbConfirmCollectRows(rows);
  const countByKey = (key) => rows.filter((row) => row.metrics?.collection?.key === key).length;
  return `
    <section class="admin-db-collect-panel">
      <div class="admin-db-collect-head">
        <div>
          <span>수집 구분</span>
          <strong>자동수집과 관리자 확인 수집을 분리합니다</strong>
          <small>신뢰도가 낮거나 표본이 부족한 업체는 확인 수집 대상으로 묶어 수량·가격·예약율 근거를 보강합니다.</small>
        </div>
        <button type="button" data-admin-db-source-link="confirm_needed">확인 수집만 보기</button>
      </div>
      <div class="admin-db-collect-metrics">
        ${[
          ["확인 수집 필요", confirmRows.length, "신뢰도 보강 대상", "hot", "confirm_needed"],
          ["관리자 검수", countByKey("admin_verified"), "판단·보정 완료", "good", "admin_verified"],
          ["자동수집", countByKey("auto_collected"), "기본 수집 누적", "neutral", "auto_collected"],
          ["B2B 수집", countByKey("b2b_collected"), "고객 검색 유입", "watch", "b2b_collected"]
        ].map(([label, count, note, tone, key]) => `
          <button type="button" class="${escapeHtml(tone)}" data-admin-db-source-link="${escapeHtml(key)}">
            <span>${escapeHtml(label)}</span>
            <strong>${fmtNumber(count)}</strong>
            <small>${escapeHtml(note)}</small>
          </button>
        `).join("")}
      </div>
      <div class="admin-db-collect-list">
        ${confirmRows.length ? confirmRows.slice(0, 5).map((row) => {
          const company = row.company || {};
          const metrics = row.metrics || {};
          const collection = metrics.collection || {};
          return `
            <article class="${escapeHtml(collection.tone || "hot")}">
              <div>
                <strong>${escapeHtml(company.primaryName || "업체명 확인")}</strong>
                <small>${escapeHtml([row.provinceLabel, row.localityLabel, metrics.rank ? `${fmtNumber(metrics.rank)}위` : "", collection.note].filter(Boolean).join(" · "))}</small>
                <p>${escapeHtml(collection.detail || adminDbWorkReason(row))}</p>
                <span class="admin-db-collect-planline">${escapeHtml(adminDbConfirmPlanLine(row))}</span>
              </div>
              <div>
                ${adminDbCollectionChip(collection)}
                <button type="button" data-queue-recrawl-company="${escapeHtml(company.companyId || "")}" data-queue-recrawl-source="admin_confirm_collect" data-queue-recrawl-autostart="1">확인 수집</button>
                <button type="button" data-admin-db-company-select="${escapeHtml(company.companyId || "")}">상세 수정</button>
              </div>
            </article>
          `;
        }).join("") : `<p class="admin-db-more">현재 필터 조건에서 확인 수집이 필요한 업체가 없습니다.</p>`}
      </div>
    </section>
  `;
}

function adminDbSelectedRow(rows = []) {
  if (!rows.length) return null;
  const selectedId = state.adminDbSelectedCompanyId || "";
  const selected = selectedId ? rows.find((row) => row.company?.companyId === selectedId) : null;
  return selected || adminDbWorkRows(rows)[0] || rows[0] || null;
}

function adminDbSelectedDetailPanel(rows = []) {
  const row = adminDbSelectedRow(rows);
  if (!row) {
    return `
      <section class="admin-db-selected-panel empty">
        <strong>상세 수정 대기</strong>
        <p>필터 조건에 맞는 업체가 없습니다.</p>
      </section>
    `;
  }
  const company = row.company || {};
  const metrics = row.metrics || {};
  const workType = metrics.workType || { label: "확인 필요", tone: "watch" };
  const issues = metrics.issues?.length ? metrics.issues : [adminDbWorkReason(row)];
  const b2bCards = adminDbB2BMetricCards(row);
  const internalCards = adminDbInternalJudgmentCards(row);
  const requiredChannels = adminDbRequiredCheckChannels(row);
  const selectedId = company.companyId || "";
  const correctionBody = adminDbQuickCorrectionPanel(row);
  const channelBody = adminDbChannelExposurePanel(row);
  const collectBody = [
    adminDbConfirmCollectPlanHtml(row),
    adminDbRecheckOutcomeHtml(row)
  ].filter(Boolean).join("");
  const nextAction = adminDbSelectedNextAction(row, requiredChannels);
  const needsCollectAction = Boolean(nextAction.runCollect || collectBody || metrics.collection?.needsConfirm || requiredChannels.length);
  const channelNeedsReview = Boolean(metrics.channels?.manualNeeded || requiredChannels.some((channel) => ["OTA", "네이버 쿠폰"].includes(channel)));
  const reviewBody = `
    <div class="admin-db-selected-review">
      <div>
        <strong>검수 상태</strong>
        <small>검수 상태와 메모는 업체 관리에 함께 반영됩니다.</small>
      </div>
      ${companyReviewActionsHtml(company, true, "admin_db_detail")}
    </div>
  `;
  state.adminDbSelectedCompanyId = selectedId;
  return `
    <section class="admin-db-selected-panel ${escapeHtml(workType.tone || "watch")}" data-admin-db-selected-company="${escapeHtml(selectedId)}">
      <div class="admin-db-selected-head">
        <div>
          <span>업체 상세</span>
          <strong>${escapeHtml(company.primaryName || "업체명 확인")}</strong>
          <small>${escapeHtml([row.provinceLabel, row.localityLabel, metrics.category?.label, metrics.sourceLabel].filter(Boolean).join(" · "))}</small>
        </div>
        <mark>${escapeHtml(workType.label || "확인 필요")}</mark>
      </div>
      ${adminDbSelectedAppliedValuesHtml(row)}
      ${adminDbSelectedDecisionPanel(row, issues, requiredChannels)}
      <section class="admin-db-selected-readonly" aria-label="읽기 전용 지표">
        ${adminDbSelectedFoldBlock({
          label: "사업자 화면 기준",
          title: "노출·예약율·예상매출·상품·채널",
          note: "공개 지표",
          body: `<div class="admin-db-selected-grid">${b2bCards.map(adminDbSelectedMetricCard).join("")}</div>`,
          open: nextAction.foldKey === "b2b",
          foldKey: "b2b"
        })}
        ${adminDbSelectedFoldBlock({
          label: "검수 기준",
          title: "신뢰도·보정·확인 채널·처리 상태",
          note: "관리자용",
          body: `<div class="admin-db-selected-grid internal">${internalCards.map(adminDbSelectedMetricCard).join("")}</div>`,
          foldKey: "internal"
        })}
      </section>
      <section class="admin-db-selected-workbench" aria-label="수정과 처리">
        ${adminDbSelectedSectionHead("수정·처리", "필요한 작업만 펼쳐 실행합니다", "")}
        <div class="admin-db-selected-actions primary">
          ${needsCollectAction ? `<button type="button" data-queue-recrawl-company="${escapeHtml(selectedId)}" data-queue-recrawl-source="admin_db_detail" data-queue-recrawl-autostart="1">확인 수집 실행</button>` : ""}
          <button type="button" data-admin-db-open-fold="correction">기준값 수정</button>
          <button type="button" data-admin-db-open-fold="channel">채널 확인</button>
          <button type="button" data-admin-db-view-link="list">목록</button>
        </div>
        <div class="admin-db-selected-workbench-stack">
          ${adminDbSelectedFoldBlock({
            label: "1. 검수 상태",
            title: "검수 상태와 메모 저장",
            note: nextAction.foldKey === "review" ? "먼저 처리" : "상태 저장",
            body: reviewBody,
            open: nextAction.foldKey === "review",
            tone: "review",
            foldKey: "review"
          })}
          ${adminDbSelectedFoldBlock({
            label: "2. 기준값 수정",
            title: "지역·채널·쿠폰·수량/가격 수정",
            note: nextAction.foldKey === "correction" ? "먼저 처리" : "필요할 때 열기",
            body: correctionBody,
            open: nextAction.foldKey === "correction",
            tone: "edit",
            foldKey: "correction"
          })}
          ${adminDbSelectedFoldBlock({
            label: "3. 채널 확인",
            title: "네이버·OTA 노출과 URL 저장",
            note: channelNeedsReview ? "확인 필요" : "채널별 확인",
            body: channelBody,
            open: channelNeedsReview && nextAction.foldKey !== "correction",
            tone: "channel",
            foldKey: "channel"
          })}
          ${adminDbSelectedFoldBlock({
            label: "4. 확인 수집",
            title: "재수집 조건과 이전/최신 비교",
            note: nextAction.foldKey === "collect" ? "먼저 처리" : (collectBody ? "필요 시 실행" : "현재 추가 없음"),
            body: collectBody,
            open: nextAction.foldKey === "collect",
            tone: "collect",
            foldKey: "collect"
          })}
        </div>
      </section>
    </section>
  `;
}

function adminDbCompanyRow(row = {}, options = {}) {
  const company = row.company || {};
  const metrics = row.metrics || {};
  const workType = metrics.workType || { label: "검수 대기", tone: "watch" };
  const rateText = Number.isFinite(metrics.rate) ? fmtRate(metrics.rate) : "예약율 확인";
  const rankText = metrics.rank ? `${fmtNumber(metrics.rank)}위` : "순위 대기";
  const selected = state.adminDbSelectedCompanyId && state.adminDbSelectedCompanyId === company.companyId;
  const reason = adminDbWorkReason(row);
  const listIndex = Number(options.index || 0);
  return `
    <article class="admin-db-company ${escapeHtml(workType.tone || "neutral")} ${selected ? "selected" : ""}" data-surface="dark" data-admin-db-company-card-select="${escapeHtml(company.companyId || "")}">
      <div class="admin-db-company-main">
        <div class="admin-db-company-title-row">
          ${listIndex ? `<span class="admin-db-company-index">${fmtNumber(listIndex)}</span>` : ""}
          <strong title="${escapeHtml(company.primaryName || "업체명 확인")}">${escapeHtml(company.primaryName || "업체명 확인")}</strong>
        </div>
        <small>${escapeHtml(row.provinceLabel || "미분류")} · ${escapeHtml(row.localityLabel || "지역 미확인")} · ${escapeHtml(metrics.category?.label || "숙박업")}</small>
        <p class="admin-db-company-reason">${escapeHtml(reason)}</p>
      </div>
      <div class="admin-db-company-values" data-surface="dark">
        <span><small>노출</small><b>${escapeHtml(rankText)}</b></span>
        <span><small>7일 매출</small><b>${escapeHtml(fmtWon(metrics.revenue || 0))}</b></span>
        <span><small>예약율</small><b>${escapeHtml(rateText)}</b></span>
        <span><small>신뢰도</small><b>${escapeHtml(metrics.confidenceGrade || "대기")}</b></span>
      </div>
      <div class="admin-db-company-tags">
        ${adminDbCompanyCompactTags(row)}
      </div>
      <div class="admin-db-company-action">
        <button class="primary" type="button" data-admin-db-company-select="${escapeHtml(company.companyId || "")}">상세·수정</button>
        ${metrics.collection?.needsConfirm ? `<button type="button" data-queue-recrawl-company="${escapeHtml(company.companyId || "")}" data-queue-recrawl-source="admin_db" data-queue-recrawl-autostart="1">확인 수집</button>` : ""}
      </div>
    </article>
  `;
}

function adminDbRegionGroup(region = {}, index = 0, context = {}) {
  const rows = region.rows || [];
  const lowConfidence = rows.filter((row) => row.metrics.lowConfidence || row.metrics.confidenceScore <= 2).length;
  const manualCount = rows.filter((row) => row.metrics.manualCorrection).length;
  const shouldOpen = Boolean(context.forceOpen || context.openRegions);
  return `
    <details class="admin-db-region" ${shouldOpen ? "open" : ""}>
      <summary>
        <div>
          <strong>${escapeHtml(region.label || "지역 미확인")}</strong>
          <small>${fmtNumber(rows.length)}개 업체 · 낮은 신뢰 ${fmtNumber(lowConfidence)} · 관리자 보정 ${fmtNumber(manualCount)}</small>
        </div>
        <span>${fmtNumber(rows.length)}개 · 업체보기</span>
      </summary>
      <div class="admin-db-company-list">
        ${rows.slice(0, 30).map(adminDbCompanyRow).join("")}
        ${rows.length > 30 ? `<p class="admin-db-more">상위 30개만 표시 중입니다. 검색어 또는 필터로 좁혀 확인하세요.</p>` : ""}
      </div>
    </details>
  `;
}

function adminDbProvinceGroup(province = {}, index = 0, context = {}) {
  const rows = province.rows || [];
  const regionCount = (province.regions || []).length;
  const revenueRows = rows.filter((row) => row.metrics.revenue > 0);
  const averageRevenue = revenueRows.length
    ? revenueRows.reduce((sum, row) => sum + row.metrics.revenue, 0) / revenueRows.length
    : 0;
  const shouldOpen = Boolean(context.forceOpen || context.openProvinces);
  return `
    <details class="admin-db-province" ${shouldOpen ? "open" : ""}>
      <summary>
        <div>
          <strong>${escapeHtml(province.label || "미분류")}</strong>
          <small>${fmtNumber(regionCount)}개 지역 · ${fmtNumber(rows.length)}개 업체 · 평균 ${fmtWon(averageRevenue)}</small>
        </div>
        <span>시군구 보기</span>
      </summary>
      <div class="admin-db-region-list">
        ${(province.regions || []).map((region, regionIndex) => adminDbRegionGroup(region, regionIndex, context)).join("")}
      </div>
    </details>
  `;
}

function adminDbFlatListPanel(rows = [], allRows = [], filters = {}) {
  const pageSize = 12;
  const pageKey = JSON.stringify({
    query: filters.query || "",
    province: filters.province || "all",
    region: filters.region || "all",
    sort: filters.sort || "name",
    category: filters.category || "all",
    status: filters.status || "all",
    confidence: filters.confidence || "all",
    source: filters.source || "all",
    ota: filters.ota || "all",
    feature: filters.feature || "all",
    quality: filters.quality || "all"
  });
  if (state.adminDbListPageKey !== pageKey) {
    state.adminDbListPageKey = pageKey;
    state.adminDbListPage = 1;
  }
  const totalPages = Math.max(1, Math.ceil(rows.length / pageSize));
  const page = Math.max(1, Math.min(totalPages, Number(state.adminDbListPage || 1)));
  state.adminDbListPage = page;
  const startIndex = (page - 1) * pageSize;
  const shown = rows.slice(startIndex, startIndex + pageSize);
  const rangeStart = rows.length ? startIndex + 1 : 0;
  const rangeEnd = rows.length ? Math.min(rows.length, startIndex + shown.length) : 0;
  const scopeText = [
    filters.province !== "all" ? "광역 선택" : "",
    filters.region !== "all" ? "지역 선택" : "",
    filters.category !== "all" ? "카테고리 선택" : "",
    filters.status !== "all" ? "관리 상태 선택" : "",
    filters.confidence !== "all" ? "신뢰도 선택" : "",
    filters.ota !== "all" ? "채널 선택" : "",
    filters.feature !== "all" ? "시설 선택" : "",
    filters.quality !== "all" ? "분류 점검" : ""
  ].filter(Boolean).join(" · ") || "전체 조건";
  const sortLabels = {
    name: "업체 가나다순",
    rank: "노출순",
    revenue_desc: "매출 높은순",
    revenue_asc: "매출 낮은순",
    rate_desc: "예약율 높은순",
    rate_asc: "예약율 낮은순",
    rooms_desc: "객실수 많은순",
    rooms_asc: "객실수 적은순",
    confidence_low: "낮은 신뢰도순",
    latest_desc: "최근 수집일순"
  };
  const sortText = sortLabels[filters.sort] || "업체 가나다순";
  return `
    <section class="admin-db-flat-list" data-surface="dark">
      <div class="admin-db-flat-head">
        <div>
          <span>업체 리스트</span>
          <strong>${escapeHtml(sortText)}</strong>
          <small>${escapeHtml(scopeText)} · ${fmtNumber(rows.length)}/${fmtNumber(allRows.length)}개 업체 · ${fmtNumber(rangeStart)}-${fmtNumber(rangeEnd)} 표시</small>
        </div>
        <mark>${fmtNumber(page)} / ${fmtNumber(totalPages)}쪽</mark>
      </div>
      <div class="admin-db-list-guide" aria-label="업체 리스트 기준">
        <span>페이지당 ${fmtNumber(pageSize)}개</span>
        <span>상세는 선택 후 확인</span>
      </div>
      <div class="admin-db-company-list flat">
        ${shown.length ? shown.map((row, index) => adminDbCompanyRow(row, { index: startIndex + index + 1 })).join("") : `<div class="admin-console-empty">조건에 맞는 업체가 없습니다.</div>`}
      </div>
      <div class="admin-db-pagination">
        <button type="button" data-admin-db-list-page="${page - 1}" ${page <= 1 ? "disabled" : ""}>이전</button>
        <span>${fmtNumber(rangeStart)}-${fmtNumber(rangeEnd)} / ${fmtNumber(rows.length)}개</span>
        <button type="button" data-admin-db-list-page="${page + 1}" ${page >= totalPages ? "disabled" : ""}>다음</button>
      </div>
    </section>
  `;
}

