      state.adminDbOpsOpen = true;
      renderAdminConsoleDashboard();
      window.requestAnimationFrame(() => {
        document.querySelector(".admin-db-audit-detail")?.scrollIntoView({ behavior: "smooth", block: "nearest" });
      });
